
if (window.FASOTOK_MAIN_SCRIPT_LOADED) {
  console.warn('FasoTok : script principal déjà chargé.');
} else {
  window.FASOTOK_MAIN_SCRIPT_LOADED = true;

  document.addEventListener('DOMContentLoaded', () => {
 
    const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
  const loginForm = $('#login-form');
  const registerForm = $('#register-form');
  const authOverlay = $('#auth-overlay');
  const logoutBtn = $('#deconnexion-fasotok');
  const videoFeed = $('#video-feed');
  const emptyMsg = $('#empty-feed-msg');
  const fileSelector = $('#fasotok-selecteur');
  const createMenu = $('#create-menu');
  const createVideoBtn = $('#create-video-btn');
  const createPhotoBtn = $('#create-photo-btn');
  const createDraftBtn = $('#create-draft-btn');
  const createLiveBtn = $('#create-live-btn');
  let totalLikes = (() => { try { return JSON.parse(localStorage.getItem('fasotok_liked_posts') || '[]').length; } catch { return 0; } })();

  function notify(message) {
    const toast = $('#fasotok-toast');
    if (!toast) { alert(message); return; }
    toast.textContent = message;
    toast.classList.add('visible');
    clearTimeout(notify.timer);
    notify.timer = setTimeout(() => toast.classList.remove('visible'), 2600);
  }
  window.fasotokNotify = notify;

  function majProfil(pseudo) {
    const clean = String(pseudo || '').replace(/^@+/, '');
    $$('.profile-username, .profile-header h2, #profil-titre').forEach(el => {
      el.textContent = '@' + clean;
    });
    const name = $('#profile-display-name');
    if (name) name.textContent = clean;
  }

  async function hashPassword(password) {
    if (!window.crypto?.subtle) throw new Error('La protection locale des mots de passe nécessite HTTPS.');
    const bytes = new TextEncoder().encode(password);
    const digest = await crypto.subtle.digest('SHA-256', bytes);
    return [...new Uint8Array(digest)].map(v => v.toString(16).padStart(2, '0')).join('');
  }

  const account = (() => {
    try { return JSON.parse(localStorage.getItem('fasotok_account_v1') || 'null'); }
    catch { return null; }
  })();
  const userSaved = localStorage.getItem('fasotok_user');
  if (userSaved) {
    if (authOverlay) authOverlay.hidden = true;
    majProfil(userSaved);
  }

  if (registerForm) registerForm.addEventListener('submit', async e => {
    e.preventDefault();
    const user = $('#register-username')?.value.trim();
    const pass = $('#register-password')?.value || '';
    const confirm = $('#register-confirm-password')?.value || '';
    if (!user || user.length < 3) return notify('Choisis un pseudo de 3 caractères minimum.');
    if (pass.length < 8) return notify('Choisis un code secret de 8 caractères minimum.');
    if (pass !== confirm) return notify('Les deux codes secrets ne correspondent pas.');
    let passwordHash;
    try { passwordHash = await hashPassword(pass); } catch (err) { return notify(err.message); }
    localStorage.setItem('fasotok_account_v1', JSON.stringify({ username: user, passwordHash }));
    localStorage.setItem('fasotok_user', user);
    if (authOverlay) authOverlay.hidden = true;
    majProfil(user);
    notify('Compte local créé sur cet appareil.');
  });

  if (loginForm) loginForm.addEventListener('submit', async e => {
    e.preventDefault();
    const user = $('#login-username')?.value.trim();
    const pass = $('#login-password')?.value || '';
    const saved = (() => { try { return JSON.parse(localStorage.getItem('fasotok_account_v1') || 'null'); } catch { return null; } })();
    if (saved) {
      let passwordHash;
      try { passwordHash = await hashPassword(pass); } catch (err) { return notify(err.message); }
      if (saved.username.toLowerCase() !== user.toLowerCase() || saved.passwordHash !== passwordHash) {
        return notify('Pseudo ou code secret incorrect.');
      }
    } else if (!user || !pass) return notify('Renseigne ton pseudo et ton code secret.');
    localStorage.setItem('fasotok_user', user);
    if (authOverlay) authOverlay.hidden = true;
    majProfil(user);
    notify('Connexion locale réussie.');
  });

  if (logoutBtn) logoutBtn.addEventListener('click', () => {
    localStorage.removeItem('fasotok_user');
    if (authOverlay) authOverlay.hidden = false;
  });

  const navButtons = $$('.nav-item[data-page]');
  const pageSections = $$('.page-section');
  function switchPage(pageId) {
    pageSections.forEach(sec => { sec.hidden = sec.id !== pageId + '-page'; });
    navButtons.forEach(btn => btn.classList.toggle('active-nav', btn.dataset.page === pageId));
    document.body.dataset.page = pageId;
    if (createMenu) createMenu.hidden = true;
    if (pageId === 'home') pauseVideosOutsideHome();
  }
  window.fasotokSwitchPage = switchPage;
  navButtons.forEach(btn => btn.addEventListener('click', () => switchPage(btn.dataset.page)));

  function pauseVideosOutsideHome() {
    if (document.body.dataset.page !== 'home') $$('video').forEach(v => v.pause());
  }

  let observer = null;
  if ('IntersectionObserver' in window) {
    observer = new IntersectionObserver(entries => entries.forEach(entry => {
      const video = entry.target.querySelector('video');
      if (!video) return;
      if (entry.isIntersecting && document.body.dataset.page === 'home') {
        video.play().catch(() => { video.muted = true; video.play().catch(() => {}); });
      } else video.pause();
    }), { threshold: 0.65 });
  }

  const DB_NAME = 'fasotok-local-v1';
  function openMediaDB() {
    return new Promise((resolve, reject) => {
      if (!('indexedDB' in window)) return reject(new Error('IndexedDB indisponible'));
      const request = indexedDB.open(DB_NAME, 1);
      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains('posts')) db.createObjectStore('posts', { keyPath: 'id' });
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }
  async function savePostBlob(post) {
    const db = await openMediaDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction('posts', 'readwrite');
      tx.objectStore('posts').put(post);
      tx.oncomplete = () => { db.close(); resolve(); };
      tx.onerror = () => { db.close(); reject(tx.error); };
    });
  }
  async function loadSavedPosts() {
    try {
      const db = await openMediaDB();
      const posts = await new Promise((resolve, reject) => {
        const req = db.transaction('posts', 'readonly').objectStore('posts').getAll();
        req.onsuccess = () => resolve(req.result || []);
        req.onerror = () => reject(req.error);
      });
      db.close();
      posts.filter(post => !post.draft).sort((a, b) => b.createdAt - a.createdAt).forEach(post => {
        const url = URL.createObjectURL(post.blob);
        creerVideo(post.author, post.caption, url, post.kind === 'video', post.likes || 0, post.id, false);
      });
      renderDrafts(posts.filter(post => post.draft));
    } catch (err) { console.warn('Chargement local des publications impossible:', err); }
  }

  function renderDrafts(drafts) {
    const wrap = $('#drafts-list'); if (!wrap) return;
    wrap.replaceChildren();
    if (!drafts.length) { const empty = document.createElement('p'); empty.className = 'muted'; empty.textContent = 'Aucun brouillon enregistré pour le moment.'; wrap.appendChild(empty); return; }
    drafts.sort((a,b) => b.createdAt - a.createdAt).forEach(draft => {
      const row = document.createElement('div'); row.className = 'draft-row';
      const info = document.createElement('div');
      const title = document.createElement('strong'); title.textContent = draft.kind === 'video' ? '🎬 Brouillon vidéo' : '🖼️ Brouillon photo';
      const caption = document.createElement('p'); caption.textContent = draft.caption;
      info.append(title, caption);
      const actions = document.createElement('div'); actions.className = 'draft-actions';
      const publish = document.createElement('button'); publish.type = 'button'; publish.textContent = 'Publier';
      publish.addEventListener('click', async () => {
        draft.draft = false; await savePostBlob(draft); const url = URL.createObjectURL(draft.blob);
        creerVideo(draft.author, draft.caption, url, draft.kind === 'video', draft.likes || 0, draft.id, false);
        renderDrafts(drafts.filter(item => item.id !== draft.id)); switchPage('home'); notify('Publication ajoutée au fil local.');
      });
      const remove = document.createElement('button'); remove.type = 'button'; remove.textContent = 'Supprimer';
      remove.addEventListener('click', async () => { await deleteSavedPost(draft.id); renderDrafts(drafts.filter(item => item.id !== draft.id)); });
      actions.append(publish, remove); row.append(info, actions); wrap.appendChild(row);
    });
  }

  async function deleteSavedPost(id) {
    const db = await openMediaDB();
    await new Promise((resolve, reject) => { const tx = db.transaction('posts', 'readwrite'); tx.objectStore('posts').delete(id); tx.oncomplete = resolve; tx.onerror = () => reject(tx.error); });
    db.close();
  }

  function creerVideo(auteur, desc, url, isVideo, likes = 0, postId = 'post-' + Date.now(), persist = true) {
    if (!videoFeed) return;
    if (emptyMsg) emptyMsg.hidden = true;
    const card = document.createElement('article');
    card.className = 'video-item';
    card.dataset.postId = postId;
    const media = isVideo ? document.createElement('video') : document.createElement('img');
    media.className = 'post-media';
    media.src = url;
    if (isVideo) { media.loop = true; media.playsInline = true; media.muted = true; media.controls = false; }
    else { media.alt = 'Publication FasoTok'; }
    card.appendChild(media);

    const info = document.createElement('div');
    info.className = 'post-caption';
    const author = document.createElement('strong'); author.textContent = '@' + auteur;
    const caption = document.createElement('p'); caption.textContent = desc;
    info.append(author, caption);
    card.appendChild(info);

    const actions = document.createElement('div'); actions.className = 'post-actions';
    const likeBtn = document.createElement('button'); likeBtn.type = 'button'; likeBtn.className = 'post-action like-btn';
    const savedLikes = JSON.parse(localStorage.getItem('fasotok_liked_posts') || '[]');
    const likeCounts = JSON.parse(localStorage.getItem('fasotok_like_counts') || '{}');
    let liked = savedLikes.includes(postId);
    let count = Number(likeCounts[postId] ?? likes) || 0;
    likeBtn.textContent = (liked ? '❤️' : '🤍') + ' ' + count;
    const commentBtn = document.createElement('button'); commentBtn.type = 'button'; commentBtn.className = 'post-action comment-btn'; commentBtn.textContent = '💬 Commenter';
    const saveBtn = document.createElement('button'); saveBtn.type = 'button'; saveBtn.className = 'post-action save-btn'; saveBtn.textContent = '🔖 Enregistrer';
    const shareBtn = document.createElement('button'); shareBtn.type = 'button'; shareBtn.className = 'post-action share-btn'; shareBtn.textContent = '↗ Partager';
    actions.append(likeBtn, commentBtn, saveBtn, shareBtn); card.appendChild(actions);

    likeBtn.addEventListener('click', () => {
      liked = !liked; count = Math.max(0, count + (liked ? 1 : -1));
      likeBtn.textContent = (liked ? '❤️ ' : '🤍 ') + count;
      const list = new Set(JSON.parse(localStorage.getItem('fasotok_liked_posts') || '[]'));
      liked ? list.add(postId) : list.delete(postId);
      localStorage.setItem('fasotok_liked_posts', JSON.stringify([...list]));
      const counts = JSON.parse(localStorage.getItem('fasotok_like_counts') || '{}'); counts[postId] = count; localStorage.setItem('fasotok_like_counts', JSON.stringify(counts));
      totalLikes = Math.max(0, totalLikes + (liked ? 1 : -1));
      const stat = $('#total-likes-count'); if (stat) stat.textContent = totalLikes;
    });
    commentBtn.addEventListener('click', () => {
      const text = prompt('Écris ton commentaire :');
      if (!text?.trim()) return;
      const key = 'fasotok_comments_' + postId;
      const comments = JSON.parse(localStorage.getItem(key) || '[]');
      comments.push({ author: localStorage.getItem('fasotok_user') || 'Visiteur', text: text.trim(), date: Date.now() });
      localStorage.setItem(key, JSON.stringify(comments));
      notify('Commentaire enregistré sur cet appareil.');
    });
    saveBtn.addEventListener('click', () => {
      const saved = new Set(JSON.parse(localStorage.getItem('fasotok_saved_posts') || '[]'));
      saved.add(postId); localStorage.setItem('fasotok_saved_posts', JSON.stringify([...saved]));
      saveBtn.textContent = '⭐ Enregistré';
    });
    shareBtn.addEventListener('click', async () => {
      const shareData = { title: 'FasoTok', text: `Découvre la publication de @${auteur} sur FasoTok`, url: location.href };
      try { if (navigator.share) await navigator.share(shareData); else if (navigator.clipboard) { await navigator.clipboard.writeText(location.href); notify('Lien copié.'); } else prompt('Copie le lien :', location.href); } catch {}
    });

    media.addEventListener('click', () => { if (isVideo) media.paused ? media.play().catch(() => {}) : media.pause(); });
    videoFeed.prepend(card);
    if (observer && isVideo) observer.observe(card);
    return card;
  }
  window.creerFasoTokVideo = creerVideo;

  async function publierFichier(file, draftOnly = false) {
    if (!file) return;
    const kind = file.type.startsWith('video/') ? 'video' : file.type.startsWith('image/') ? 'image' : '';
    if (!kind) return notify('Choisis une image ou une vidéo.');
    const id = 'ft-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7);
    const post = { id, author: localStorage.getItem('fasotok_user') || 'FasoCreateur', caption: $('#create-caption')?.value.trim() || 'Ma publication sur FasoTok 🇧🇫', kind, blob: file, likes: 0, createdAt: Date.now(), draft: draftOnly };
    let persisted = true;
    try { await savePostBlob(post); } catch (err) { persisted = false; console.warn(err); }
    if (draftOnly) { notify(persisted ? 'Brouillon enregistré sur cet appareil.' : 'Le stockage local est indisponible : brouillon non conservé.'); return; }
    const url = URL.createObjectURL(file);
    creerVideo(post.author, post.caption, url, kind === 'video', 0, id, false);
    if ($('#create-caption')) $('#create-caption').value = '';
    if (createMenu) createMenu.hidden = true;
    switchPage('home');
    notify(persisted ? 'Publication ajoutée et conservée sur cet appareil.' : 'Publication ajoutée pour cette session seulement.');
  }

  if ($('#publish-btn') && createMenu) $('#publish-btn').addEventListener('click', () => { createMenu.hidden = !createMenu.hidden; });
  if (createVideoBtn && fileSelector) createVideoBtn.addEventListener('click', () => { fileSelector.dataset.saveDraft = 'false'; fileSelector.accept = 'video/*'; fileSelector.click(); });
  if (createPhotoBtn && fileSelector) createPhotoBtn.addEventListener('click', () => { fileSelector.dataset.saveDraft = 'false'; fileSelector.accept = 'image/*'; fileSelector.click(); });
  if (createDraftBtn && fileSelector) createDraftBtn.addEventListener('click', () => { fileSelector.dataset.saveDraft = 'true'; fileSelector.accept = 'video/*,image/*'; fileSelector.click(); });
  if (createLiveBtn) createLiveBtn.addEventListener('click', () => notify('Le direct public sera activé après la mise en place du serveur et des protections de diffusion.'));
  if (fileSelector) fileSelector.addEventListener('change', async e => {
    const file = e.target.files?.[0];
    if (!file) return;
    const draftOnly = fileSelector.dataset.saveDraft === 'true';
    fileSelector.dataset.saveDraft = 'false';
    await publierFichier(file, draftOnly);
    fileSelector.value = '';
  });

  // Recherche locale : créateurs et publications déjà chargés sur l'appareil.
  const searchInput = $('#discover-search');
  const searchResults = $('#discover-results');
  if (searchInput && searchResults) searchInput.addEventListener('input', () => {
    const q = searchInput.value.trim().toLowerCase();
    searchResults.replaceChildren();
    if (!q) { searchResults.textContent = 'Recherche dans les contenus présents sur cet appareil.'; return; }
    const matches = $$('.video-item').filter(card => card.textContent.toLowerCase().includes(q));
    if (!matches.length) { searchResults.textContent = 'Aucun résultat local pour le moment.'; return; }
    matches.forEach(card => { const item = document.createElement('button'); item.className = 'result-card'; item.type = 'button'; item.textContent = card.querySelector('.post-caption')?.textContent || 'Publication'; item.onclick = () => switchPage('home'); searchResults.appendChild(item); });
  });

  const assistantForm = $('#assistant-form');
  if (assistantForm) assistantForm.addEventListener('submit', e => {
    e.preventDefault(); const input = $('#assistant-question'); const box = $('#assistant-reponses'); const q = input?.value.trim();
    if (!q || !box) return;
    const line = document.createElement('p'); line.textContent = 'Toi : ' + q; box.appendChild(line);
    const answer = document.createElement('p'); answer.textContent = 'Assistant local : je peux enregistrer ta question, mais les réponses intelligentes nécessiteront un service IA connecté. Pour le moment, je fonctionne hors ligne.'; box.appendChild(answer);
    input.value = '';
  });

  const langSelect = $('#fasotok-langue');
  if (langSelect) {
    langSelect.value = localStorage.getItem('fasotok-langue') || 'fr';
    langSelect.addEventListener('change', () => {
      localStorage.setItem('fasotok-langue', langSelect.value);
      const msg = $('#langue-message'); if (msg) msg.textContent = 'Langue sélectionnée : ' + langSelect.options[langSelect.selectedIndex].text;
    });
  }
  const editProfile = $('#modifier-profil-btn');
  if (editProfile) editProfile.addEventListener('click', () => {
    const current = localStorage.getItem('fasotok_user') || '';
    const next = prompt('Nouveau pseudo :', current);
    if (!next?.trim()) return;
    const clean = next.trim().replace(/^@+/, '');
    localStorage.setItem('fasotok_user', clean);
    const saved = JSON.parse(localStorage.getItem('fasotok_account_v1') || 'null');
    if (saved) { saved.username = clean; localStorage.setItem('fasotok_account_v1', JSON.stringify(saved)); }
    majProfil(clean);
  });

  // Onglets du fil.
  $$('[data-feed-tab]').forEach(tab => tab.addEventListener('click', () => {
    $$('[data-feed-tab]').forEach(t => t.classList.toggle('active', t === tab));
    const type = tab.dataset.feedTab;
    const livePanel = $('#live-placeholder');
    if (livePanel) livePanel.hidden = type !== 'live';
    if (videoFeed) videoFeed.hidden = type === 'live';
    if (type === 'live') notify('Les diffusions en direct seront disponibles après le serveur de diffusion.');
    else if (type === 'following') notify('Le fil Suivis affichera les créateurs suivis lorsque les comptes seront connectés.');
  }));

      loadSavedPosts();
    if (document.body.dataset.page === '') document.body.dataset.page = 'home';
  });
}
// --- 6. DOUBLE-TAP LIKE ❤️ ET DISQUE MUSICAL QUI TOURNE 🎵 ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  // Ajouter l'animation CSS pour le disque qui tourne et le grand cœur
  const styleAnim = document.createElement('style');
  styleAnim.textContent = `
    @keyframes tournerDisque {
      from { transform: rotate(0deg); }
      to { transform: rotate(360deg); }
    }
    @keyframes popCoeur {
      0% { transform: translate(-50%, -50%) scale(0); opacity: 1; }
      50% { transform: translate(-50%, -50%) scale(1.3); opacity: 1; }
      100% { transform: translate(-50%, -50%) scale(1); opacity: 0; }
    }
    .disque-tiktok {
      width: 42px;
      height: 42px;
      border-radius: 50%;
      background: radial-gradient(circle, #fe2c55 20%, #111 25%, #333 60%, #000 100%);
      border: 3px solid #222;
      display: flex;
      justify-content: center;
      align-items: center;
      font-size: 16px;
      animation: tournerDisque 4s linear infinite;
      margin-top: 10px;
    }
    .grand-coeur-anim {
      position: absolute;
      top: 50%;
      left: 50%;
      font-size: 85px;
      pointer-events: none;
      animation: popCoeur 0.8s ease-out forwards;
      z-index: 50;
    }
  `;
  document.head.appendChild(styleAnim);

  // Fonction pour équiper chaque vidéo
  function equiperTikTokFeatures(carte) {
    if (carte.dataset.tiktokEquipped) return;
    carte.dataset.tiktokEquipped = 'true';

    const auteur = carte.querySelector('h3')?.textContent || '@FasoTok';

    // 1. Ajouter le nom de la musique défilante sous la description
    const blocInfo = carte.querySelector('div[style*="left:15px"]');
    if (blocInfo) {
      const musique = document.createElement('p');
      musique.style.cssText = 'font-size: 13px; margin-top: 8px; color: #eee; font-weight: 500;';
      musique.textContent = `🎵 Son original - ${auteur} (FasoTok BF)`;
      blocInfo.appendChild(musique);
    }

    // 2. Ajouter le disque vinyle qui tourne en bas de la barre d'actions
    const barreActions = carte.querySelector('div[style*="right:15px"]');
    if (barreActions) {
      const disque = document.createElement('div');
      disque.className = 'disque-tiktok';
      disque.textContent = '🎵';
      barreActions.appendChild(disque);
    }

    // 3. Activer le Double-Clic (Double-Tap) sur la vidéo pour aimer
    let dernierClic = 0;
    carte.addEventListener('click', () => {
      const maintenant = Date.now();
      if (maintenant - dernierClic < 300) {
        // Afficher le grand cœur au milieu
        const coeur = document.createElement('div');
        coeur.className = 'grand-coeur-anim';
        coeur.textContent = '❤️';
        carte.appendChild(coeur);
        setTimeout(() => coeur.remove(), 800);

        // Activer le bouton J'aime s'il n'était pas encore rouge
        const likeBtn = carte.querySelector('.like-btn');
        if (likeBtn && likeBtn.textContent.trim().startsWith('🤍')) {
          likeBtn.click();
        }
      }
      dernierClic = maintenant;
    });
  }

  // Appliquer aux vidéos déjà chargées et aux futures vidéos publiées
  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(equiperTikTokFeatures);

    const obs = new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(equiperTikTokFeatures);
    });
    obs.observe(videoFeed, { childList: true });
  }, 500);
});
// --- 7. TIROIR DE COMMENTAIRES STYLE TIKTOK (BOTTOM SHEET) ---
window.addEventListener('load', () => {
  // 1. Créer le panneau de commentaires caché en bas de l'écran
  if (document.getElementById('tiktok-comment-drawer')) return;

const tiroir = document.createElement('div');
tiroir.id = 'tiktok-comment-drawer'; 
  tiroir.style.cssText = `
    position: fixed;
    left: 0;
    right: 0;
    bottom: -100%;
    height: 60vh;
    background: #161823;
    color: white;
    border-top-left-radius: 16px;
    border-top-right-radius: 16px;
    z-index: 500;
    display: flex;
    flex-direction: column;
    transition: bottom 0.3s ease;
    box-shadow: 0 -4px 20px rgba(0,0,0,0.8);
  `;

  tiroir.innerHTML = `
    <div style="padding: 15px; border-bottom: 1px solid #2b2d3a; display: flex; justify-content: space-between; align-items: center;">
      <strong id="drawer-title">Commentaires</strong>
      <button id="close-drawer-btn" type="button" style="background:none; border:none; color:white; font-size:20px; cursor:pointer;">✕</button>
    </div>
    <div id="drawer-comments-list" style="flex: 1; overflow-y: auto; padding: 15px; display: flex; flex-direction: column; gap: 12px;"></div>
    <form id="drawer-comment-form" style="padding: 10px 15px; background: #000; display: flex; gap: 10px; border-top: 1px solid #2b2d3a;">
      <input type="text" id="drawer-comment-input" placeholder="Ajouter un commentaire..." required style="flex: 1; padding: 10px 14px; border-radius: 20px; border: none; background: #222; color: white;">
      <button type="submit" style="background: #fe2c55; color: white; border: none; border-radius: 20px; padding: 0 18px; font-weight: bold; cursor: pointer;">Envoyer</button>
    </form>
  `;

  document.body.appendChild(tiroir);

  const closeBtn = document.getElementById('close-drawer-btn');
  const commentsList = document.getElementById('drawer-comments-list');
  const commentForm = document.getElementById('drawer-comment-form');
  const commentInput = document.getElementById('drawer-comment-input');
  const drawerTitle = document.getElementById('drawer-title');

  let videoActiveId = null;

  // Fermer le tiroir
  closeBtn.addEventListener('click', () => {
    tiroir.style.bottom = '-100%';
  });

  // Afficher les commentaires sauvegardés pour cette vidéo
  function afficherCommentaires(videoId) {
    commentsList.innerHTML = '';
    let commentaires = [];

try {
  commentaires = JSON.parse(
    localStorage.getItem('fasotok_coms_' + videoId) || '[]'
  );

  if (!Array.isArray(commentaires)) commentaires = [];
} catch (error) {
  console.error('Erreur commentaires :', error);
}

    drawerTitle.textContent = `${commentaires.length} commentaire(s)`;

    if (commentaires.length === 0) {
      commentsList.innerHTML = '<p style="color:#888; text-align:center; margin-top:30px;">Sois le premier à commenter cette vidéo ! 🇧🇫</p>';
      return;
    }

    commentaires.forEach(com => {
      const item = document.createElement('div');
      item.style.cssText = 'background: #222533; padding: 10px 12px; border-radius: 10px;';
      item.innerHTML = `
        <strong style="font-size: 13px; color: #fe2c55;">@${com.auteur}</strong>
        <p style="font-size: 14px; margin-top: 4px;">${com.texte}</p>
      `;
      commentsList.appendChild(item);
    });
  }

  // Envoyer un nouveau commentaire
  commentForm.addEventListener('submit', (e) => {
    e.preventDefault();
    if (!videoActiveId) return;

    const texte = commentInput.value.trim();
    if (!texte) return;

    const moi = localStorage.getItem('fasotok_user') || 'FasoMembre';
    const commentaires = JSON.parse(localStorage.getItem('fasotok_coms_' + videoActiveId) || '[]');

    commentaires.push({ auteur: moi, texte: texte });
    localStorage.setItem('fasotok_coms_' + videoActiveId, JSON.stringify(commentaires));

    commentInput.value = '';
    afficherCommentaires(videoActiveId);
  });

  // Remplacer l'ancien clic sur 💬 par l'ouverture du vrai tiroir
  function activerTiroirSurVideos() {
    document.querySelectorAll('.video-item').forEach((carte, index) => {
      if (carte.dataset.drawerReady) return;
      carte.dataset.drawerReady = 'true';

      const auteur = carte.querySelector('h3')?.textContent || 'vid_' + index;
      const vidId = carte.dataset.postId || (auteur.replace(/[^a-zA-Z0-9]/g, '') + '_' + index);

      const oldBtn = carte.querySelector('.comment-btn');
      if (oldBtn) {
        // Cloner le bouton pour supprimer l'ancien événement "prompt"
        const newBtn = oldBtn.cloneNode(true);
        oldBtn.parentNode.replaceChild(newBtn, oldBtn);

        newBtn.addEventListener('click', (e) => {
          e.stopPropagation(); // Évite de mettre la vidéo en pause
          videoActiveId = vidId;
          afficherCommentaires(vidId);
          tiroir.style.bottom = '0';
        });
      }
    });
  }

  setTimeout(activerTiroirSurVideos, 600);
  const videoFeed = document.getElementById('video-feed');
  if (videoFeed) {
    new MutationObserver(activerTiroirSurVideos).observe(videoFeed, { childList: true });
  }
});
// --- 8. BARRE DE RECHERCHE TIKTOK (🔍) EN HAUT À DROITE ---
window.addEventListener('load', () => {
  const topNav = document.getElementById('top-nav');
  const videoFeed = document.getElementById('video-feed');
  if (!topNav || !videoFeed) return;

  // 1. Ajouter l'icône loupe 🔍 tout à droite de la barre supérieure
  const searchIconBtn = document.createElement('button');
  searchIconBtn.type = 'button';
  searchIconBtn.textContent = '🔍';
  searchIconBtn.style.cssText = `
    position: absolute;
    right: 15px;
    background: none;
    border: none;
    color: white;
    font-size: 20px;
    cursor: pointer;
  `;
  topNav.appendChild(searchIconBtn);

  // 2. Créer le panneau de recherche plein écran
  const searchPanel = document.createElement('div');
  searchPanel.id = 'tiktok-search-panel';
  searchPanel.style.cssText = `
    position: fixed;
    inset: 0;
    background: #000;
    z-index: 600;
    display: none;
    flex-direction: column;
    padding: 15px;
  `;

  searchPanel.innerHTML = `
    <div style="display: flex; align-items: center; gap: 10px; margin-bottom: 20px;">
      <button id="close-search-btn" type="button" style="background:none; border:none; color:white; font-size:22px; cursor:pointer;">←</button>
      <input type="text" id="tiktok-search-input" placeholder="Rechercher @pseudo ou #hashtag..." style="flex:1; padding:10px 15px; border-radius:20px; border:1px solid #333; background:#161823; color:white; font-size:15px;">
      <button id="run-search-btn" type="button" style="background:#fe2c55; color:white; border:none; border-radius:20px; padding:10px 16px; font-weight:bold; cursor:pointer;">Chercher</button>
    </div>
    <div style="margin-bottom: 15px;">
      <p style="font-size: 13px; color: #aaa; margin-bottom: 10px;">🔥 Tendances au Burkina Faso :</p>
      <div style="display: flex; flex-wrap: wrap; gap: 8px;" id="trending-tags">
        <span class="tag-chip" style="background:#222; padding:6px 12px; border-radius:15px; font-size:13px; cursor:pointer;">#FasoTok</span>
        <span class="tag-chip" style="background:#222; padding:6px 12px; border-radius:15px; font-size:13px; cursor:pointer;">#Burkina</span>
        <span class="tag-chip" style="background:#222; padding:6px 12px; border-radius:15px; font-size:13px; cursor:pointer;">Ouaga</span>
        <span class="tag-chip" style="background:#222; padding:6px 12px; border-radius:15px; font-size:13px; cursor:pointer;">Tout afficher</span>
      </div>
    </div>
    <p id="search-status-msg" style="color: #25f4ee; font-size: 14px;"></p>
  `;

  document.body.appendChild(searchPanel);

  const closeSearchBtn = document.getElementById('close-search-btn');
  const searchInput = document.getElementById('tiktok-search-input');
  const runSearchBtn = document.getElementById('run-search-btn');
  const statusMsg = document.getElementById('search-status-msg');

  // Ouvrir / Fermer la recherche
  searchIconBtn.addEventListener('click', () => {
    searchPanel.style.display = 'flex';
    searchInput.focus();
  });

  closeSearchBtn.addEventListener('click', () => {
    searchPanel.style.display = 'none';
  });

  // Fonction pour filtrer les vidéos selon le mot-clé
  function filtrerVideos(motCle) {
    const terme = motCle.toLowerCase().trim();
    const videos = videoFeed.querySelectorAll('.video-item');
    let trouvees = 0;

    videos.forEach(carte => {
      const texteCarte = carte.textContent.toLowerCase();
      if (terme === '' || terme === 'tout afficher' || texteCarte.includes(terme)) {
        carte.style.display = 'block';
        trouvees++;
      } else {
        carte.style.display = 'none';
      }
    });

    if (trouvees === 0) {
      statusMsg.textContent = `Aucune vidéo trouvée pour "${motCle}". Essaie un autre mot !`;
    } else {
      statusMsg.textContent = '';
      searchPanel.style.display = 'none';
    }
  }

  runSearchBtn.addEventListener('click', () => filtrerVideos(searchInput.value));
  searchInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') filtrerVideos(searchInput.value);
  });

  // Rendre les hashtags tendances cliquables
  document.querySelectorAll('.tag-chip').forEach(chip => {
    chip.addEventListener('click', () => {
      const mot = chip.textContent;
      searchInput.value = mot === 'Tout afficher' ? '' : mot;
      filtrerVideos(mot);
    });
  });
});
