// --- 29. SAUVEGARDE PERMANENTE DES VIDÉOS EN LOCAL (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const DB_NAME = 'FasoTokLocalDB';
  const STORE_NAME = 'mesVideos';
  let db = null;

  // 1. Ouvrir ou créer la base de données interne du téléphone
  const request = indexedDB.open(DB_NAME, 1);

  request.onupgradeneeded = (e) => {
    db = e.target.result;
    if (!db.objectStoreNames.contains(STORE_NAME)) {
      db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
    }
  };

  request.onsuccess = (e) => {
    db = e.target.result;
    chargerVideosSauvegardees();
  };

  // 2. Fonction pour sauvegarder un fichier vidéo/photo dans le téléphone
  window.sauvegarderMediaLocal = function(file, legende, filtre) {
    if (!db) return;
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const auteur = localStorage.getItem('fasotok_user') || 'FasoCreateur';

    store.add({
      fichier: file,
      auteur: auteur,
      legende: legende || 'Ma vidéo FasoTok 🇧🇫',
      filtre: filtre || 'none',
      date: Date.now()
    });
  };

  // 3. Recharger automatiquement les vidéos sauvegardées au démarrage de l'appli
  function chargerVideosSauvegardees() {
    if (!db) return;
    const videoFeed = document.getElementById('video-feed');
    const emptyMsg = document.getElementById('empty-feed-msg');
    if (!videoFeed) return;

    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const getAll = store.getAll();

    getAll.onsuccess = () => {
      const liste = getAll.result;
      if (liste.length > 0 && emptyMsg) {
        emptyMsg.style.display = 'none';
      }

      liste.forEach((item) => {
        const url = URL.createObjectURL(item.fichier);
        const estVideo = item.fichier.type.startsWith('video/');

        const card = document.createElement('div');
        card.className = 'video-item';
        const mediaHTML = estVideo
          ? `<video src="${url}" loop playsinline style="width:100%; height:100%; object-fit:cover; filter:${item.filtre};"></video>`
          : `<img src="${url}" style="width:100%; height:100%; object-fit:contain; filter:${item.filtre};">`;

        card.innerHTML = `
          ${mediaHTML}
          <div style="position:absolute; bottom:25px; left:15px; right:70px; text-shadow:1px 1px 4px #000;">
            <h3>@${item.auteur}</h3>
            <p style="font-size:14px; margin-top:5px;">${item.legende}</p>
          </div>
          <div style="position:absolute; bottom:30px; right:15px; display:flex; flex-direction:column; gap:15px; align-items:center;">
            <button class="like-btn" type="button" style="background:none; border:none; font-size:30px;">🤍</button>
            <span class="like-count" style="font-weight:bold; font-size:13px;">0</span>
            <button class="comment-btn" type="button" style="background:none; border:none; font-size:28px;">💬</button>
            <span style="font-size:12px;">Avis</span>
          </div>
        `;

        videoFeed.prepend(card);
      });
    };
  }
});
// --- 30. PHOTO DE PROFIL PERSONNALISÉE EN LOCAL (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const avatarBox = document.querySelector('.profile-avatar');
  if (!avatarBox) return;

  // Charger la photo de profil sauvegardée s'il y en a une
  const photoSauvee = localStorage.getItem('fasotok_avatar_img');
  if (photoSauvee) {
    avatarBox.innerHTML = `<img src="${photoSauvee}" style="width:85px; height:85px; border-radius:50%; object-fit:cover; border:2px solid #fe2c55;">`;
  }

  // Créer un sélecteur d'image caché
  const avatarInput = document.createElement('input');
  avatarInput.type = 'file';
  avatarInput.accept = 'image/*';
  avatarInput.style.display = 'none';
  document.body.appendChild(avatarInput);

  avatarBox.style.cursor = 'pointer';
  avatarBox.title = 'Appuie pour changer ta photo de profil';

  avatarBox.addEventListener('click', () => {
    avatarInput.click();
  });

  avatarInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = () => {
      const imageDataUrl = reader.result;
      localStorage.setItem('fasotok_avatar_img', imageDataUrl);
      avatarBox.innerHTML = `<img src="${imageDataUrl}" style="width:85px; height:85px; border-radius:50%; object-fit:cover; border:2px solid #fe2c55;">`;
      alert("📸 Ta nouvelle photo de profil est enregistrée !");
    };
    reader.readAsDataURL(file);
  });
});
// --- 31. ENREGISTRER CHAQUE PUBLICATION DU STUDIO DANS INDEXEDDB (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const studioInput = document.querySelector('input[type="file"][accept="video/*,image/*"]');
  const postStudioBtn = document.getElementById('post-studio-btn');
  const captionInput = document.getElementById('studio-caption-input');
  let dernierFichierChoisi = null;

  // Capturer le fichier sélectionné dans le Studio ou la caméra
  document.addEventListener('change', (e) => {
    if (e.target && e.target.type === 'file' && e.target.files && e.target.files[0]) {
      // Ignorer le sélecteur d'avatar (qui n'accepte que image/*)
      if (e.target.accept.includes('video')) {
        dernierFichierChoisi = e.target.files[0];
      }
    }
  });

  // Sauvegarder définitivement le fichier lorsqu'on clique sur "Publier"
  if (postStudioBtn) {
    postStudioBtn.addEventListener('click', () => {
      if (dernierFichierChoisi && typeof window.sauvegarderMediaLocal === 'function') {
        const legende = captionInput ? captionInput.value.trim() : '';
        const mediaPreview = document.getElementById('studio-media');
        const filtre = mediaPreview ? mediaPreview.style.filter : 'none';

        window.sauvegarderMediaLocal(dernierFichierChoisi, legende, filtre);
        dernierFichierChoisi = null;
      }
    });
  }
});
