window.addEventListener('load', () => {
  // Créer une visionneuse plein écran pour les vidéos du profil
  const profileViewer = document.createElement('div');
  profileViewer.id = 'profile-media-viewer';
  profileViewer.style.cssText = `
    position: fixed; inset: 0; background: #000; z-index: 950;
    display: none; flex-direction: column; justify-content: center; align-items: center;
  `;

  profileViewer.innerHTML = `
    <button id="close-profile-viewer" type="button" style="position:absolute; top:20px; right:20px; background:rgba(255,255,255,0.2); border:none; color:white; width:38px; height:38px; border-radius:50%; font-size:20px; z-index:960;">✕</button>
    <div id="profile-viewer-content" style="width:100%; height:100%; display:flex; justify-content:center; align-items:center;"></div>
  `;
  document.body.appendChild(profileViewer);

  const viewerContent = document.getElementById('profile-viewer-content');
  document.getElementById('close-profile-viewer').addEventListener('click', () => {
    viewerContent.innerHTML = ''; // Coupe le son à la fermeture
    profileViewer.style.display = 'none';
  });

  // Détecter le clic sur n'importe quelle miniature dans les grilles du Profil
  document.addEventListener('click', (e) => {
    const grille = e.target.closest('#my-videos-grid, #profile-favs-grid');
    if (!grille) return;

    const vignette = e.target.closest('div');
    if (!vignette) return;

    const media = vignette.querySelector('video, img');
    if (!media) return;

    if (media.tagName === 'VIDEO') {
      viewerContent.innerHTML = `<video src="${media.src}" controls autoplay loop playsinline style="width:100%; height:100%; object-fit:contain;"></video>`;
    } else {
      viewerContent.innerHTML = `<img src="${media.src}" style="width:100%; height:100%; object-fit:contain;">`;
    }

    profileViewer.style.display = 'flex';
  });
});
// --- 33. STORIES TIKTOK 24H EN HAUT DE L'ÉCRAN (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const homePage = document.getElementById('home-page');
  if (!homePage) return;

  // 1. Créer la barre horizontale des Stories juste sous le menu du haut
  const storiesBar = document.createElement('div');
  storiesBar.id = 'fasotok-stories-bar';
  storiesBar.style.cssText = `
    position: fixed; top: 48px; left: 0; right: 0; height: 78px;
    background: linear-gradient(to bottom, rgba(0,0,0,0.85), transparent);
    display: flex; align-items: center; gap: 14px; padding: 0 15px;
    overflow-x: auto; z-index: 90;
  `;

  const storiesData = [
    { nom: "Ta Story +", avatar: "📸", texte: "Bienvenue sur ma Story FasoTok ! 🇧🇫🔥", couleur: "#fe2c55", isMe: true },
    { nom: "OuagaStar", avatar: "😂", texte: "Qui est prêt pour le concert ce soir à Ouaga ? 🎤", couleur: "#25f4ee" },
    { nom: "BoboDance", avatar: "💃", texte: "Nouvelle chorégraphie Afrobeat en préparation 🔥", couleur: "#fe2c55" },
    { nom: "Etalons226", avatar: "⚽", texte: "Allez les Étalons ! Victoire assurée 🇧🇫🦁", couleur: "#feca57" }
  ];

  storiesData.forEach((st) => {
    const item = document.createElement('div');
    item.style.cssText = 'display:flex; flex-direction:column; align-items:center; min-width:58px; cursor:pointer;';
    item.innerHTML = `
      <div style="width:48px; height:48px; border-radius:50%; padding:2px; background:linear-gradient(45deg, #25f4ee, #fe2c55); display:flex; justify-content:center; align-items:center;">
        <div style="width:100%; height:100%; background:#161823; border-radius:50%; display:flex; justify-content:center; align-items:center; font-size:22px;">
          ${st.avatar}
        </div>
      </div>
      <span style="font-size:10px; color:white; margin-top:4px; text-shadow:1px 1px 2px #000; white-space:nowrap;">${st.nom}</span>
    `;

    item.addEventListener('click', () => {
      if (st.isMe) {
        const monTexte = prompt("Écris le texte de ta Story 24h :", st.texte);
        if (monTexte && monTexte.trim() !== '') {
          st.texte = monTexte.trim();
        }
      }
      ouvrirVisionneuseStory(st);
    });

    storiesBar.appendChild(item);
  });

  homePage.appendChild(storiesBar);

  // 2. Créer la visionneuse plein écran des Stories
  const storyViewer = document.createElement('div');
  storyViewer.style.cssText = `
    position: fixed; inset: 0; background: linear-gradient(135deg, #161823, #000);
    z-index: 980; display: none; flex-direction: column; justify-content: space-between;
    padding: 20px; color: white;
  `;

  storyViewer.innerHTML = `
    <div>
      <div style="width:100%; height:3px; background:rgba(255,255,255,0.3); border-radius:2px; overflow:hidden; margin-bottom:12px;">
        <div id="story-progress-fill" style="width:0%; height:100%; background:#fff; transition:width 4s linear;"></div>
      </div>
      <div style="display:flex; justify-content:space-between; align-items:center;">
        <strong id="story-author-name" style="font-size:15px;">@Auteur</strong>
        <button id="close-story-btn" type="button" style="background:none; border:none; color:white; font-size:22px;">✕</button>
      </div>
    </div>
    <div id="story-body-text" style="text-align:center; font-size:24px; font-weight:bold; padding:20px;"></div>
    <p style="text-align:center; font-size:12px; color:#aaa;">Story FasoTok 24h 🇧🇫</p>
  `;
  document.body.appendChild(storyViewer);

  let storyTimer = null;

  function ouvrirVisionneuseStory(st) {
    clearTimeout(storyTimer);
    document.getElementById('story-author-name').textContent = `${st.avatar} ${st.nom}`;
    document.getElementById('story-body-text').textContent = st.texte;

    const fill = document.getElementById('story-progress-fill');
    fill.style.transition = 'none';
    fill.style.width = '0%';
    storyViewer.style.display = 'flex';

    setTimeout(() => {
      fill.style.transition = 'width 4s linear';
      fill.style.width = '100%';
    }, 50);

    storyTimer = setTimeout(() => {
      storyViewer.style.display = 'none';
    }, 4100);
  }

  document.getElementById('close-story-btn').addEventListener('click', () => {
    clearTimeout(storyTimer);
    storyViewer.style.display = 'none';
  });
});
