window.addEventListener('load', () => {
  const profileInfo = document.querySelector('.profile-info-container');
  const avatarBox = document.querySelector('.profile-avatar');
  if (!profileInfo || !avatarBox) return;

  // Créer la bulle de pensée au-dessus de l'avatar
  const noteBubble = document.createElement('div');
  noteBubble.id = 'fasotok-profile-note';
  noteBubble.style.cssText = `
    display: inline-block; background: #222533; color: #fff;
    padding: 8px 14px; border-radius: 18px; font-size: 13px;
    margin-bottom: 10px; border: 1px solid #333; cursor: pointer;
    box-shadow: 0 3px 10px rgba(0,0,0,0.5); max-width: 240px;
  `;

  const noteSauvee = localStorage.getItem('fasotok_note_24h');
  noteBubble.textContent = noteSauvee ? `💭 ${noteSauvee}` : '💭 Laisser une note...';

  avatarBox.before(noteBubble);

  noteBubble.addEventListener('click', () => {
    const actuelle = localStorage.getItem('fasotok_note_24h') || '';
    const nouvelleNote = prompt("Écris ta note d'humeur du jour (max 50 caractères) :", actuelle);

    if (nouvelleNote !== null) {
      const textePropre = nouvelleNote.trim().slice(0, 50);
      if (textePropre === '') {
        localStorage.removeItem('fasotok_note_24h');
        noteBubble.textContent = '💭 Laisser une note...';
      } else {
        localStorage.setItem('fasotok_note_24h', textePropre);
        noteBubble.textContent = `💭 ${textePropre}`;
      }
    }
  });
});
