// --- 37. BARRE DE RÉACTIONS RAPIDES PAR ÉMOJIS (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  function ajouterReactionsRapides(carte) {
    if (carte.dataset.reactionsReady) return;
    carte.dataset.reactionsReady = 'true';

    const barreActions = carte.querySelector('div[style*="right:15px"]');
    if (!barreActions) return;

    // Bouton pour ouvrir les réactions
    const reactBtn = document.createElement('button');
    reactBtn.type = 'button';
    reactBtn.textContent = '😍';
    reactBtn.style.cssText = 'background:none; border:none; font-size:26px; cursor:pointer; margin-top:5px;';

    // Bulle flottante contenant 4 émojis
    const popupEmojis = document.createElement('div');
    popupEmojis.style.cssText = `
      position: absolute; right: 65px; bottom: 140px;
      background: rgba(22, 24, 35, 0.95); border: 1px solid #333;
      border-radius: 25px; padding: 6px 12px; display: none; gap: 10px;
      z-index: 60; box-shadow: 0 4px 15px rgba(0,0,0,0.7);
    `;

    ['😂', '🔥', '👏', '🇧🇫'].forEach(emoji => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.textContent = emoji;
      btn.style.cssText = 'background:none; border:none; font-size:24px; cursor:pointer;';

      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        popupEmojis.style.display = 'none';

        // Faire s'envoler l'émoji choisi au milieu de la vidéo
        const volant = document.createElement('div');
        volant.textContent = emoji;
        volant.style.cssText = `
          position: absolute; top: 55%; left: 50%; transform: translate(-50%, -50%);
          font-size: 75px; pointer-events: none; transition: all 0.9s ease-out; opacity: 1; z-index: 70;
        `;
        carte.appendChild(volant);

        setTimeout(() => {
          volant.style.top = '25%';
          volant.style.opacity = '0';
        }, 50);
        setTimeout(() => volant.remove(), 950);
      });

      popupEmojis.appendChild(btn);
    });

    reactBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      popupEmojis.style.display = popupEmojis.style.display === 'flex' ? 'none' : 'flex';
    });

    carte.appendChild(popupEmojis);
    barreActions.appendChild(reactBtn);
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(ajouterReactionsRapides);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(ajouterReactionsRapides);
    }).observe(videoFeed, { childList: true });
  }, 1300);
});
// --- 38. BOUTON BOUCLE VIDÉO (🔁) ET VERROUILLAGE TACTILE (🔒) (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  function ajouterBoucleEtVerrou(carte) {
    if (carte.dataset.loopLockReady) return;
    carte.dataset.loopLockReady = 'true';

    const videoEl = carte.querySelector('video');
    if (!videoEl) return;

    // Bouton Répétition en boucle (🔁) en haut à gauche sous le bouton plein écran
    const loopBtn = document.createElement('button');
    loopBtn.type = 'button';
    loopBtn.textContent = '🔁';
    loopBtn.title = 'Lecture en boucle activée';
    loopBtn.style.cssText = `
      position: absolute; top: 150px; left: 15px;
      background: rgba(254, 44, 85, 0.75); border: none;
      color: white; font-size: 16px; padding: 8px;
      border-radius: 50%; z-index: 40; cursor: pointer;
    `;

    loopBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      videoEl.loop = !videoEl.loop;
      loopBtn.style.background = videoEl.loop ? 'rgba(254, 44, 85, 0.75)' : 'rgba(0, 0, 0, 0.5)';
      alert(videoEl.loop ? '🔁 Lecture en boucle activée' : '➡️ Lecture simple (sans répétition)');
    });

    carte.appendChild(loopBtn);
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(ajouterBoucleEtVerrou);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(ajouterBoucleEtVerrou);
    }).observe(videoFeed, { childList: true });
  }, 1350);
});
// --- 39. MODE ÉCONOMIE DE DONNÉES MOBILES (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const profileContainer = document.querySelector('#profile-page .page-padding');
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!profileContainer || !modProfilBtn) return;

  // 1. Ajouter l'interrupteur Économie de Données dans les paramètres du Profil
  const ecoBox = document.createElement('div');
  ecoBox.style.cssText = `
    background: #161823; padding: 12px; border-radius: 10px;
    margin-top: 15px; display: flex; justify-content: space-between; align-items: center;
  `;

  const ecoActive = localStorage.getItem('fasotok_eco_data') === 'true';

  ecoBox.innerHTML = `
    <div>
      <strong style="font-size: 14px;">📶 Économie de données</strong>
      <p style="font-size: 11px; color: #aaa; margin-top: 2px;">Désactive la lecture automatique pour économiser tes mégas.</p>
    </div>
    <input type="checkbox" id="toggle-eco-data" ${ecoActive ? 'checked' : ''} style="width: 20px; height: 20px; accent-color: #fe2c55;">
  `;

  modProfilBtn.parentElement.appendChild(ecoBox);

  const ecoCheckbox = document.getElementById('toggle-eco-data');
  ecoCheckbox.addEventListener('change', () => {
    localStorage.setItem('fasotok_eco_data', ecoCheckbox.checked.toString());
    if (ecoCheckbox.checked) {
      document.querySelectorAll('#video-feed video').forEach(v => v.pause());
      alert("📶 Mode Économie de données activé : touche une vidéo pour la lancer.");
    } else {
      alert("⚡ Mode Normal activé : lecture automatique rétablie.");
    }
  });

  // Empêcher la lecture auto si le mode Éco-Data est activé
  if (ecoActive) {
    setInterval(() => {
      document.querySelectorAll('#video-feed video').forEach(v => {
        if (!v.dataset.userClicked && !v.paused) {
          v.pause();
        }
      });
    }, 800);

    document.addEventListener('click', (e) => {
      if (e.target && e.target.tagName === 'VIDEO') {
        e.target.dataset.userClicked = 'true';
      }
    });
  }
});
// --- 40. SYSTÈME DE BROUILLONS VIDÉO DANS LE STUDIO (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const studioModal = document.getElementById('fasotok-studio-modal');
  const postStudioBtn = document.getElementById('post-studio-btn');
  const captionInput = document.getElementById('studio-caption-input');
  const profileContainer = document.querySelector('#profile-page .page-padding');

  if (!studioModal || !postStudioBtn || !profileContainer) return;

  // 1. Ajouter un bouton "📁 Brouillon" dans le Studio à côté de Publier
  const draftBtn = document.createElement('button');
  draftBtn.type = 'button';
  draftBtn.textContent = '📁 Brouillon';
  draftBtn.style.cssText = `
    background: #222533; color: #25f4ee; border: 1px solid #25f4ee;
    padding: 8px 12px; border-radius: 20px; font-weight: bold; font-size: 13px; margin-right: 6px;
  `;

  postStudioBtn.before(draftBtn);

  // 2. Créer l'affichage des brouillons enregistrés sur le Profil
  const draftListBox = document.createElement('div');
  draftListBox.id = 'profile-drafts-box';
  draftListBox.style.cssText = 'margin-top: 15px; background: #161823; padding: 12px; border-radius: 10px;';

  function afficherBrouillons() {
    const brouillons = JSON.parse(localStorage.getItem('fasotok_drafts') || '[]');
    if (brouillons.length === 0) {
      draftListBox.style.display = 'none';
      return;
    }

    draftListBox.style.display = 'block';
    draftListBox.innerHTML = `<strong style="font-size: 13px; color: #25f4ee;">📁 Mes Brouillons (${brouillons.length})</strong>`;

    brouillons.forEach((b, index) => {
      const row = document.createElement('div');
      row.style.cssText = 'display:flex; justify-content:space-between; align-items:center; margin-top:8px; padding-top:8px; border-top:1px solid #222; font-size:12px;';
      row.innerHTML = `
        <span>📝 ${b.legende || 'Brouillon sans titre'} (${b.date})</span>
        <button type="button" class="del-draft-btn" data-idx="${index}" style="background:none; border:none; color:#fe2c55; font-weight:bold;">Supprimer</button>
      `;
      draftListBox.appendChild(row);
    });

    draftListBox.querySelectorAll('.del-draft-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const idx = parseInt(btn.getAttribute('data-idx'), 10);
        brouillons.splice(idx, 1);
        localStorage.setItem('fasotok_drafts', JSON.stringify(brouillons));
        afficherBrouillons();
      });
    });
  }

  const tabsBar = document.getElementById('tab-my-videos')?.parentElement;
  if (tabsBar) {
    tabsBar.before(draftListBox);
  }
  afficherBrouillons();

  // Enregistrer en brouillon au clic
  draftBtn.addEventListener('click', () => {
    const legende = captionInput ? captionInput.value.trim() : '';
    const brouillons = JSON.parse(localStorage.getItem('fasotok_drafts') || '[]');

    brouillons.push({
      legende: legende || 'Idée vidéo FasoTok 🇧🇫',
      date: new Date().toLocaleDateString('fr-FR')
    });

    localStorage.setItem('fasotok_drafts', JSON.stringify(brouillons));
    afficherBrouillons();
    studioModal.style.display = 'none';
    alert("📁 Ton brouillon a été enregistré dans ton Profil !");
  });
});
// --- 41. HISTORIQUE DES VIDÉOS REGARDÉES (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!videoFeed || !modProfilBtn) return;

  // 1. Enregistrer chaque vidéo visionnée dans l'historique local
  const obsHistorique = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const auteur = entry.target.querySelector('h3')?.textContent || '@FasoTok';
        const desc = entry.target.querySelector('p')?.textContent || 'Vidéo FasoTok';

        let histo = JSON.parse(localStorage.getItem('fasotok_history') || '[]');
        // Éviter les doublons consécutifs
        if (histo.length === 0 || histo.desc !== desc) {
          histo.unshift({
            auteur: auteur,
            desc: desc.slice(0, 45),
            heure: new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })
          });
          localStorage.setItem('fasotok_history', JSON.stringify(histo.slice(0, 15)));
        }
      }
    });
  }, { threshold: 0.75 });

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(c => obsHistorique.observe(c));
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(c => obsHistorique.observe(c));
    }).observe(videoFeed, { childList: true });
  }, 1400);

  // 2. Ajouter le bouton "🕒 Historique" dans le Profil
  const histoBtn = document.createElement('button');
  histoBtn.type = 'button';
  histoBtn.textContent = '🕒 Historique de visionnage';
  histoBtn.className = 'secondary-btn';
  histoBtn.style.width = '100%';
  histoBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(histoBtn);

  histoBtn.addEventListener('click', () => {
    const histo = JSON.parse(localStorage.getItem('fasotok_history') || '[]');
    if (histo.length === 0) {
      alert("🕒 Ton historique est encore vide. Regarde quelques vidéos dans l'accueil !");
      return;
    }

    const resume = histo.map((h, i) => `${i + 1}. ${h.auteur} — "${h.desc}..." (${h.heure})`).join('\n');
    alert("🕒 DERNIÈRES VIDÉOS REGARDÉES :\n\n" + resume);
  });
});
// --- 42. BIEN-ÊTRE NUMÉRIQUE : RAPPEL DE TEMPS D'ÉCRAN (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!modProfilBtn) return;

  const timerBtn = document.createElement('button');
  timerBtn.type = 'button';
  timerBtn.textContent = '⏱️ Rappel de pause (Temps d’écran)';
  timerBtn.className = 'secondary-btn';
  timerBtn.style.width = '100%';
  timerBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(timerBtn);

  let rappelTimer = null;

  timerBtn.addEventListener('click', () => {
    const minutes = prompt("Après combien de minutes veux-tu recevoir un rappel de pause ? (ex: 15)", "15");
    const delai = parseInt(minutes, 10);

    if (!isNaN(delai) && delai > 0) {
      clearTimeout(rappelTimer);
      alert(`⏱️ Rappel activé ! FasoTok t'avertira dans ${delai} minute(s).`);

      rappelTimer = setTimeout(() => {
        alert(`⏱️ PAUSE FASOTOK 🇧🇫 : Cela fait ${delai} minutes que tu regardes des vidéos. Pense à reposer tes yeux !`);
      }, delai * 60 * 1000);
    }
  });
});
