// --- 44. PERSONNALISATION DU THÈME DE L'APPLICATION (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!modProfilBtn) return;

  const themeBox = document.createElement('div');
  themeBox.style.cssText = 'margin-top: 15px;';
  themeBox.innerHTML = `
    <label for="fasotok-theme-select" style="font-size: 14px; font-weight: bold; display: block; margin-bottom: 6px;">🎨 Thème de l'application :</label>
    <select id="fasotok-theme-select" class="custom-select">
      <option value="dark">🌑 Noir Classique (TikTok)</option>
      <option value="burkina">🇧🇫 Couleurs du Faso (Vert & Rouge)</option>
      <option value="ocean">🌌 Bleu Nuit Étoilé</option>
    </select>
  `;

  modProfilBtn.parentElement.appendChild(themeBox);

  const themeSelect = document.getElementById('fasotok-theme-select');

  function appliquerTheme(theme) {
    const app = document.querySelector('.fasotoc-app');
    const bottomNav = document.querySelector('.bottom-nav');
    if (!app || !bottomNav) return;

    if (theme === 'burkina') {
      app.style.background = 'linear-gradient(180deg, #009e49 0%, #000000 35%, #ef2b2d 100%)';
      bottomNav.style.backgroundColor = '#1a0505';
    } else if (theme === 'ocean') {
      app.style.background = 'linear-gradient(180deg, #0a192f 0%, #000000 100%)';
      bottomNav.style.backgroundColor = '#0a192f';
    } else {
      app.style.background = '#000000';
      bottomNav.style.backgroundColor = '#000000';
    }
    localStorage.setItem('fasotok_theme', theme);
  }

  const themeSauve = localStorage.getItem('fasotok_theme') || 'dark';
  themeSelect.value = themeSauve;
  appliquerTheme(themeSauve);

  themeSelect.addEventListener('change', () => {
    appliquerTheme(themeSelect.value);
  });
});
// --- 45. PORTEFEUILLE DE PIÈCES FASOTOK ET BONUS QUOTIDIEN (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const profileContainer = document.querySelector('#profile-page .page-padding');
  const statsContainer = profileContainer?.querySelector('.profile-stats');
  if (!profileContainer || !statsContainer) return;

  // Initialiser le solde de pièces (100 pièces offertes à l'inscription)
  if (localStorage.getItem('fasotok_coins') === null) {
    localStorage.setItem('fasotok_coins', '100');
  }

  // Fonction globale pour lire ou modifier les pièces
  window.getFasoCoins = () => parseInt(localStorage.getItem('fasotok_coins') || '0', 10);
  window.setFasoCoins = (nouveauSolde) => {
    localStorage.setItem('fasotok_coins', Math.max(0, nouveauSolde).toString());
    const display = document.getElementById('profile-coins-amount');
    if (display) display.textContent = window.getFasoCoins();
  };

  // Créer la carte Portefeuille sur la page Profil
  const walletCard = document.createElement('div');
  walletCard.style.cssText = `
    background: linear-gradient(135deg, #161823, #2b1025);
    border: 1px solid #fe2c55; border-radius: 12px; padding: 14px;
    margin-top: 15px; display: flex; justify-content: space-between; align-items: center;
  `;

  walletCard.innerHTML = `
    <div>
      <span style="font-size: 12px; color: #aaa;">Mon Portefeuille FasoTok</span>
      <strong style="display: block; font-size: 20px; color: #feca57; margin-top: 2px;">
        🪙 <span id="profile-coins-amount">${window.getFasoCoins()}</span> pièces
      </strong>
    </div>
    <button id="claim-daily-coins-btn" type="button" style="background: #fe2c55; color: white; border: none; padding: 10px 14px; border-radius: 20px; font-weight: bold; font-size: 12px; cursor: pointer;">
      🎁 Bonus +50 🪙
    </button>
  `;

  statsContainer.after(walletCard);

  // Réclamer le bonus quotidien (+50 pièces une fois par jour)
  document.getElementById('claim-daily-coins-btn').addEventListener('click', () => {
    const aujourdhui = new Date().toLocaleDateString('fr-FR');
    const dernierBonus = localStorage.getItem('fasotok_last_bonus_date');

    if (dernierBonus === aujourdhui) {
      alert("⏳ Tu as déjà récupéré ton bonus de 50 pièces aujourd'hui ! Reviens demain.");
      return;
    }

    const nouveauTotal = window.getFasoCoins() + 50;
    window.setFasoCoins(nouveauTotal);
    localStorage.setItem('fasotok_last_bonus_date', aujourdhui);
    alert(`🎉 Bravo ! +50 pièces ajoutées. Ton nouveau solde est de ${nouveauTotal} 🪙.`);
  });
});
// --- 46. PAIEMENT DES CADEAUX VIRTUELS AVEC LES PIÈCES (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const giftPanel = document.getElementById('fasotok-gift-panel');
  if (!giftPanel) return;

  // Afficher le solde actuel en haut du panneau des cadeaux
  const headerGift = giftPanel.querySelector('div');
  if (headerGift) {
    const soldeBadge = document.createElement('span');
    soldeBadge.id = 'gift-panel-balance';
    soldeBadge.style.cssText = 'color: #feca57; font-size: 13px; font-weight: bold;';
    headerGift.insertBefore(soldeBadge, headerGift.lastElementChild);
  }

  // Mettre à jour les prix sur les 3 cadeaux (Rose = 10, Djembé = 30, Lion = 50)
    const prixCadeaux = new Array(10, 30, 50);
  const boutonsCadeaux = giftPanel.querySelectorAll('.gift-choice');

  boutonsCadeaux.forEach((btn, idx) => {
    const prix = prixCadeaux[idx] || 10;
    const labelPrix = document.createElement('span');
    labelPrix.style.cssText = 'display:block; font-size:11px; color:#feca57; margin-top:4px;';
    labelPrix.textContent = `${prix} 🪙`;
    btn.appendChild(labelPrix);

    // Cloner le bouton pour contrôler le solde avant d'envoyer le cadeau
    const nouveauBtn = btn.cloneNode(true);
    btn.parentNode.replaceChild(nouveauBtn, btn);

    nouveauBtn.addEventListener('click', () => {
      const soldeActuel = typeof window.getFasoCoins === 'function' ? window.getFasoCoins() : 100;

      if (soldeActuel < prix) {
        alert(`⚠️ Solde insuffisant ! Il te faut ${prix} 🪙 (tu as ${soldeActuel} 🪙). Va sur ton Profil pour réclamer ton bonus quotidien !`);
        giftPanel.style.bottom = '-100%';
        return;
      }

      // Déduire le prix du cadeau
      if (typeof window.setFasoCoins === 'function') {
        window.setFasoCoins(soldeActuel - prix);
      }

      const nomCadeau = nouveauBtn.getAttribute('data-gift');
      giftPanel.style.bottom = '-100%';
      alert(`🎁 Cadeau envoyé : ${nomCadeau} (-${prix} 🪙) ! Il te reste ${soldeActuel - prix} 🪙.`);
    });
  });

  // Actualiser l'affichage du solde chaque fois qu'on ouvre le panneau cadeau
  document.addEventListener('click', (e) => {
    if (e.target && e.target.textContent === '🎁') {
      const bal = document.getElementById('gift-panel-balance');
      if (bal && typeof window.getFasoCoins === 'function') {
        bal.textContent = `Solde : ${window.getFasoCoins()} 🪙`;
      }
    }
  });
});
// --- 47. NIVEAUX VIP CRÉATEUR ET CLASSEMENT LOCAL (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const profileInfo = document.querySelector('.profile-info-container');
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!profileInfo || !modProfilBtn) return;

  // 1. Calculer le rang VIP selon le nombre de pièces et de vidéos
  function calculerRangVIP() {
    const coins = typeof window.getFasoCoins === 'function' ? window.getFasoCoins() : 100;
    const nbVids = document.querySelectorAll('#video-feed .video-item').length;
    const score = coins + (nbVids * 30);

    if (score >= 400) return { titre: "👑 Légende du Faso (Niveau 3)", couleur: "#feca57", score };
    if (score >= 200) return { titre: "⭐ Étoile Montante (Niveau 2)", couleur: "#25f4ee", score };
    return { titre: "🌱 Nouveau Talent (Niveau 1)", couleur: "#a3cb38", score };
  }

  const rang = calculerRangVIP();

  // Afficher le badge de niveau sous la bio du profil
  const rankBadge = document.createElement('div');
  rankBadge.style.cssText = `
    display: inline-block; margin-top: 10px; padding: 5px 14px;
    border-radius: 20px; background: rgba(255,255,255,0.08);
    border: 1px solid ${rang.couleur}; color: ${rang.couleur};
    font-size: 12px; font-weight: bold;
  `;
  rankBadge.textContent = rang.titre;

  const bioEl = profileInfo.querySelector('.profile-bio');
  if (bioEl) bioEl.after(rankBadge);

  // 2. Ajouter le bouton "🏆 Classement Top FasoTok" dans le Profil
  const rankBtn = document.createElement('button');
  rankBtn.type = 'button';
  rankBtn.textContent = '🏆 Classement Top Créateurs 226';
  rankBtn.className = 'secondary-btn';
  rankBtn.style.width = '100%';
  rankBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(rankBtn);

  rankBtn.addEventListener('click', () => {
    const moi = localStorage.getItem('fasotok_user') || 'MonProfil';
    const monScore = calculerRangVIP().score;

    alert(
      "🏆 CLASSEMENT TOP CRÉATEURS FASOTOK 🇧🇫\n\n" +
      "🥇 1. @OuagaStar226 — 850 pts\n" +
      "🥈 2. @BoboDance — 620 pts\n" +
      `⭐ TOI (@${moi}) — ${monScore} pts\n` +
      "🥉 3. @EtalonsFoot — 490 pts\n\n" +
      "Publie des vidéos et gagne des pièces pour monter sur le podium !"
    );
  });
});
// --- 48. ROUE DE LA CHANCE QUOTIDIENNE POUR GAGNER DES PIÈCES (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const claimBtn = document.getElementById('claim-daily-coins-btn');
  if (!claimBtn) return;

  const walletCard = claimBtn.parentElement;

  // Ajouter un bouton "🎡 Roue" juste à côté du bouton Bonus
  const wheelBtn = document.createElement('button');
  wheelBtn.type = 'button';
  wheelBtn.textContent = '🎡 Roue';
  wheelBtn.style.cssText = `
    background: #25f4ee; color: #000; border: none; padding: 10px 12px;
    border-radius: 20px; font-weight: bold; font-size: 12px; cursor: pointer; margin-left: 6px;
  `;

  claimBtn.after(wheelBtn);

  wheelBtn.addEventListener('click', () => {
    const aujourdhui = new Date().toLocaleDateString('fr-FR');
    const dernierTour = localStorage.getItem('fasotok_last_wheel_date');

    if (dernierTour === aujourdhui) {
      alert("🎡 Tu as déjà tourné la Roue FasoTok aujourd'hui ! Reviens demain pour tenter ta chance.");
      return;
    }
        const lots = new Array(20, 50, 100, 150, 200);
    const gain = lots[Math.floor(Math.random() * lots.length)];

    if (typeof window.getFasoCoins === 'function' && typeof window.setFasoCoins === 'function') {
      const nouveauSolde = window.getFasoCoins() + gain;
      window.setFasoCoins(nouveauSolde);
      localStorage.setItem('fasotok_last_wheel_date', aujourdhui);
      alert(`🎡 LA ROUE TOURNE...\n\n🎉 Félicitations ! Tu as gagné +${gain} pièces 🪙 !\nNouveau solde : ${nouveauSolde} 🪙.`);
    }
  });
});
