window.addEventListener('load', () => {
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!modProfilBtn) return;

  const safeModeActive = localStorage.getItem('fasotok_safe_mode') === 'true';

  const safeBox = document.createElement('div');
  safeBox.style.cssText = `
    background: #161823; padding: 12px; border-radius: 10px;
    margin-top: 10px; display: flex; justify-content: space-between; align-items: center;
  `;

  safeBox.innerHTML = `
    <div>
      <strong style="font-size: 14px;">🛡️ Mode Contrôle Parental</strong>
      <p style="font-size: 11px; color: #aaa; margin-top: 2px;">Protège les paramètres et les achats de cadeaux par un code PIN.</p>
    </div>
    <input type="checkbox" id="toggle-safe-mode" ${safeModeActive ? 'checked' : ''} style="width: 20px; height: 20px; accent-color: #25f4ee;">
  `;

  modProfilBtn.parentElement.appendChild(safeBox);

  const safeCheckbox = document.getElementById('toggle-safe-mode');
  safeCheckbox.addEventListener('change', () => {
    if (safeCheckbox.checked) {
      const pin = prompt("Choisis un code PIN parental à 4 chiffres (ex: 1234) :");
      if (pin && pin.trim().length >= 4) {
        localStorage.setItem('fasotok_safe_mode', 'true');
        localStorage.setItem('fasotok_parent_pin', pin.trim());
        alert("🛡️ Contrôle parental activé avec succès !");
      } else {
        safeCheckbox.checked = false;
        alert("⚠️ Code PIN trop court (4 chiffres minimum).");
      }
    } else {
      const savedPin = localStorage.getItem('fasotok_parent_pin') || '1234';
      const saisie = prompt("Entre le code PIN parental pour désactiver :");
      if (saisie === savedPin) {
        localStorage.setItem('fasotok_safe_mode', 'false');
        alert("🔓 Contrôle parental désactivé.");
      } else {
        safeCheckbox.checked = true;
        alert("❌ Code PIN incorrect !");
      }
    }
  });
});
