window.addEventListener('load', () => {
  const tabsBar = document.getElementById('tab-my-videos')?.parentElement;
  if (!tabsBar) return;

  // Créer une barre horizontale de Playlists juste au-dessus des vidéos du Profil
  const playlistSection = document.createElement('div');
  playlistSection.style.cssText = 'margin-top: 15px; margin-bottom: 5px;';
  playlistSection.innerHTML = `
    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
      <strong style="font-size:13px; color:#ccc;">📂 Mes Playlists</strong>
      <button id="add-playlist-btn" type="button" style="background:#222533; border:1px solid #444; color:#25f4ee; font-size:11px; padding:4px 10px; border-radius:12px; cursor:pointer;">+ Créer</button>
    </div>
    <div id="playlists-chips-container" style="display:flex; gap:8px; overflow-x:auto; padding-bottom:6px;"></div>
  `;

  tabsBar.before(playlistSection);

  const chipsContainer = document.getElementById('playlists-chips-container');
  const playlistsParDefaut = new Array("🔥 Best-of 226", "🎵 Clips & Danse", "😂 Humour Ouaga");

  function afficherPlaylists() {
    const saved = JSON.parse(localStorage.getItem('fasotok_playlists') || 'null') || playlistsParDefaut;
    chipsContainer.innerHTML = '';

    saved.forEach((nom) => {
      const chip = document.createElement('button');
      chip.type = 'button';
      chip.textContent = nom;
      chip.style.cssText = `
        background: #161823; border: 1px solid #333; color: white;
        padding: 7px 14px; border-radius: 16px; font-size: 12px;
        white-space: nowrap; cursor: pointer;
      `;

      chip.addEventListener('click', () => {
        alert(`📂 Playlist « ${nom} » ouverte !\nToutes tes vidéos classées dans cette série s'affichent ici.`);
      });

      chipsContainer.appendChild(chip);
    });
  }

  afficherPlaylists();

  document.getElementById('add-playlist-btn').addEventListener('click', () => {
    const nomPlaylist = prompt("Nom de ta nouvelle playlist (ex: ⚽ Football 226) :");
    if (nomPlaylist && nomPlaylist.trim() !== '') {
      const actuelles = JSON.parse(localStorage.getItem('fasotok_playlists') || 'null') || playlistsParDefaut;
      actuelles.push(nomPlaylist.trim());
      localStorage.setItem('fasotok_playlists', JSON.stringify(actuelles));
      afficherPlaylists();
    }
  });
});
