window.addEventListener('load', () => {
  const avatarBox = document.querySelector('.profile-avatar');
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!avatarBox || !modProfilBtn) return;

  // Bouton pour choisir un cadre autour de la photo de profil
  const frameBtn = document.createElement('button');
  frameBtn.type = 'button';
  frameBtn.textContent = '🖼️ Changer le cadre de mon avatar';
  frameBtn.className = 'secondary-btn';
  frameBtn.style.width = '100%';
  frameBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(frameBtn);

  function appliquerCadreAvatar(styleCadre) {
    const img = avatarBox.querySelector('img');
    const cible = img || avatarBox;

    cible.style.borderRadius = '50%';
    cible.style.padding = '3px';

    if (styleCadre === 'burkina') {
      cible.style.border = '4px solid #009e49';
      cible.style.boxShadow = '0 0 0 3px #ef2b2d, 0 0 12px #feca57';
    } else if (styleCadre === 'neon') {
      cible.style.border = '4px solid #25f4ee';
      cible.style.boxShadow = '0 0 0 3px #fe2c55, 0 0 15px #fe2c55';
    } else if (styleCadre === 'gold') {
      cible.style.border = '4px solid #feca57';
      cible.style.boxShadow = '0 0 15px rgba(254, 202, 87, 0.8)';
    } else {
      cible.style.border = '2px solid #444';
      cible.style.boxShadow = 'none';
    }
    localStorage.setItem('fasotok_avatar_frame', styleCadre);
  }

  const cadreSauve = localStorage.getItem('fasotok_avatar_frame') || 'neon';
  appliquerCadreAvatar(cadreSauve);

  frameBtn.addEventListener('click', () => {
    const choix = prompt(
      "Choisis un style de cadre pour ta photo :\n" +
      "1 = Néon TikTok (Bleu & Rouge)\n" +
      "2 = Couleurs du Burkina 🇧🇫\n" +
      "3 = Couronne Or VIP 👑\n" +
      "4 = Simple",
      "2"
    );

    if (choix === '1') appliquerCadreAvatar('neon');
    else if (choix === '2') appliquerCadreAvatar('burkina');
    else if (choix === '3') appliquerCadreAvatar('gold');
    else if (choix === '4') appliquerCadreAvatar('simple');
  });
});
// --- 54. ÉGALISEUR MUSICAL ANIMÉ SUR LES VIDÉOS (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  // Ajouter l'animation CSS des barres de son
  const eqStyle = document.createElement('style');
  eqStyle.textContent = `
    @keyframes danseBarre {
      0%, 100% { height: 4px; }
      50% { height: 14px; }
    }
    .eq-container {
      display: inline-flex;
      align-items: flex-end;
      gap: 2px;
      height: 15px;
      margin-right: 6px;
    }
    .eq-bar {
      width: 3px;
      background: #25f4ee;
      border-radius: 2px;
      animation: danseBarre 0.6s infinite ease-in-out;
    }
    .eq-bar:nth-child(2) { animation-delay: 0.2s; background: #fe2c55; }
    .eq-bar:nth-child(3) { animation-delay: 0.4s; background: #feca57; }
  `;
  document.head.appendChild(eqStyle);

  function ajouterEqualiseur(carte) {
    if (carte.dataset.eqReady) return;
    carte.dataset.eqReady = 'true';

    const infoBloc = carte.querySelector('div[style*="left:15px"]');
    if (!infoBloc) return;

    const eqBadge = document.createElement('div');
    eqBadge.style.cssText = 'display:flex; align-items:center; margin-top:6px; font-size:11px; color:#ccc;';
    eqBadge.innerHTML = `
      <span class="eq-container">
        <span class="eq-bar"></span>
        <span class="eq-bar"></span>
        <span class="eq-bar"></span>
      </span>
      <span>Audio stéréo FasoTok 226</span>
    `;

    infoBloc.appendChild(eqBadge);
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(ajouterEqualiseur);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(ajouterEqualiseur);
    }).observe(videoFeed, { childList: true });
  }, 1600);
});
// --- 55. STATUT DE PRÉSENCE EN DIRECT SUR LE PROFIL (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const profilTitre = document.getElementById('profil-titre');
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!profilTitre || !modProfilBtn) return;

  // Créer le badge de statut juste sous le titre du profil
  const statusBadge = document.createElement('div');
  statusBadge.style.cssText = `
    display: inline-block; font-size: 12px; color: #2ecc71;
    background: rgba(46, 204, 113, 0.15); padding: 3px 10px;
    border-radius: 12px; margin-top: 6px; cursor: pointer;
  `;

  function majStatut(code) {
    if (code === 'filming') {
      statusBadge.textContent = '🎬 En plein tournage';
      statusBadge.style.color = '#feca57';
      statusBadge.style.background = 'rgba(254, 202, 87, 0.15)';
    } else if (code === 'busy') {
      statusBadge.textContent = '🔴 Occupé';
      statusBadge.style.color = '#fe2c55';
      statusBadge.style.background = 'rgba(254, 44, 85, 0.15)';
    } else {
      statusBadge.textContent = '🟢 En ligne';
      statusBadge.style.color = '#2ecc71';
      statusBadge.style.background = 'rgba(46, 204, 113, 0.15)';
    }
    localStorage.setItem('fasotok_online_status', code);
  }

  const statutSauve = localStorage.getItem('fasotok_online_status') || 'online';
  majStatut(statutSauve);

  profilTitre.after(document.createElement('br'), statusBadge);

  statusBadge.addEventListener('click', () => {
    const actuel = localStorage.getItem('fasotok_online_status') || 'online';
    if (actuel === 'online') majStatut('filming');
    else if (actuel === 'filming') majStatut('busy');
    else majStatut('online');
  });
});
