// --- 57. MODE MAINS LIBRES / DÉFILEMENT AUTOMATIQUE (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  const homePage = document.getElementById('home-page');
  if (!videoFeed || !homePage) return;

  // Bouton Auto-Scroll en haut à gauche sous la barre des Stories
  const autoScrollBtn = document.createElement('button');
  autoScrollBtn.type = 'button';
  autoScrollBtn.textContent = '⏬ Auto';
  autoScrollBtn.title = 'Défilement automatique mains libres';
  autoScrollBtn.style.cssText = `
    position: fixed; top: 132px; right: 15px;
    background: rgba(22, 24, 35, 0.8); color: #aaa;
    border: 1px solid #444; border-radius: 15px;
    padding: 5px 10px; font-size: 11px; font-weight: bold;
    z-index: 95; cursor: pointer;
  `;

  homePage.appendChild(autoScrollBtn);

  let autoScrollActif = false;

  autoScrollBtn.addEventListener('click', () => {
    autoScrollActif = !autoScrollActif;
    autoScrollBtn.style.color = autoScrollActif ? '#25f4ee' : '#aaa';
    autoScrollBtn.style.borderColor = autoScrollActif ? '#25f4ee' : '#444';
    alert(autoScrollActif ? '⏬ Défilement automatique activé !' : '⏹️ Défilement automatique désactivé.');
  });

  // Surveiller la fin de chaque vidéo pour passer à la suivante
  function activerAutoNext(carte) {
    if (carte.dataset.autoNextReady) return;
    carte.dataset.autoNextReady = 'true';

    const videoEl = carte.querySelector('video');
    if (!videoEl) return;

    videoEl.addEventListener('timeupdate', () => {
      if (autoScrollActif && videoEl.duration && videoEl.currentTime >= videoEl.duration - 0.3) {
        const suivante = carte.nextElementSibling;
        if (suivante && suivante.classList.contains('video-item')) {
          suivante.scrollIntoView({ behavior: 'smooth' });
        }
      }
    });
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(activerAutoNext);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(activerAutoNext);
    }).observe(videoFeed, { childList: true });
  }, 1700);
});
// --- 58. BADGE VIDÉO ÉPINGLÉE SUR LA GRILLE DU PROFIL (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const myGrid = document.getElementById('my-videos-grid');
  if (!myGrid) return;

  function marquerPremiereVideoEpinglee() {
    const vignettes = myGrid.querySelectorAll('div');
    if (vignettes.length === 0) return;

    // Retirer l'ancien badge s'il y en a un
    myGrid.querySelectorAll('.pin-badge-tiktok').forEach(b => b.remove());

    // Ajouter le badge rouge "📌 Épinglé" sur la première vidéo de la grille
    const premiere = vignettes[0];
    premiere.style.position = 'relative';

    const pinBadge = document.createElement('span');
    pinBadge.className = 'pin-badge-tiktok';
    pinBadge.textContent = '📌 Épinglé';
    pinBadge.style.cssText = `
      position: absolute; top: 4px; left: 4px;
      background: #fe2c55; color: white; font-size: 9px;
      font-weight: bold; padding: 2px 5px; border-radius: 4px; z-index: 10;
    `;

    premiere.appendChild(pinBadge);
  }

  setTimeout(marquerPremiereVideoEpinglee, 1500);
  new MutationObserver(marquerPremiereVideoEpinglee).observe(myGrid, { childList: true });
});
