// --- 60. BOUTON ZOOM SUR LES PUBLICATIONS PHOTO (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  function ajouterZoomSurPhotos(carte) {
    if (carte.dataset.zoomReady) return;
    carte.dataset.zoomReady = 'true';

    const imgEl = carte.querySelector('img');
    if (!imgEl) return;

    const zoomBtn = document.createElement('button');
    zoomBtn.type = 'button';
    zoomBtn.textContent = '🔍 Zoom';
    zoomBtn.style.cssText = `
      position: absolute; top: 60px; right: 15px;
      background: rgba(0, 0, 0, 0.6); border: 1px solid rgba(255,255,255,0.3);
      color: white; font-size: 12px; font-weight: bold;
      padding: 6px 12px; border-radius: 15px; z-index: 45; cursor: pointer;
    `;

    let zoome = false;
    zoomBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      zoome = !zoome;
      imgEl.style.transition = 'transform 0.3s ease';
      imgEl.style.transform = zoome ? 'scale(1.5)' : 'scale(1)';
      zoomBtn.textContent = zoome ? '➖ Réduire' : '🔍 Zoom';
    });

    carte.appendChild(zoomBtn);
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(ajouterZoomSurPhotos);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(ajouterZoomSurPhotos);
    }).observe(videoFeed, { childList: true });
  }, 1800);
});
