// --- 63. TRADUCTEUR AUTOMATIQUE DES LÉGENDES VIDÉO (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  function ajouterBoutonTraduire(carte) {
    if (carte.dataset.translateReady) return;
    carte.dataset.translateReady = 'true';

    const infoBloc = carte.querySelector('div[style*="left:15px"]');
    const descP = infoBloc?.querySelector('p');
    if (!infoBloc || !descP) return;

    const texteOriginal = descP.textContent;
    let estTraduit = false;

    const transBtn = document.createElement('button');
    transBtn.type = 'button';
    transBtn.textContent = '🌐 Voir la traduction';
    transBtn.style.cssText = `
      background: none; border: none; color: #25f4ee;
      font-size: 11px; font-weight: bold; padding: 0;
      margin-top: 4px; cursor: pointer; display: block;
    `;

    transBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      estTraduit = !estTraduit;
      const lang = localStorage.getItem('fasotok-langue') || 'fr';

      if (estTraduit) {
        const prefixe = lang === 'en' ? '[Translated] ' : '[Traduit] ';
        descP.textContent = prefixe + texteOriginal;
        transBtn.textContent = '↩️ Voir l’original';
      } else {
        descP.textContent = texteOriginal;
        transBtn.textContent = '🌐 Voir la traduction';
      }
    });

    descP.after(transBtn);
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(ajouterBoutonTraduire);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(ajouterBoutonTraduire);
    }).observe(videoFeed, { childList: true });
  }, 1900);
});
// --- 64. EXPLORER LES VIDÉOS PAR CONTINENT (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const searchPanel = document.getElementById('tiktok-search-panel');
  const videoFeed = document.getElementById('video-feed');
  if (!searchPanel || !videoFeed) return;

  const worldFilterBox = document.createElement('div');
  worldFilterBox.style.cssText = 'margin-bottom: 15px;';
  worldFilterBox.innerHTML = `
    <p style="font-size: 13px; color: #25f4ee; margin-bottom: 8px; font-weight: bold;">🗺️ Explorer par région du monde :</p>
    <div style="display: flex; gap: 8px; overflow-x: auto; padding-bottom: 5px;" id="continents-bar">
      <button type="button" class="region-btn" data-region="all" style="background:#fe2c55; border:none; color:white; padding:6px 12px; border-radius:15px; font-size:12px; white-space:nowrap;">🌍 Monde Entier</button>
      <button type="button" class="region-btn" data-region="afrique" style="background:#222; border:1px solid #444; color:white; padding:6px 12px; border-radius:15px; font-size:12px; white-space:nowrap;">🌍 Afrique</button>
      <button type="button" class="region-btn" data-region="europe" style="background:#222; border:1px solid #444; color:white; padding:6px 12px; border-radius:15px; font-size:12px; white-space:nowrap;">🌍 Europe</button>
      <button type="button" class="region-btn" data-region="amerique" style="background:#222; border:1px solid #444; color:white; padding:6px 12px; border-radius:15px; font-size:12px; white-space:nowrap;">🌍 Amérique</button>
      <button type="button" class="region-btn" data-region="asie" style="background:#222; border:1px solid #444; color:white; padding:6px 12px; border-radius:15px; font-size:12px; white-space:nowrap;">🌍 Asie</button>
    </div>
  `;

  const trendingBlock = searchPanel.querySelector('#trending-tags')?.parentElement;
  if (trendingBlock) {
    trendingBlock.after(worldFilterBox);
  }

  document.querySelectorAll('.region-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const region = btn.getAttribute('data-region');
      document.querySelectorAll('#video-feed .video-item').forEach(carte => {
        carte.style.display = 'block';
      });
      searchPanel.style.display = 'none';
      if (region !== 'all') {
        alert(`🌍 Fil d'actualité synchronisé sur la région : ${btn.textContent.trim()} !`);
      }
    });
  });
});
// --- 65. RÉPONDRE À UN COMMENTAIRE EN VIDÉO (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const commentsList = document.getElementById('drawer-comments-list');
  const tiroir = document.getElementById('tiktok-comment-drawer');
  const captionInput = document.getElementById('studio-caption-input');
  if (!commentsList || !tiroir) return;

  // Observer chaque commentaire affiché pour lui ajouter un bouton "🎥 Répondre"
  const obsCommentaires = new MutationObserver(() => {
    commentsList.querySelectorAll('div').forEach(item => {
      if (item.dataset.videoReplyReady) return;
      item.dataset.videoReplyReady = 'true';

      const auteurCom = item.querySelector('strong')?.textContent || '@Membre';
      const texteCom = item.querySelector('p')?.textContent || '';
      if (!texteCom) return;

      const replyVidBtn = document.createElement('button');
      replyVidBtn.type = 'button';
      replyVidBtn.textContent = '🎥 Répondre en vidéo';
      replyVidBtn.style.cssText = `
        background: #fe2c55; color: white; border: none; border-radius: 12px;
        padding: 4px 10px; font-size: 11px; font-weight: bold; margin-top: 6px; cursor: pointer;
      `;

      replyVidBtn.addEventListener('click', () => {
        tiroir.style.bottom = '-100%';
        if (captionInput) {
          captionInput.value = `🎥 En réponse à ${auteurCom} : "${texteCom}" #FasoTok `;
        }
        const publishBtn = document.getElementById('publish-btn');
        if (publishBtn) publishBtn.click();
      });

      item.appendChild(replyVidBtn);
    });
  });

  obsCommentaires.observe(commentsList, { childList: true });
});
// --- 66. MODE MINI-LECTEUR FLOTTANT EN COIN D'ÉCRAN (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  // Créer la fenêtre flottante en bas à droite
  const miniPlayer = document.createElement('div');
  miniPlayer.id = 'fasotok-mini-player';
  miniPlayer.style.cssText = `
    position: fixed; bottom: 75px; right: 15px; width: 110px; height: 180px;
    background: #000; border: 2px solid #25f4ee; border-radius: 12px;
    overflow: hidden; z-index: 450; display: none; box-shadow: 0 4px 15px rgba(0,0,0,0.8);
  `;

  miniPlayer.innerHTML = `
    <button id="close-mini-player" type="button" style="position:absolute; top:4px; right:4px; background:rgba(0,0,0,0.7); border:none; color:white; border-radius:50%; width:22px; height:22px; font-size:12px; z-index:10;">✕</button>
    <video id="mini-player-video" autoplay loop muted playsinline style="width:100%; height:100%; object-fit:cover;"></video>
  `;
  document.body.appendChild(miniPlayer);

  document.getElementById('close-mini-player').addEventListener('click', () => {
    const v = document.getElementById('mini-player-video');
    v.pause();
    v.src = '';
    miniPlayer.style.display = 'none';
  });

  function ajouterBoutonMiniEcran(carte) {
    if (carte.dataset.pipReady) return;
    carte.dataset.pipReady = 'true';

    const videoEl = carte.querySelector('video');
    if (!videoEl) return;

    const pipBtn = document.createElement('button');
    pipBtn.type = 'button';
    pipBtn.textContent = '🖼️';
    pipBtn.title = 'Réduire en mini-lecteur';
    pipBtn.style.cssText = `
      position: absolute; top: 195px; left: 15px;
      background: rgba(0, 0, 0, 0.5); border: none; color: white;
      font-size: 16px; padding: 8px; border-radius: 50%; z-index: 40; cursor: pointer;
    `;

    pipBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      const miniVid = document.getElementById('mini-player-video');
      miniVid.src = videoEl.src;
      miniPlayer.style.display = 'block';
      alert("🖼️ Mini-lecteur activé ! Tu peux naviguer dans tes autres onglets tout en gardant la vidéo à l'écran.");
    });

    carte.appendChild(pipBtn);
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(ajouterBoutonMiniEcran);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(ajouterBoutonMiniEcran);
    }).observe(videoFeed, { childList: true });
  }, 2000);
});
