// --- 71. RÉGLAGE DE LUMINOSITÉ DANS LE STUDIO DE CRÉATION (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const captionInput = document.getElementById('studio-caption-input');
  const postStudioBtn = document.getElementById('post-studio-btn');
  const videoFeed = document.getElementById('video-feed');
  if (!captionInput || !postStudioBtn || !videoFeed) return;

  // Créer le curseur de luminosité dans le Studio
  const lightBox = document.createElement('div');
  lightBox.style.cssText = 'margin-top: 8px; display: flex; align-items: center; gap: 8px;';
  lightBox.innerHTML = `
    <label for="studio-brightness-range" style="font-size: 12px; color: #feca57; white-space: nowrap;">☀️ Lumière :</label>
    <input type="range" id="studio-brightness-range" min="60" max="160" value="100" style="flex: 1; accent-color: #fe2c55;">
    <span id="brightness-val-label" style="font-size: 11px; color: #ccc; width: 35px;">100%</span>
  `;

  captionInput.before(lightBox);

  const rangeInput = document.getElementById('studio-brightness-range');
  const valLabel = document.getElementById('brightness-val-label');

  rangeInput.addEventListener('input', () => {
    const val = rangeInput.value;
    valLabel.textContent = `${val}%`;
    const media = document.getElementById('studio-media');
    if (media) {
      const filtreBase = media.style.filter.replace(/brightness\([^)]+\)/g, '').trim();
      media.style.filter = `${filtreBase} brightness(${val}%)`.trim();
    }
  });

  postStudioBtn.addEventListener('click', () => {
    const lumiereFinale = rangeInput.value;
    if (lumiereFinale !== '100') {
      setTimeout(() => {
        const nouvelleCarte = videoFeed.firstElementChild;
        const media = nouvelleCarte?.querySelector('video, img');
        if (media) {
          media.style.filter = `${media.style.filter} brightness(${lumiereFinale}%)`.trim();
        }
      }, 150);
    }
    rangeInput.value = '100';
    valLabel.textContent = '100%';
  });
});
