window.addEventListener('load', () => {
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!modProfilBtn) return;

  const inviteBtn = document.createElement('button');
  inviteBtn.type = 'button';
  inviteBtn.textContent = '🤝 Inviter des amis (+100 🪙)';
  inviteBtn.className = 'secondary-btn';
  inviteBtn.style.width = '100%';
  inviteBtn.style.marginTop = '8px';
  inviteBtn.style.borderColor = '#25f4ee';

  modProfilBtn.parentElement.appendChild(inviteBtn);

  inviteBtn.addEventListener('click', () => {
    const pseudo = localStorage.getItem('fasotok_user') || 'CREATEUR';
    const codeParrain = `FT-${pseudo.toUpperCase().slice(0, 6)}-226`;

    const action = confirm(
      `🤝 TON CODE D'INVITATION FASOTOK 🌍 :\n\n` +
      `Code : ${codeParrain}\n\n` +
      `Partage ce code avec tes amis dans le monde entier ! Appuie sur OK pour copier ton message d'invitation et recevoir ton bonus de bienvenue.`
    );

    if (action) {
      const msg = `Rejoins-moi sur FasoTok 🌍 ! Utilise mon code d'invitation ${codeParrain} sur ${window.location.origin}`;
      navigator.clipboard?.writeText(msg);

      if (!localStorage.getItem('fasotok_invite_claimed') && typeof window.getFasoCoins === 'function') {
        window.setFasoCoins(window.getFasoCoins() + 100);
        localStorage.setItem('fasotok_invite_claimed', 'true');
        alert("🎉 Message copié et +100 pièces 🪙 ajoutées à ton portefeuille !");
      } else {
        alert("📋 Message d'invitation copié ! Prêt à être envoyé.");
      }
    }
  });
});
