window.addEventListener('load', () => {
  const profileInfo = document.querySelector('.profile-info-container');
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!profileInfo || !modProfilBtn) return;

  // Créer le badge de lien social sous la bio
  const socialLinkDisplay = document.createElement('a');
  socialLinkDisplay.id = 'profile-social-url';
  socialLinkDisplay.target = '_blank';
  socialLinkDisplay.style.cssText = `
    display: inline-block; margin-top: 8px; color: #25f4ee;
    font-size: 12px; font-weight: bold; text-decoration: none;
  `;

  function majLienSocial() {
    const lienSauve = localStorage.getItem('fasotok_social_link');
    if (lienSauve) {
      socialLinkDisplay.textContent = `🔗 ${lienSauve}`;
      socialLinkDisplay.href = lienSauve.startsWith('http') ? lienSauve : `https://${lienSauve}`;
      socialLinkDisplay.style.display = 'inline-block';
    } else {
      socialLinkDisplay.style.display = 'none';
    }
  }

  const statsDiv = profileInfo.querySelector('.profile-stats');
  if (statsDiv) statsDiv.before(document.createElement('br'), socialLinkDisplay);
  majLienSocial();

  // Bouton dans les paramètres pour ajouter/modifier son lien social
  const addSocialBtn = document.createElement('button');
  addSocialBtn.type = 'button';
  addSocialBtn.textContent = '🔗 Ajouter un lien social (YouTube / Insta)';
  addSocialBtn.className = 'secondary-btn';
  addSocialBtn.style.width = '100%';
  addSocialBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(addSocialBtn);

  addSocialBtn.addEventListener('click', () => {
    const actuel = localStorage.getItem('fasotok_social_link') || '';
    const nouveauLien = prompt("Entre le lien de ta chaîne YouTube, Instagram ou site web :", actuel);
    if (nouveauLien !== null) {
      if (nouveauLien.trim() === '') {
        localStorage.removeItem('fasotok_social_link');
      } else {
        localStorage.setItem('fasotok_social_link', nouveauLien.trim());
      }
      majLienSocial();
    }
  });
});
