// --- 77. GRILLE DES VIDÉOS TENDANCES DANS LA RECHERCHE (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const searchPanel = document.getElementById('tiktok-search-panel');
  const videoFeed = document.getElementById('video-feed');
  if (!searchPanel || !videoFeed) return;

  const gridBox = document.createElement('div');
  gridBox.style.cssText = 'margin-top: 15px;';
  gridBox.innerHTML = `
    <strong style="font-size: 14px; color: #25f4ee; display: block; margin-bottom: 10px;">🎬 À la une dans le monde</strong>
    <div id="search-discover-grid" style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px;"></div>
  `;

  searchPanel.appendChild(gridBox);
  const discoverGrid = document.getElementById('search-discover-grid');

  function majGrilleDecouverte() {
    discoverGrid.innerHTML = '';
    const cartes = videoFeed.querySelectorAll('.video-item');

    cartes.forEach((carte, index) => {
      const auteur = carte.querySelector('h3')?.textContent || '@Créateur';
      const desc = carte.querySelector('p')?.textContent || 'Vidéo FasoTok 🌍';

      const cardMini = document.createElement('div');
      cardMini.style.cssText = `
        background: #161823; border: 1px solid #2b2d3a; border-radius: 10px;
        padding: 12px; cursor: pointer; display: flex; flex-direction: column; justify-content: space-between;
      `;

      cardMini.innerHTML = `
        <span style="font-size: 22px; margin-bottom: 6px;">▶️</span>
        <strong style="font-size: 12px; color: #fe2c55;">${auteur}</strong>
        <p style="font-size: 11px; color: #ccc; margin-top: 4px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${desc}</p>
      `;

      cardMini.addEventListener('click', () => {
        searchPanel.style.display = 'none';
        carte.scrollIntoView({ behavior: 'smooth' });
      });

      discoverGrid.appendChild(cardMini);
    });
  }

  setTimeout(majGrilleDecouverte, 2200);
  new MutationObserver(majGrilleDecouverte).observe(videoFeed, { childList: true });
});
// --- 78. GESTION DES UTILISATEURS BLOQUÉS (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const optionsMenu = document.getElementById('tiktok-video-options');
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!optionsMenu || !modProfilBtn) return;

  // 1. Ajouter le bouton "🚫 Bloquer ce créateur" dans le menu options de la vidéo (⋮)
  const menuList = optionsMenu.querySelector('div[style*="flex-direction:column"]');
  if (menuList) {
    const blockCreatorBtn = document.createElement('button');
    blockCreatorBtn.type = 'button';
    blockCreatorBtn.textContent = '🚫 Bloquer ce créateur';
    blockCreatorBtn.style.cssText = 'padding:12px; background:#222533; border:none; border-radius:10px; color:#ff9f43; text-align:left; font-size:14px;';

    blockCreatorBtn.addEventListener('click', () => {
      const pseudo = prompt("Confirme le @pseudo du créateur à bloquer :");
      if (pseudo && pseudo.trim() !== '') {
        const clean = pseudo.trim().replace('@', '');
        let bloques = JSON.parse(localStorage.getItem('fasotok_blocked_users') || '[]');
        if (!bloques.includes(clean)) {
          bloques.push(clean);
          localStorage.setItem('fasotok_blocked_users', JSON.stringify(bloques));
        }
        optionsMenu.style.bottom = '-100%';
        alert(`🚫 Le compte @${clean} a été ajouté à ta liste noire.`);
      }
    });

    menuList.appendChild(blockCreatorBtn);
  }

  // 2. Ajouter un bouton dans le Profil pour voir ou débloquer les comptes
  const manageBlockedBtn = document.createElement('button');
  manageBlockedBtn.type = 'button';
  manageBlockedBtn.textContent = '🚫 Comptes bloqués';
  manageBlockedBtn.className = 'secondary-btn';
  manageBlockedBtn.style.width = '100%';
  manageBlockedBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(manageBlockedBtn);

  manageBlockedBtn.addEventListener('click', () => {
    const bloques = JSON.parse(localStorage.getItem('fasotok_blocked_users') || '[]');
    if (bloques.length === 0) {
      alert("✅ Tu n'as bloqué aucun compte pour le moment.");
      return;
    }

    const vider = confirm(`🚫 COMPTES BLOQUÉS :\n- @${bloques.join('\n- @')}\n\nAppuie sur OK si tu souhaites débloquer tout le monde.`);
    if (vider) {
      localStorage.removeItem('fasotok_blocked_users');
      alert("🔓 Tous les comptes ont été débloqués.");
    }
  });
});
// --- 79. BOÎTE QUESTIONS & RÉPONSES (Q&A) SUR LE PROFIL (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!modProfilBtn) return;

  const qaBtn = document.createElement('button');
  qaBtn.type = 'button';
  qaBtn.textContent = '❓ Boîte Questions / Réponses (Q&A)';
  qaBtn.className = 'secondary-btn';
  qaBtn.style.width = '100%';
  qaBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(qaBtn);

  qaBtn.addEventListener('click', () => {
    const questions = JSON.parse(localStorage.getItem('fasotok_qa_list') || 'null') || new Array(
      { de: "@AlexParis_Off", q: "Quel téléphone utilises-tu pour filmer tes vidéos ?" },
      { de: "@NYC_Vibes", q: "À quelle fréquence publies-tu sur FasoTok ?" }
    );

    const listeTexte = questions.map((item, i) => `${i + 1}. ${item.de} : « ${item.q} »`).join('\n\n');
    const nouvelleQ = prompt(
      "❓ QUESTIONS DE TES ABONNÉS :\n\n" +
      listeTexte +
      "\n\nÉcris une nouvelle question à ajouter à ton mur Q&A (ou Annuler pour fermer) :"
    );

    if (nouvelleQ && nouvelleQ.trim() !== '') {
      const moi = localStorage.getItem('fasotok_user') || 'MonProfil';
      questions.unshift({ de: `@${moi}`, q: nouvelleQ.trim() });
      localStorage.setItem('fasotok_qa_list', JSON.stringify(questions));
      alert("✅ Ta question a été ajoutée à ton espace Q&A !");
    }
  });
});
// --- 80. ÉPINGLER UN COMMENTAIRE EN HAUT DU TIROIR (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const commentsList = document.getElementById('drawer-comments-list');
  if (!commentsList) return;

  const obsPinComment = new MutationObserver(() => {
    commentsList.querySelectorAll('div').forEach(item => {
      if (item.dataset.pinCommentReady) return;
      item.dataset.pinCommentReady = 'true';

      const pinBtn = document.createElement('button');
      pinBtn.type = 'button';
      pinBtn.textContent = '📌 Épingler';
      pinBtn.style.cssText = `
        background: none; border: 1px solid #444; color: #25f4ee;
        border-radius: 10px; padding: 3px 8px; font-size: 10px;
        margin-top: 6px; margin-left: 6px; cursor: pointer;
      `;

      pinBtn.addEventListener('click', () => {
        // Retirer les anciens badges épinglés
        commentsList.querySelectorAll('.pinned-com-label').forEach(b => b.remove());

        const badge = document.createElement('span');
        badge.className = 'pinned-com-label';
        badge.textContent = '📌 Épinglé par le créateur';
        badge.style.cssText = 'display:block; font-size:10px; color:#feca57; font-weight:bold; margin-bottom:4px;';

        item.prepend(badge);
        commentsList.prepend(item);
      });

      item.appendChild(pinBtn);
    });
  });

  obsPinComment.observe(commentsList, { childList: true });
});
