// --- 82. MODE RALENTI (0.5X) SUR LES VIDÉOS (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  function ajouterBoutonRalenti(carte) {
    if (carte.dataset.slowMoReady) return;
    carte.dataset.slowMoReady = 'true';

    const videoEl = carte.querySelector('video');
    if (!videoEl) return;

    const slowBtn = document.createElement('button');
    slowBtn.type = 'button';
    slowBtn.textContent = '0.5x';
    slowBtn.title = 'Mode ralenti';
    slowBtn.style.cssText = `
      position: absolute; top: 60px; right: 112px;
      background: rgba(0, 0, 0, 0.55); border: 1px solid rgba(255,255,255,0.3);
      color: white; font-size: 12px; font-weight: bold;
      padding: 6px 10px; border-radius: 15px; z-index: 40; cursor: pointer;
    `;

    slowBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (videoEl.playbackRate === 0.5) {
        videoEl.playbackRate = 1;
        slowBtn.style.borderColor = 'rgba(255,255,255,0.3)';
        slowBtn.style.color = 'white';
      } else {
        videoEl.playbackRate = 0.5;
        slowBtn.style.borderColor = '#25f4ee';
        slowBtn.style.color = '#25f4ee';
      }
    });

    carte.appendChild(slowBtn);
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(ajouterBoutonRalenti);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(ajouterBoutonRalenti);
    }).observe(videoFeed, { childList: true });
  }, 2300);
});
// --- 83. COMPTE À REBOURS VISUEL DANS LE STUDIO (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const studioModal = document.getElementById('fasotok-studio-modal');
  const previewBox = document.getElementById('studio-preview-box');
  const captionInput = document.getElementById('studio-caption-input');
  if (!studioModal || !previewBox || !captionInput) return;

  // Bouton Retardateur 3s dans le Studio
  const timerPreviewBtn = document.createElement('button');
  timerPreviewBtn.type = 'button';
  timerPreviewBtn.textContent = '⏱️ Tester un compte à rebours (3s)';
  timerPreviewBtn.style.cssText = `
    width: 100%; padding: 8px; margin-top: 6px; border-radius: 8px;
    border: 1px dashed #feca57; background: #161823; color: #feca57;
    font-size: 12px; font-weight: bold; cursor: pointer;
  `;

  captionInput.after(timerPreviewBtn);

  timerPreviewBtn.addEventListener('click', () => {
    let compteur = 3;
    const chiffreGeant = document.createElement('div');
    chiffreGeant.style.cssText = `
      position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
      font-size: 90px; font-weight: bold; color: #fe2c55;
      text-shadow: 0 0 20px #000; z-index: 50; pointer-events: none;
    `;
    chiffreGeant.textContent = compteur;
    previewBox.appendChild(chiffreGeant);

    const interval = setInterval(() => {
      compteur -= 1;
      if (compteur > 0) {
        chiffreGeant.textContent = compteur;
      } else {
        clearInterval(interval);
        chiffreGeant.textContent = '🎬 Action !';
        chiffreGeant.style.fontSize = '40px';
        setTimeout(() => chiffreGeant.remove(), 900);
      }
    }, 1000);
  });
});

