// --- 85. SÉLECTEUR DE CADRAGE VIDÉO : PLEIN ÉCRAN OU ORIGINAL (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  function ajouterBoutonCadrage(carte) {
    if (carte.dataset.fitReady) return;
    carte.dataset.fitReady = 'true';

    const mediaEl = carte.querySelector('video, img');
    if (!mediaEl) return;

    const fitBtn = document.createElement('button');
    fitBtn.type = 'button';
    fitBtn.textContent = '📐';
    fitBtn.title = 'Adapter le cadrage (Remplir / Entier)';
    fitBtn.style.cssText = `
      position: absolute; top: 240px; left: 15px;
      background: rgba(0, 0, 0, 0.5); border: none; color: white;
      font-size: 16px; padding: 8px; border-radius: 50%; z-index: 40; cursor: pointer;
    `;

    let modeEntier = false;
    fitBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      modeEntier = !modeEntier;
      mediaEl.style.objectFit = modeEntier ? 'contain' : 'cover';
      fitBtn.style.background = modeEntier ? 'rgba(37, 244, 238, 0.7)' : 'rgba(0, 0, 0, 0.5)';
    });

    carte.appendChild(fitBtn);
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(ajouterBoutonCadrage);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(ajouterBoutonCadrage);
    }).observe(videoFeed, { childList: true });
  }, 2400);
});
