// --- 96. CONTRÔLE DU NIVEAU SONORE SUR LES VIDÉOS (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  function ajouterNiveauSonore(carte) {
    if (carte.dataset.volLevelReady) return;
    carte.dataset.volLevelReady = 'true';

    const videoEl = carte.querySelector('video');
    if (!videoEl) return;

    const volBtn = document.createElement('button');
    volBtn.type = 'button';
    volBtn.textContent = '🔊 100%';
    volBtn.style.cssText = `
      position: absolute; top: 285px; left: 15px;
      background: rgba(0, 0, 0, 0.55); border: 1px solid rgba(255,255,255,0.2);
      color: white; font-size: 10px; font-weight: bold;
      padding: 5px 8px; border-radius: 12px; z-index: 40; cursor: pointer;
    `;

    volBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (videoEl.volume === 1) {
        videoEl.volume = 0.5;
        volBtn.textContent = '🔉 50%';
      } else if (videoEl.volume === 0.5) {
        videoEl.volume = 0.2;
        volBtn.textContent = '🔈 20%';
      } else {
        videoEl.volume = 1;
        volBtn.textContent = '🔊 100%';
      }
    });

    carte.appendChild(volBtn);
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(ajouterNiveauSonore);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(ajouterNiveauSonore);
    }).observe(videoFeed, { childList: true });
  }, 2500);
});
// --- 97 & 98. MARQUE-PAGE TEMPOREL ET PARTAGE WHATSAPP DIRECT (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  function ajouterMomentCleEtWhatsApp(carte) {
    if (carte.dataset.milestone98Ready) return;
    carte.dataset.milestone98Ready = 'true';

    const barreActions = carte.querySelector('div[style*="right:15px"]');
    const videoEl = carte.querySelector('video');
    const auteur = carte.querySelector('h3')?.textContent || '@FasoTok';
    if (!barreActions) return;

    // 97. Bouton Marque-Page Temporel (⏱️)
    if (videoEl) {
      const clipBtn = document.createElement('button');
      clipBtn.type = 'button';
      clipBtn.textContent = '⏱️';
      clipBtn.title = 'Marquer ce moment clé';
      clipBtn.style.cssText = `
        position: absolute; top: 330px; left: 15px;
        background: rgba(0, 0, 0, 0.55); border: 1px solid rgba(255,255,255,0.2);
        color: white; font-size: 15px; padding: 6px 8px;
        border-radius: 50%; z-index: 40; cursor: pointer;
      `;

      clipBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        const sec = Math.floor(videoEl.currentTime);
        alert(`⏱️ Moment clé enregistré à 0:${sec < 10 ? '0' + sec : sec} sur la vidéo de ${auteur} !`);
      });

      carte.appendChild(clipBtn);
    }

    // 98. Bouton Partage WhatsApp Direct (📲)
    const waBtn = document.createElement('button');
    waBtn.type = 'button';
    waBtn.textContent = '📲';
    waBtn.title = 'Partager sur WhatsApp';
    waBtn.style.cssText = 'background:none; border:none; font-size:25px; cursor:pointer; margin-top:5px;';
    const waLabel = document.createElement('span');
    waLabel.textContent = 'WhatsApp';
    waLabel.style.cssText = 'font-size:10px; color:#2ecc71; font-weight:bold;';

    waBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      const texte = encodeURIComponent(`🌍 Regarde cette vidéo de ${auteur} sur FasoTok : ${window.location.origin}`);
      window.open(`https://wa.me{texte}`, '_blank');
    });

    barreActions.appendChild(waBtn);
    barreActions.appendChild(waLabel);
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(ajouterMomentCleEtWhatsApp);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(ajouterMomentCleEtWhatsApp);
    }).observe(videoFeed, { childList: true });
  }, 2600);
});
