// --- 101. EFFETS VOCAUX TIKTOK DANS LE STUDIO (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const captionInput = document.getElementById('studio-caption-input');
  const postStudioBtn = document.getElementById('post-studio-btn');
  const videoFeed = document.getElementById('video-feed');
  if (!captionInput || !postStudioBtn || !videoFeed) return;

  const voiceFxBox = document.createElement('div');
  voiceFxBox.style.cssText = 'margin-top: 8px; display: flex; align-items: center; gap: 8px;';
  voiceFxBox.innerHTML = `
    <label for="studio-voice-fx" style="font-size: 12px; color: #25f4ee; white-space: nowrap;">🗣️ Effet Voix :</label>
    <select id="studio-voice-fx" style="flex: 1; padding: 8px; border-radius: 8px; border: 1px solid #333; background: #161823; color: white; font-size: 12px;">
      <option value="1">🎙️ Voix Normale</option>
      <option value="1.35">🐿️ Voix Aiguë (Chipmunk)</option>
      <option value="0.75">🤖 Voix Grave (Robot)</option>
    </select>
  `;

  captionInput.before(voiceFxBox);

  const voiceSelect = document.getElementById('studio-voice-fx');

  voiceSelect.addEventListener('change', () => {
    const media = document.getElementById('studio-media');
    if (media && media.tagName === 'VIDEO') {
      media.playbackRate = parseFloat(voiceSelect.value);
    }
  });

  postStudioBtn.addEventListener('click', () => {
    const vitesseVoix = parseFloat(voiceSelect.value);
    if (vitesseVoix !== 1) {
      setTimeout(() => {
        const nouvelleCarte = videoFeed.firstElementChild;
        const vid = nouvelleCarte?.querySelector('video');
        if (vid) {
          vid.playbackRate = vitesseVoix;
        }
      }, 170);
    }
    voiceSelect.value = '1';
  });
});
// --- 102. GÉNÉRATEUR D'AFFICHE PROMOTIONNELLE DU PROFIL (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!modProfilBtn) return;

  const posterBtn = document.createElement('button');
  posterBtn.type = 'button';
  posterBtn.textContent = '🪪 Générer mon Affiche Créateur';
  posterBtn.className = 'secondary-btn';
  posterBtn.style.width = '100%';
  posterBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(posterBtn);

  posterBtn.addEventListener('click', () => {
    const pseudo = localStorage.getItem('fasotok_user') || 'CreateurGlobal';
    const canvas = document.createElement('canvas');
    canvas.width = 600;
    canvas.height = 800;
    const ctx = canvas.getContext('2d');

    // Fond dégradé TikTok
    const grad = ctx.createLinearGradient(0, 0, 600, 800);
    grad.addColorStop(0, '#000000');
    grad.addColorStop(0.5, '#161823');
    grad.addColorStop(1, '#2b1025');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, 600, 800);

    // Bordure néon
    ctx.strokeStyle = '#fe2c55';
    ctx.lineWidth = 12;
    ctx.strokeRect(20, 20, 560, 760);

    // Textes de l'affiche
    ctx.fillStyle = '#25f4ee';
    ctx.font = 'bold 42px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('FASOTOK 🌍', 300, 160);

    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 48px sans-serif';
    ctx.fillText(`@${pseudo}`, 300, 360);

    ctx.fillStyle = '#feca57';
    ctx.font = '26px sans-serif';
    ctx.fillText('Rejoins-moi et découvre mes vidéos !', 300, 440);

    ctx.fillStyle = '#aaaaaa';
    ctx.font = '22px sans-serif';
    ctx.fillText(window.location.host || 'fasotok.netlify.app', 300, 660);

    // Télécharger l'affiche en image PNG
    const link = document.createElement('a');
    link.download = `Affiche_FasoTok_${pseudo}.png`;
    link.href = canvas.toDataURL('image/png');
    document.body.appendChild(link);
    link.click();
    link.remove();

    alert("🪪 Ton affiche créateur PNG a été enregistrée dans ta galerie !");
  });
});
// --- 103. MINUTEUR D'ARRÊT AUTOMATIQUE POUR LE SOMMEIL (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!modProfilBtn) return;

  const sleepBtn = document.createElement('button');
  sleepBtn.type = 'button';
  sleepBtn.textContent = '😴 Minuteur de sommeil (Arrêt auto)';
  sleepBtn.className = 'secondary-btn';
  sleepBtn.style.width = '100%';
  sleepBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(sleepBtn);

  let sleepTimer = null;

  sleepBtn.addEventListener('click', () => {
    const mins = prompt("Dans combien de minutes veux-tu que les vidéos s'arrêtent automatiquement ? (ex: 10)", "10");
    const delai = parseInt(mins, 10);

    if (!isNaN(delai) && delai > 0) {
      clearTimeout(sleepTimer);
      alert(`😴 Mode sommeil activé ! Toutes les vidéos se mettront en pause dans ${delai} minute(s).`);

      sleepTimer = setTimeout(() => {
        document.querySelectorAll('video, audio').forEach(media => media.pause());
        alert("😴 Bonne nuit ! Le minuteur FasoTok 🌍 a mis les vidéos en pause.");
      }, delai * 60 * 1000);
    }
  });
});
