// --- 109. BADGE VÉRIFIÉ SUR LES VIDÉOS PUBLIÉES (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  function afficherBadgeSurVideos(carte) {
    if (carte.dataset.verifiedVideoReady) return;
    carte.dataset.verifiedVideoReady = 'true';

    const estVerifie = localStorage.getItem('fasotok_verified') === 'true';
    const moi = localStorage.getItem('fasotok_user') || 'FasoCreateur';
    const titreH3 = carte.querySelector('h3');

    if (estVerifie && titreH3 && titreH3.textContent.includes(moi) && !titreH3.textContent.includes('☑️')) {
      titreH3.innerHTML += ' <span style="color:#25f4ee; font-size:14px;">☑️</span>';
    }
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(afficherBadgeSurVideos);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(afficherBadgeSurVideos);
    }).observe(videoFeed, { childList: true });
  }, 2700);
});
