window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  const statsItems = document.querySelectorAll('#profile-page .stat-item');
  if (!videoFeed || statsItems.length === 0) return;

  function majCompteurPosts() {
    const nbTotal = videoFeed.querySelectorAll('.video-item').length;
    statsItems.forEach(stat => {
      if (stat.textContent.includes('J’aime') || stat.textContent.includes('Vidéos') || stat.textContent.includes('Posts')) {
        const strongEl = stat.querySelector('strong');
        if (strongEl && stat.textContent.includes('Vidéos')) {
          strongEl.textContent = nbTotal;
        }
      }
    });
  }

  setTimeout(majCompteurPosts, 1500);
  new MutationObserver(majCompteurPosts).observe(videoFeed, { childList: true });
});
