// --- 127. MODE CINÉMA PUR : MASQUER LES BOUTONS SUR LA VIDÉO (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  function ajouterModeCinemaPur(carte) {
    if (carte.dataset.cleanViewReady) return;
    carte.dataset.cleanViewReady = 'true';

    const cleanBtn = document.createElement('button');
    cleanBtn.type = 'button';
    cleanBtn.textContent = '👁️';
    cleanBtn.title = 'Masquer/Afficher les boutons (Mode Cinéma)';
    cleanBtn.style.cssText = `
      position: absolute; top: 375px; left: 15px;
      background: rgba(0, 0, 0, 0.55); border: 1px solid rgba(255,255,255,0.25);
      color: white; font-size: 15px; padding: 6px 8px;
      border-radius: 50%; z-index: 80; cursor: pointer;
    `;

    let masque = false;
    cleanBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      masque = !masque;

      carte.querySelectorAll('div, button').forEach(el => {
        if (el !== cleanBtn && !el.contains(carte.querySelector('video, img'))) {
          el.style.opacity = masque ? '0' : '1';
          el.style.pointerEvents = masque ? 'none' : 'auto';
        }
      });

      cleanBtn.textContent = masque ? '🙈' : '👁️';
      cleanBtn.style.opacity = '1';
    });

    carte.appendChild(cleanBtn);
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(ajouterModeCinemaPur);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(ajouterModeCinemaPur);
    }).observe(videoFeed, { childList: true });
  }, 2900);
});
