window.addEventListener('load', () => {
  const profileInfo = document.querySelector('.profile-info-container');
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!profileInfo || !modProfilBtn) return;

  // Créer la bannière d'annonce Live sur le profil
  const liveScheduleBadge = document.createElement('div');
  liveScheduleBadge.style.cssText = `
    margin-top: 10px; padding: 8px 12px; border-radius: 10px;
    background: rgba(254, 44, 85, 0.15); border: 1px dashed #fe2c55;
    color: #fff; font-size: 12px; display: none;
  `;

  function majAnnonceLive() {
    const annonce = localStorage.getItem('fasotok_next_live');
    if (annonce) {
      liveScheduleBadge.textContent = `📅 Prochain LIVE : ${annonce}`;
      liveScheduleBadge.style.display = 'block';
    } else {
      liveScheduleBadge.style.display = 'none';
    }
  }

  profileInfo.appendChild(liveScheduleBadge);
  majAnnonceLive();

  // Bouton dans les paramètres pour programmer l'heure du Live
  const scheduleBtn = document.createElement('button');
  scheduleBtn.type = 'button';
  scheduleBtn.textContent = '📅 Programmer mon prochain LIVE';
  scheduleBtn.className = 'secondary-btn';
  scheduleBtn.style.width = '100%';
  scheduleBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(scheduleBtn);

  scheduleBtn.addEventListener('click', () => {
    const actuel = localStorage.getItem('fasotok_next_live') || 'Ce soir à 20h00 GMT 🌍';
    const nouvelleDate = prompt("Indique le jour et l'heure de ton prochain LIVE (ou vide pour effacer) :", actuel);

    if (nouvelleDate !== null) {
      if (nouvelleDate.trim() === '') {
        localStorage.removeItem('fasotok_next_live');
      } else {
        localStorage.setItem('fasotok_next_live', nouvelleDate.trim());
      }
      majAnnonceLive();
    }
  });
});
