// --- 142. BOUTON PIVOTER LA VIDÉO EN LECTURE (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const videoFeed = document.getElementById('video-feed');
  if (!videoFeed) return;

  function ajouterBoutonPivoter(carte) {
    if (carte.dataset.rotateReady) return;
    carte.dataset.rotateReady = 'true';

    const mediaEl = carte.querySelector('video, img');
    if (!mediaEl) return;

    const rotBtn = document.createElement('button');
    rotBtn.type = 'button';
    rotBtn.textContent = '🔄';
    rotBtn.title = 'Pivoter la vidéo de 90°';
    rotBtn.style.cssText = `
      position: absolute; top: 420px; left: 15px;
      background: rgba(0, 0, 0, 0.55); border: 1px solid rgba(255,255,255,0.25);
      color: white; font-size: 14px; padding: 6px 8px;
      border-radius: 50%; z-index: 45; cursor: pointer;
    `;

    let angle = 0;
    rotBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      angle = (angle + 90) % 360;
      mediaEl.style.transition = 'transform 0.3s ease';
      mediaEl.style.transform = `rotate(${angle}deg)`;
    });

    carte.appendChild(rotBtn);
  }

  setTimeout(() => {
    document.querySelectorAll('.video-item').forEach(ajouterBoutonPivoter);
    new MutationObserver(() => {
      document.querySelectorAll('.video-item').forEach(ajouterBoutonPivoter);
    }).observe(videoFeed, { childList: true });
  }, 3000);
});
