window.addEventListener('load', () => {
  const captionInput = document.getElementById('studio-caption-input');
  const postStudioBtn = document.getElementById('post-studio-btn');
  const videoFeed = document.getElementById('video-feed');
  if (!captionInput || !postStudioBtn || !videoFeed) return;

  const tributeBtn = document.createElement('button');
  tributeBtn.type = 'button';
  tributeBtn.textContent = '🙏 Ajouter une dédicace spéciale';
  tributeBtn.style.cssText = `
    width: 100%; padding: 8px; margin-top: 6px; border-radius: 8px;
    border: 1px dashed #25f4ee; background: #161823; color: #25f4ee;
    font-size: 12px; font-weight: bold; cursor: pointer;
  `;

  captionInput.after(tributeBtn);

  let dedicaceTexte = '';

  tributeBtn.addEventListener('click', () => {
    const saisie = prompt("À qui dédies-tu cette vidéo ? (ex: Dédicace à tous mes abonnés 🌍) :", dedicaceTexte);
    if (saisie !== null) {
      dedicaceTexte = saisie.trim();
      tributeBtn.textContent = dedicaceTexte ? `🙏 ${dedicaceTexte}` : '🙏 Ajouter une dédicace spéciale';
    }
  });

  postStudioBtn.addEventListener('click', () => {
    const texteFinal = dedicaceTexte;
    if (texteFinal) {
      setTimeout(() => {
        const nouvelleCarte = videoFeed.firstElementChild;
        const infoBloc = nouvelleCarte?.querySelector('div[style*="left:15px"]');
        if (infoBloc) {
          const badgeDed = document.createElement('p');
          badgeDed.style.cssText = 'font-size: 11px; color: #feca57; font-style: italic; margin-top: 4px;';
          badgeDed.textContent = `🙏 ${texteFinal}`;
          infoBloc.appendChild(badgeDed);
        }
      }, 200);
    }
    dedicaceTexte = '';
    tributeBtn.textContent = '🙏 Ajouter une dédicace spéciale';
  });
});
