// --- 149. CERTIFICAT OFFICIEL DE CRÉATEUR FASOTOK (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!modProfilBtn) return;

  const certBtn = document.createElement('button');
  certBtn.type = 'button';
  certBtn.textContent = '📜 Télécharger mon Certificat Créateur (100%)';
  certBtn.className = 'secondary-btn';
  certBtn.style.width = '100%';
  certBtn.style.marginTop = '8px';
  certBtn.style.borderColor = '#feca57';

  modProfilBtn.parentElement.appendChild(certBtn);

  certBtn.addEventListener('click', () => {
    const pseudo = localStorage.getItem('fasotok_user') || 'FondateurGlobal';
    const canvas = document.createElement('canvas');
    canvas.width = 800;
    canvas.height = 550;
    const ctx = canvas.getContext('2d');

    ctx.fillStyle = '#0d0f17';
    ctx.fillRect(0, 0, 800, 550);

    ctx.strokeStyle = '#feca57';
    ctx.lineWidth = 10;
    ctx.strokeRect(20, 20, 760, 510);

    ctx.fillStyle = '#25f4ee';
    ctx.font = 'bold 34px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('CERTIFICAT OFFICIEL FASOTOK 🌍', 400, 110);

    ctx.fillStyle = '#ffffff';
    ctx.font = '24px sans-serif';
    ctx.fillText('Décerné au créateur et développeur :', 400, 190);

    ctx.fillStyle = '#fe2c55';
    ctx.font = 'bold 46px sans-serif';
    ctx.fillText(`@${pseudo}`, 400, 270);

    ctx.fillStyle = '#feca57';
    ctx.font = 'bold 22px sans-serif';
    ctx.fillText('Programme Complet : 150 / 150 Modules Accomplis (100%)', 400, 360);

    ctx.fillStyle = '#aaaaaa';
    ctx.font = '18px sans-serif';
    ctx.fillText(`Validé le ${new Date().toLocaleDateString('fr-FR')}`, 400, 440);

    const link = document.createElement('a');
    link.download = `Certificat_FasoTok_${pseudo}.png`;
    link.href = canvas.toDataURL('image/png');
    document.body.appendChild(link);
    link.click();
    link.remove();

    alert("📜 Félicitations ! Ton Certificat Officiel 100 % a été enregistré dans ta galerie !");
  });
});
