// --- 152. SONDAGE INTERACTIF DANS LA MESSAGERIE DIRECTE (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const chatForm = document.getElementById('inbox-chat-form');
  const chatBox = document.getElementById('chat-messages-box');
  if (!chatForm || !chatBox) return;

  const chatPollBtn = document.createElement('button');
  chatPollBtn.type = 'button';
  chatPollBtn.textContent = '🗳️';
  chatPollBtn.title = 'Créer un sondage dans le chat';
  chatPollBtn.style.cssText = `
    background: #feca57; color: #000; border: none; border-radius: 50%;
    width: 42px; height: 42px; font-size: 18px; cursor: pointer; flex-shrink: 0;
  `;

  chatForm.insertBefore(chatPollBtn, chatForm.firstChild);

  chatPollBtn.addEventListener('click', () => {
    const question = prompt("Pose ta question dans le chat (ex: On fait un LIVE ce soir ?) :");
    if (!question || question.trim() === '') return;

    const bulleSondage = document.createElement('div');
    bulleSondage.style.cssText = `
      background: #161823; border: 1px solid #feca57; color: white;
      padding: 12px; border-radius: 14px; align-self: flex-end; max-width: 85%;
    `;
    bulleSondage.innerHTML = `
      <strong style="font-size:13px; color:#feca57; display:block; margin-bottom:8px;">🗳️ ${question.trim()}</strong>
      <div style="display:flex; gap:8px;">
        <button type="button" class="chat-vote-opt" style="flex:1; padding:6px; background:#222533; border:1px solid #444; color:white; border-radius:8px; font-size:12px;">✅ Oui (0)</button>
        <button type="button" class="chat-vote-opt" style="flex:1; padding:6px; background:#222533; border:1px solid #444; color:white; border-radius:8px; font-size:12px;">❌ Non (0)</button>
      </div>
    `;

    bulleSondage.querySelectorAll('.chat-vote-opt').forEach((optBtn, index) => {
      let votes = 0;
      optBtn.addEventListener('click', () => {
        votes += 1;
        optBtn.textContent = index === 0 ? `✅ Oui (${votes})` : `❌ Non (${votes})`;
        optBtn.style.borderColor = '#25f4ee';
      });
    });

    chatBox.appendChild(bulleSondage);
    chatBox.scrollTop = chatBox.scrollHeight;
  });
});
