// --- 186. BILAN DE STOCKAGE LOCAL DES MÉDIAS SUR LE PROFIL (PARTIE 2/2) ---
window.addEventListener('load', () => {
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!modProfilBtn) return;

  const storageBtn = document.createElement('button');
  storageBtn.type = 'button';
  storageBtn.textContent = '💽 Vérifier l’espace de stockage médias';
  storageBtn.className = 'secondary-btn';
  storageBtn.style.width = '100%';
  storageBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(storageBtn);

  storageBtn.addEventListener('click', async () => {
    const nbCartes = document.querySelectorAll('#video-feed .video-item').length;
    let estimation = 'Calcul non disponible';

    if (navigator.storage && navigator.storage.estimate) {
      const est = await navigator.storage.estimate();
      const utiliseMo = ((est.usage || 0) / (1024 * 1024)).toFixed(2);
      estimation = `${utiliseMo} Mo utilisés`;
    }

    alert(
      "💽 STOCKAGE LOCAL FASOTOK 🌍\n\n" +
      `🎬 Publications chargées : ${nbCartes}\n` +
      `📦 Espace occupé sur le téléphone : ${estimation}\n` +
      "✅ État de la base IndexedDB : Opérationnelle"
    );
  });
});
