// --- 199. ZOOM PLEIN ÉCRAN SUR L'AVATAR DU PROFIL (PARTIE 1/2) ---
window.addEventListener('load', () => {
  const avatarEl = document.querySelector('#profile-page .profile-avatar, #profile-page img');
  if (!avatarEl) return;

  avatarEl.style.cursor = 'pointer';
  avatarEl.title = 'Toucher pour agrandir la photo';

  avatarEl.addEventListener('click', () => {
    const overlay = document.createElement('div');
    overlay.style.cssText = `
      position: fixed; inset: 0; background: rgba(0,0,0,0.92);
      display: flex; flex-direction: column; align-items: center;
      justify-content: center; z-index: 9999; padding: 20px;
    `;

    const imgSrc = avatarEl.tagName === 'IMG' ? avatarEl.src : '';
    overlay.innerHTML = imgSrc
      ? `<img src="${imgSrc}" style="max-width:85vw; max-height:70vh; border-radius:20px; border:3px solid #25f4ee;">`
      : `<div style="width:180px; height:180px; border-radius:50%; background:#fe2c55; display:flex; align-items:center; justify-content:center; font-size:70px;">👤</div>`;

    const closeText = document.createElement('p');
    closeText.textContent = '✕ Toucher n’importe où pour fermer';
    closeText.style.cssText = 'color:#ccc; font-size:13px; margin-top:16px;';
    overlay.appendChild(closeText);

    overlay.addEventListener('click', () => overlay.remove());
    document.body.appendChild(overlay);
  });
});
