window.addEventListener('load', () => {
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!modProfilBtn) return;

  const profileSearch = document.createElement('input');
  profileSearch.type = 'text';
  profileSearch.placeholder = '🔍 Rechercher un outil ou paramètre (ex: Certificat, Revenus, Jeu)...';
  profileSearch.style.cssText = `
    width: 100%; padding: 10px 12px; margin-top: 12px; margin-bottom: 6px;
    border-radius: 10px; border: 1px solid #25f4ee; background: #161823;
    color: white; font-size: 13px; box-sizing: border-box;
  `;

  modProfilBtn.before(profileSearch);

  profileSearch.addEventListener('input', () => {
    const motCle = profileSearch.value.toLowerCase().trim();
    const conteneur = modProfilBtn.parentElement;

    conteneur.querySelectorAll('.secondary-btn').forEach(btn => {
      if (btn === modProfilBtn) return;
      const texteBtn = btn.textContent.toLowerCase();
      btn.style.display = texteBtn.includes(motCle) ? 'block' : 'none';
    });
  });
});
