  hashtagGenBtn.type = 'button';
  hashtagGenBtn.textContent = '#️⃣ Copier des #hashtags viraux par thème';
  hashtagGenBtn.className = 'secondary-btn';
  hashtagGenBtn.style.width = '100%';
  hashtagGenBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(hashtagGenBtn);

  hashtagGenBtn.addEventListener('click', () => {
    const choix = prompt(
      "#️⃣ CHOISIS TON THÈME POUR COPIER LES HASHTAGS :\n" +
      "1 - Musique & Danse 🎶\n" +
      "2 - Humour & Comédie 😂\n" +
      "3 - Sport & Exploits ⚽\n" +
      "4 - Général & Viral 🌍",
      "4"
    );

    const packs = {
      '1': '#FasoTok #Afrobeat #DanceChallenge #MusicVibes #ForYou #Viral',
      '2': '#FasoTok #Humour #Comedie #MDR #Drole #PourToi #FYP',
      '3': '#FasoTok #Football #Sport #Skills #Champion #WorldCup #Viral',
      '4': '#FasoTok #ForYou #PourToi #Trending #ViralVideo #Global 🌍'
    };

    const selection = packs[choix] || packs['4'];
    navigator.clipboard?.writeText(selection);
    alert(`✅ Hashtags copiés dans ton presse-papiers :\n\n${selection}`);
  });
