window.addEventListener('load', () => {
  const captionInput = document.getElementById('studio-caption-input');
  if (!captionInput) return;

  const studioSearchInput = document.createElement('input');
  studioSearchInput.type = 'text';
  studioSearchInput.placeholder = '🔍 Chercher un filtre (ex: Or, Nuit, Cinéma, Rose)...';
  studioSearchInput.style.cssText = `
    width: 100%; padding: 9px 12px; margin-top: 8px; margin-bottom: 4px;
    border-radius: 8px; border: 1px solid #feca57; background: #161823;
    color: white; font-size: 12px; box-sizing: border-box;
  `;

  captionInput.after(studioSearchInput);

  studioSearchInput.addEventListener('input', () => {
    const mot = studioSearchInput.value.toLowerCase().trim();
    const modalBox = studioSearchInput.parentElement;

    modalBox.querySelectorAll('button').forEach(btn => {
      if (btn.id === 'post-studio-btn' || btn.textContent.includes('Annuler') || btn.textContent.includes('Fermer')) return;
      if (btn.textContent.includes('Appliquer') || btn.textContent.includes('Activer') || btn.textContent.includes('Mode')) {
        btn.style.display = btn.textContent.toLowerCase().includes(mot) ? 'block' : 'none';
      }
    });
  });
});
