window.addEventListener('load', () => {
  const modProfilBtn = document.getElementById('modifier-profil-btn');
  if (!modProfilBtn) return;

  const coinPlanBtn = document.createElement('button');
  coinPlanBtn.type = 'button';
  coinPlanBtn.textContent = '🪙 Planifier mon objectif de pièces';
  coinPlanBtn.className = 'secondary-btn';
  coinPlanBtn.style.width = '100%';
  coinPlanBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(coinPlanBtn);

  coinPlanBtn.addEventListener('click', () => {
    const coinsActuels = parseInt(localStorage.getItem('fasotok_coins') || '100', 10);
    const cibleSaisie = prompt(`Tu as actuellement ${coinsActuels} 🪙.\nCombien de pièces vises-tu ? (ex: 1000)`, "1000");
    const cible = parseInt(cibleSaisie, 10);

    if (!isNaN(cible) && cible > coinsActuels) {
      const manque = cible - coinsActuels;
      const joursEstimes = Math.ceil(manque / 50);
      alert(
        `🪙 PLAN D'ACTION POUR ${cible} PIÈCES :\n\n` +
        `📉 Pièces manquantes : ${manque} 🪙\n` +
        `📅 Temps estimé : ~${joursEstimes} jour(s) avec les bonus quotidiens et la roue !`
      );
    }
  });
});
