  autoSignBtn.className = 'secondary-btn';
  autoSignBtn.style.width = '100%';
  autoSignBtn.style.marginTop = '8px';

  modProfilBtn.parentElement.appendChild(autoSignBtn);

  autoSignBtn.addEventListener('click', () => {
    const sigActuelle = localStorage.getItem('fasotok_auto_signature') || '#FasoTok 🌍 #ForYou';
    const nouvelleSig = prompt("✍️ SIGNATURE AJOUTÉE À TES LÉGENDES :", sigActuelle);

    if (nouvelleSig !== null) {
      localStorage.setItem('fasotok_auto_signature', nouvelleSig.trim());
      alert("✅ Signature automatique enregistrée !");
    }
  });

  if (captionInput && postStudioBtn) {
    postStudioBtn.addEventListener('click', () => {
      const sig = localStorage.getItem('fasotok_auto_signature');
      if (sig && !captionInput.value.includes(sig)) {
        captionInput.value = `${captionInput.value} ${sig}`.trim();
      }
    }, true);
  }
