// --- 301. COMPTEUR DE PERFORMANCES & MÉMOIRE LOCALE (SUR LE PROFIL) ---
window.addEventListener('load', () => {
  const profileInfo = document.querySelector('.profile-info-container');
  const logoutBtn = document.getElementById('deconnexion-fasotok');

  if (profileInfo && logoutBtn) {
    const perfBtn = document.createElement('button');
    perfBtn.type = 'button';
    perfBtn.textContent = '⚡ Diagnostic & Stockage FasoTok';
    perfBtn.className = 'secondary-btn';
    perfBtn.style.width = '100%';
    perfBtn.style.marginBottom = '10px';
    perfBtn.style.borderColor = '#25f4ee';

    logoutBtn.before(perfBtn);

    perfBtn.addEventListener('click', () => {
      // Calcul de l'espace utilisé dans localStorage
      let totalBytes = 0;
      for (let key in localStorage) {
        if (localStorage.hasOwnProperty(key)) {
          totalBytes += (localStorage[key].length + key.length) * 2;
        }
      }
      const usedKB = (totalBytes / 1024).toFixed(2);
      const domElements = document.getElementsByTagName('*').length;

      alert(
        "⚡ DIAGNOSTIC TECHNIQUE FASOTOK\n\n" +
        `📦 Stockage local utilisé : ${usedKB} Ko\n` +
        `🧩 Éléments actifs à l'écran : ${domElements}\n` +
        `🌐 Statut réseau : ${navigator.onLine ? 'En ligne 🟢' : 'Mode Hors-Ligne 🔴'}\n` +
        "🚀 Optimisation mobile : Active"
      );
    });
  }
});

// --- 302. MODE ÉCONOMIE DE DONNÉES (DATA SAVER BURKINA) ---
window.addEventListener('load', () => {
  const logoutBtn = document.getElementById('deconnexion-fasotok');
  if (!logoutBtn) return;

  let dataSaverActive = localStorage.getItem('fasotok_datasaver') === 'true';

  const applyDataSaver = (active) => {
    document.querySelectorAll('video').forEach((vid) => {
      if (active) {
        vid.removeAttribute('autoplay');
        vid.preload = 'none';
      } else {
        vid.preload = 'metadata';
      }
    });
  };

  applyDataSaver(dataSaverActive);

  const dataBtn = document.createElement('button');
  dataBtn.type = 'button';
  dataBtn.className = 'secondary-btn';
  dataBtn.style.width = '100%';
  dataBtn.style.marginBottom = '10px';

  const updateDataBtnText = () => {
    dataBtn.textContent = dataSaverActive
      ? '📶 Économie de Data : ACTIVÉE (Clic pour désactiver)'
      : '📶 Économie de Data : DÉSACTIVÉE';
    dataBtn.style.borderColor = dataSaverActive ? '#2ed573' : '#555';
  };

  updateDataBtnText();
  logoutBtn.before(dataBtn);

  dataBtn.addEventListener('click', () => {
    dataSaverActive = !dataSaverActive;
    localStorage.setItem('fasotok_datasaver', dataSaverActive);
    applyDataSaver(dataSaverActive);
    updateDataBtnText();
  });
});

