// --- 304. SAUVEGARDE & RESTAURATION JSON DU COMPTE FASOTOK ---
window.addEventListener('load', () => {
  const logoutBtn = document.getElementById('deconnexion-fasotok');
  if (!logoutBtn) return;

  const backupBtn = document.createElement('button');
  backupBtn.type = 'button';
  backupBtn.textContent = '💾 Exporter ma Sauvegarde FasoTok (.json)';
  backupBtn.className = 'secondary-btn';
  backupBtn.style.width = '100%';
  backupBtn.style.marginBottom = '10px';
  backupBtn.style.borderColor = '#25f4ee';

  logoutBtn.before(backupBtn);

  backupBtn.addEventListener('click', () => {
    const dataToSave = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      dataToSave[key] = localStorage.getItem(key);
    }

    const blob = new Blob([JSON.stringify(dataToSave, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `fasotok_backup_${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
  });
});

