// --- 313. MOTEUR DE MIGRATION AUTOMATIQUE VERS SUPABASE ---
window.addEventListener('load', () => {
  // Configuration prête pour le lancement (remplace par tes vraies clés Supabase le jour J)
  window.FASOTOK_SUPABASE_CONFIG = {
    url: 'https://supabase.co',
    anonKey: 'TA-CLE-PUBLIQUE-ANON',
    table: 'profiles'
  };

  window.syncFasoTokToSupabase = async (userId) => {
    if (!window.supabaseClient) {
      console.info('[FasoTok Cloud] Client Supabase non encore initialisé. Données mises en file d’attente.');
      return { status: 'queued', data: window.getFasoTokCloudPayload ? window.getFasoTokCloudPayload() : {} };
    }

    const payload = window.getFasoTokCloudPayload ? window.getFasoTokCloudPayload() : {};
    const { data, error } = await window.supabaseClient
      .from(window.FASOTOK_SUPABASE_CONFIG.table)
      .upsert({ id: userId, ...payload }, { onConflict: 'id' });

    if (error) {
      console.error('[FasoTok Cloud] Erreur de synchronisation :', error.message);
      return { status: 'error', error };
    }
    return { status: 'synced', data };
  };
});

