// --- 316. BOUCLIER ANTI-DOUBLURE GLOBAL & NETTOYEUR DOM ---
(() => {

  // 1. Registre global anti-double exécution
  window.FASOTOK_LOADED_MODULES =
    window.FASOTOK_LOADED_MODULES || new Set();

  window.registerFasoTokModule = (moduleId, initFn) => {
    if (window.FASOTOK_LOADED_MODULES.has(moduleId)) {
      console.warn(
        `[FasoTok Anti-Doublure] Module ${moduleId} déjà actif.`
      );
      return false;
    }

    window.FASOTOK_LOADED_MODULES.add(moduleId);

    try {
      initFn();
      return true;
    } catch (error) {
      window.FASOTOK_LOADED_MODULES.delete(moduleId);
      console.error(`[FasoTok] Erreur module ${moduleId}:`, error);
      return false;
    }
  };

  // 2. Nettoyage des boutons secondaires en double
  window.addEventListener('load', () => {
    window.registerFasoTokModule('MOD_316_ANTI_DOUBLURE', () => {
      const seenTexts = new Set();

      const profileButtons =
        document.querySelectorAll('.secondary-btn');

      profileButtons.forEach((btn) => {
        const label = btn.textContent.trim().toLowerCase();

        if (!label) return;

        if (seenTexts.has(label)) {
          btn.remove();
          console.warn('[FasoTok] Bouton doublon supprimé:', label);
        } else {
          seenTexts.add(label);
        }
      });
    });
  });

  // 3. Déduplication de la file des signalements
  try {
    const reports = JSON.parse(
      localStorage.getItem('fasotok_reports_queue') || '[]'
    );

    const uniqueReports = reports.filter(
      (item, index, self) =>
        index === self.findIndex((r) => r.reason === item.reason)
    );

    localStorage.setItem(
      'fasotok_reports_queue',
      JSON.stringify(uniqueReports)
    );
  } catch (error) {
    console.error('[FasoTok] Erreur de nettoyage des signalements:', error);
  }

})();

