// --- 323. PORTAIL AUTHENTIFICATION MONDIALE SUPABASE (INSCRIPTION / CONNEXION) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_323_SUPABASE_AUTH', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-323')) return;

    const authBtn = document.createElement('button');
    authBtn.id = 'btn-mod-323';
    authBtn.type = 'button';
    authBtn.textContent = '🔐 Compte Cloud Mondial (Connexion / Inscription)';
    authBtn.className = 'secondary-btn';
    authBtn.style.width = '100%';
    authBtn.style.marginBottom = '10px';
    authBtn.style.borderColor = '#3ecf8e';

    logoutBtn.before(authBtn);

    authBtn.addEventListener('click', async () => {
      if (!window.supabaseClient) {
        alert('🟡 Configure d’abord tes clés Supabase via le bouton "🔌 Configurer les Clés Supabase" avant d’activer les inscriptions publiques.');
        return;
      }

      const email = prompt('📧 Entre ton adresse e-mail pour ton compte mondial FasoTok :');
      if (!email || !email.includes('@')) return;

      const password = prompt('🔑 Choisis un mot de passe (6 caractères minimum) :');
      if (!password || password.length < 6) {
        alert('❌ Le mot de passe doit contenir au moins 6 caractères.');
        return;
      }

      // Tente la connexion, sinon crée le compte automatiquement
      const { data: signInData, error: signInError } = await window.supabaseClient.auth.signInWithPassword({
        email: email.trim(),
        password
      });

      if (!signInError && signInData?.user) {
        if (window.syncFasoTokToSupabase) await window.syncFasoTokToSupabase(signInData.user.id);
        alert('🟢 Connexion réussie ! Ton profil local a été synchronisé avec Supabase.');
        return;
      }

      const { data: signUpData, error: signUpError } = await window.supabaseClient.auth.signUp({
        email: email.trim(),
        password
      });

      if (signUpError) {
        alert(`❌ Erreur Supabase : ${signUpError.message}`);
      } else {
        if (signUpData?.user && window.syncFasoTokToSupabase) {
          await window.syncFasoTokToSupabase(signUpData.user.id);
        }
        alert('🎉 Compte mondial FasoTok créé ! Vérifie ta boîte mail si la confirmation est activée sur Supabase.');
      }
    });
  });
});

