// --- 326. PUBLICATION DE VIDÉO PUBLIQUE MONDIALE (PRÊTE POUR SUPABASE) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_326_GLOBAL_VIDEO_PUBLISH', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-326')) return;

    const pubBtn = document.createElement('button');
    pubBtn.id = 'btn-mod-326';
    pubBtn.type = 'button';
    pubBtn.textContent = '🎬 Publier une Vidéo Mondiale (Cloud)';
    pubBtn.className = 'secondary-btn';
    pubBtn.style.width = '100%';
    pubBtn.style.marginBottom = '10px';
    pubBtn.style.borderColor = '#fe2c55';

    logoutBtn.before(pubBtn);

    pubBtn.addEventListener('click', async () => {
      const title = prompt('🎬 Titre ou description de ta vidéo publique (avec #hashtags) :');
      if (!title || title.trim().length < 2) return;

      const videoUrl = prompt('🔗 Colle le lien public de la vidéo (MP4 / Supabase Storage / Cloudinary) :');
      if (!videoUrl || !videoUrl.startsWith('http')) {
        alert('❌ Lien vidéo invalide. Il doit commencer par http:// ou https://');
        return;
      }

      const newPost = {
        title: title.trim(),
        video_url: videoUrl.trim(),
        country: localStorage.getItem('fasotok_country') || '🇧🇫 Burkina Faso',
        created_at: new Date().toISOString()
      };

      // Envoi direct vers Supabase si connecté
      if (window.supabaseClient) {
        const { data: userData } = await window.supabaseClient.auth.getUser();
        const { error } = await window.supabaseClient.from('videos').insert({
          user_id: userData?.user?.id || null,
          ...newPost
        });

        if (!error) {
          alert('🌍 Vidéo publiée en direct sur le réseau mondial FasoTok (Supabase) !');
          return;
        }
      }

      // Sinon sauvegarde dans la file d'attente locale prête pour le lancement
      const queue = JSON.parse(localStorage.getItem('fasotok_videos_queue') || '[]');
      queue.unshift(newPost);
      localStorage.setItem('fasotok_videos_queue', JSON.stringify(queue));
      alert('✅ Vidéo enregistrée dans ta file de publication mondiale ! Elle sera diffusée dès la connexion Supabase.');
    });
  });
});

