// --- 330. SOUTIEN & DONS EN FASOCOINS ENTRE UTILISATEURS ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_330_CREATOR_TIPS', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-330')) return;

    const tipBtn = document.createElement('button');
    tipBtn.id = 'btn-mod-330';
    tipBtn.type = 'button';
    tipBtn.textContent = '💝 Envoyer un Cadeau (FasoCoins)';
    tipBtn.className = 'secondary-btn';
    tipBtn.style.width = '100%';
    tipBtn.style.marginBottom = '10px';
    tipBtn.style.borderColor = '#ff6b81';

    logoutBtn.before(tipBtn);

    tipBtn.addEventListener('click', () => {
      let balance = parseInt(localStorage.getItem('fasotok_coins') || '100', 10);
      const targetUser = prompt('👤 Entre le nom du créateur à soutenir (ex: @OuagaVibes) :');
      if (!targetUser || targetUser.trim().length < 2) return;

      const amount = parseInt(prompt(`🪙 Combien de FasoCoins veux-tu envoyer ? (Ton solde : ${balance})`, '20'), 10);
      if (isNaN(amount) || amount <= 0) return;

      if (amount > balance) {
        alert(`❌ Solde insuffisant (${balance} FasoCoins disponibles).`);
        return;
      }

      balance -= amount;
      localStorage.setItem('fasotok_coins', balance);

      // Enregistre la transaction dans une file prête pour Supabase
      const tips = JSON.parse(localStorage.getItem('fasotok_tips_history') || '[]');
      tips.push({
        to_user: targetUser.trim(),
        amount,
        created_at: new Date().toISOString()
      });
      localStorage.setItem('fasotok_tips_history', JSON.stringify(tips));

      alert(`💝 Bravo ! Tu as envoyé ${amount} FasoCoins à ${targetUser.trim()}.\nNouveau solde : ${balance} FasoCoins.`);
    });
  });
});

// --- 331. SCRIPT SQL SUPABASE COMPLET (VIDÉOS, ANNONCES & SÉCURITÉ PUBLIQUE) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_331_SUPABASE_SQL_PART2', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-331')) return;

    const sql2Btn = document.createElement('button');
    sql2Btn.id = 'btn-mod-331';
    sql2Btn.type = 'button';
    sql2Btn.textContent = '🗄️ Copier le SQL Vidéos & Annonces (Supabase)';
    sql2Btn.className = 'secondary-btn';
    sql2Btn.style.width = '100%';
    sql2Btn.style.marginBottom = '10px';
    sql2Btn.style.borderColor = '#3ecf8e';

    logoutBtn.before(sql2Btn);

    sql2Btn.addEventListener('click', async () => {
      const sqlPart2 = `
CREATE TABLE IF NOT EXISTS videos (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id UUID REFERENCES auth.users(id),
  title TEXT NOT NULL,
  video_url TEXT NOT NULL,
  country TEXT DEFAULT '🇧🇫 Burkina Faso',
  likes INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS announcements (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  message TEXT NOT NULL,
  active BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE videos ENABLE ROW LEVEL SECURITY;
ALTER TABLE announcements ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Lecture publique profils" ON profiles FOR SELECT USING (true);
CREATE POLICY "Lecture publique videos" ON videos FOR SELECT USING (true);
CREATE POLICY "Lecture publique annonces" ON announcements FOR SELECT USING (true);
      `.trim();

      if (navigator.clipboard) {
        await navigator.clipboard.writeText(sqlPart2);
        alert('✅ Script SQL Vidéos + Annonces + Sécurité RLS copié !\nColle-le dans Supabase SQL Editor pour ouvrir la lecture publique au monde entier.');
      } else {
        prompt('Copie ce script SQL pour Supabase :', sqlPart2);
      }
    });
  });
});
