// --- 338. LIKES MONDIAUX EN DIRECT SUR LES VIDÉOS (SUPABASE) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_338_GLOBAL_LIKES', () => {
    window.likeFasoTokVideo = async (videoId, currentLikes = 0) => {
      const likedKey = `fasotok_liked_${videoId}`;
      if (localStorage.getItem(likedKey) === 'true') {
        alert('❤️ Tu as déjà aimé cette vidéo !');
        return;
      }

      localStorage.setItem(likedKey, 'true');

      if (window.supabaseClient) {
        const { error } = await window.supabaseClient
          .from('videos')
          .update({ likes: currentLikes + 1 })
          .eq('id', videoId);

        if (!error) {
          alert(`❤️ Like enregistré sur le serveur mondial ! (Total : ${currentLikes + 1})`);
          return;
        }
      }

      alert('❤️ Like enregistré localement (prêt pour la synchronisation Supabase) !');
    };
  });
});

// --- 339. SYSTÈME D'ABONNEMENT ENTRE CRÉATEURS MONDIAUX (FOLLOW) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_339_GLOBAL_FOLLOW', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-339')) return;

    const followBtn = document.createElement('button');
    followBtn.id = 'btn-mod-339';
    followBtn.type = 'button';
    followBtn.textContent = '➕ Suivre un Créateur (Abonnements)';
    followBtn.className = 'secondary-btn';
    followBtn.style.width = '100%';
    followBtn.style.marginBottom = '10px';
    followBtn.style.borderColor = '#fe2c55';

    logoutBtn.before(followBtn);

    followBtn.addEventListener('click', async () => {
      const following = JSON.parse(localStorage.getItem('fasotok_following_list') || '[]');
      const target = prompt(
        `👥 Tu suis actuellement ${following.length} créateur(s).\n` +
        `Entre le @pseudo du créateur mondial que tu veux suivre :`
      );

      if (!target || target.trim().length < 2) return;
      const cleanName = target.trim();

      if (following.includes(cleanName)) {
        alert(`✅ Tu es déjà abonné à ${cleanName} !`);
        return;
      }

      following.push(cleanName);
      localStorage.setItem('fasotok_following_list', JSON.stringify(following));

      if (window.supabaseClient) {
        const { data: userData } = await window.supabaseClient.auth.getUser();
        if (userData?.user) {
          await window.supabaseClient.from('follows').insert({
            follower_id: userData.user.id,
            target_username: cleanName
          });
        }
      }

      alert(`🎉 Tu suis maintenant ${cleanName} ! (Total abonnements : ${following.length})`);
    });
  });
});

// --- 340. UPLOAD DE VIDÉO DEPUIS LE TÉLÉPHONE VERS SUPABASE STORAGE ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_340_SUPABASE_STORAGE_UPLOAD', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-340')) return;

    const fileInput = document.createElement('input');
    fileInput.id = 'input-video-mod-340';
    fileInput.type = 'file';
    fileInput.accept = 'video/*';
    fileInput.style.display = 'none';
    document.body.appendChild(fileInput);

    const uploadBtn = document.createElement('button');
    uploadBtn.id = 'btn-mod-340';
    uploadBtn.type = 'button';
    uploadBtn.textContent = '📤 Envoyer une Vidéo depuis mon Téléphone (Cloud)';
    uploadBtn.className = 'secondary-btn';
    uploadBtn.style.width = '100%';
    uploadBtn.style.marginBottom = '10px';
    uploadBtn.style.borderColor = '#3ecf8e';

    logoutBtn.before(uploadBtn);

    uploadBtn.addEventListener('click', () => {
      fileInput.click();
    });

    fileInput.addEventListener('change', async (e) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const title = prompt(`🎬 Titre pour "${file.name}" :`, 'Nouvelle création FasoTok 🌍');
      if (!title) return;

      if (!window.supabaseClient) {
        alert(
          `📁 Vidéo "${file.name}" (${(file.size / (1024 * 1024)).toFixed(1)} Mo) prête !\n` +
          `Dès que tu auras connecté Supabase et créé un bucket public nommé "videos", l'envoi vers le monde entier se fera automatiquement.`
        );
        return;
      }

      const filePath = `public/${Date.now()}_${file.name.replace(/\s+/g, '_')}`;
      const { error: uploadError } = await window.supabaseClient.storage
        .from('videos')
        .upload(filePath, file);

      if (uploadError) {
        alert(`❌ Erreur d'envoi Storage : ${uploadError.message}`);
        return;
      }

      const { data: publicUrlData } = window.supabaseClient.storage
        .from('videos')
        .getPublicUrl(filePath);

      const { data: userData } = await window.supabaseClient.auth.getUser();
      await window.supabaseClient.from('videos').insert({
        user_id: userData?.user?.id || null,
        title: title.trim(),
        video_url: publicUrlData.publicUrl,
        country: localStorage.getItem('fasotok_country') || '🇧🇫 Burkina Faso'
      });

      alert('🌍 Vidéo envoyée et publiée dans le monde entier sur FasoTok !');
    });
  });
});
// --- 341. COMMENTAIRES MONDIAUX SUR LES VIDÉOS (SUPABASE) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_341_GLOBAL_COMMENTS', () => {
    window.postFasoTokComment = async (videoId) => {
      const commentText = prompt('💬 Écris ton commentaire public (visible dans le monde entier) :');
      if (!commentText || commentText.trim().length < 1) return;

      const cleanComment = commentText.trim().slice(0, 250);

      if (window.supabaseClient) {
        const { data: userData } = await window.supabaseClient.auth.getUser();
        const { error } = await window.supabaseClient.from('comments').insert({
          video_id: videoId,
          user_id: userData?.user?.id || null,
          content: cleanComment,
          country: localStorage.getItem('fasotok_country') || '🇧🇫 Burkina Faso'
        });

        if (!error) {
          alert('💬 Commentaire publié en direct sur FasoTok !');
          return;
        }
      }

      const localComments = JSON.parse(localStorage.getItem('fasotok_comments_queue') || '[]');
      localComments.push({ video_id: videoId, content: cleanComment, created_at: new Date().toISOString() });
      localStorage.setItem('fasotok_comments_queue', JSON.stringify(localComments));
      alert('💬 Commentaire enregistré (prêt pour la synchronisation Supabase) !');
    };
  });
});

