window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_343_SUPABASE_SQL_FINAL', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-343')) return;

    const sql3Btn = document.createElement('button');
    sql3Btn.id = 'btn-mod-343';
    sql3Btn.type = 'button';
    sql3Btn.textContent = '🗄️ Copier le SQL Final (Abonnements & Commentaires)';
    sql3Btn.className = 'secondary-btn';
    sql3Btn.style.width = '100%';
    sql3Btn.style.marginBottom = '10px';
    sql3Btn.style.borderColor = '#3ecf8e';

    logoutBtn.before(sql3Btn);

    sql3Btn.addEventListener('click', async () => {
      const sqlFinal = `
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS avatar_url TEXT;

CREATE TABLE IF NOT EXISTS follows (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  follower_id UUID REFERENCES auth.users(id),
  target_username TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(follower_id, target_username)
);

CREATE TABLE IF NOT EXISTS comments (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  video_id BIGINT REFERENCES videos(id) ON DELETE CASCADE,
  user_id UUID REFERENCES auth.users(id),
  content TEXT NOT NULL,
  country TEXT DEFAULT '🇧🇫 Burkina Faso',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE follows ENABLE ROW LEVEL SECURITY;
ALTER TABLE comments ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Lecture publique follows" ON follows FOR SELECT USING (true);
CREATE POLICY "Ajout propre follow" ON follows FOR INSERT WITH CHECK (auth.uid() = follower_id);
CREATE POLICY "Lecture publique comments" ON comments FOR SELECT USING (true);
CREATE POLICY "Ajout commentaire authentifie" ON comments FOR INSERT WITH CHECK (auth.uid() = user_id);
      `.trim();

      if (navigator.clipboard) {
        await navigator.clipboard.writeText(sqlFinal);
        alert('✅ Script SQL Final copié !\nTu as maintenant 100 % des tables nécessaires pour le lancement mondial de FasoTok sur Supabase.');
      } else {
        prompt('Copie ce script SQL final pour Supabase :', sqlFinal);
      }
    });
  });
});
// --- 344. LECTEUR DE COMMENTAIRES MONDIAUX (TABLE COMMENTS SUPABASE) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_344_READ_GLOBAL_COMMENTS', () => {
    window.readFasoTokComments = async (videoId) => {
      if (window.supabaseClient) {
        const { data, error } = await window.supabaseClient
          .from('comments')
          .select('content, country, created_at')
          .eq('video_id', videoId)
          .order('created_at', { ascending: false })
          .limit(10);

        if (!error && data && data.length > 0) {
          const formatted = data
            .map((c) => `• [${c.country || '🌍'}] ${c.content}`)
            .join('\n');
          alert(`💬 COMMENTAIRES MONDIAUX (${data.length}) :\n\n${formatted}`);
          return;
        }
      }

      const localQueue = JSON.parse(localStorage.getItem('fasotok_comments_queue') || '[]');
      const filtered = localQueue.filter((c) => String(c.video_id) === String(videoId));
      if (filtered.length > 0) {
        const list = filtered.map((c) => `• ${c.content}`).join('\n');
        alert(`💬 COMMENTAIRES EN ATTENTE DE SYNCHRONISATION :\n\n${list}`);
      } else {
        alert('💬 Aucun commentaire pour le moment. Sois le premier à commenter !');
      }
    };
  });
});

