// --- 348. TRIGGER SQL AUTOMATIQUE À L'INSCRIPTION D'UN UTILISATEUR MONDIAL ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_348_SUPABASE_AUTO_PROFILE_TRIGGER', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-348')) return;

    const triggerBtn = document.createElement('button');
    triggerBtn.id = 'btn-mod-348';
    triggerBtn.type = 'button';
    triggerBtn.textContent = '⚙️ Copier le Trigger SQL (Auto-Profil Inscription)';
    triggerBtn.className = 'secondary-btn';
    triggerBtn.style.width = '100%';
    triggerBtn.style.marginBottom = '10px';
    triggerBtn.style.borderColor = '#3ecf8e';

    logoutBtn.before(triggerBtn);

    triggerBtn.addEventListener('click', async () => {
      const triggerSql = `
CREATE OR REPLACE FUNCTION public.handle_new_fasotok_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, username, coins, xp)
  VALUES (
    NEW.id,
    COALESCE(split_part(NEW.email, '@', 1), 'createur_' || substr(NEW.id::text, 1, 6)),
    100,
    0
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS on_auth_user_created_fasotok ON auth.users;
CREATE TRIGGER on_auth_user_created_fasotok
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_fasotok_user();
      `.trim();

      if (navigator.clipboard) {
        await navigator.clipboard.writeText(triggerSql);
        alert('✅ Trigger SQL Auto-Profil copié !\nDès qu’un utilisateur mondial s’inscrira sur FasoTok, son profil avec 100 FasoCoins sera créé automatiquement dans Supabase.');
      } else {
        prompt('Copie ce Trigger SQL pour Supabase :', triggerSql);
      }
    });
  });
});

