// --- 351. BOÎTE À RYTHMES & AMBIANCE SONORE FASOTOK (WEB AUDIO API) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_351_AMBIENT_BEAT_MAKER', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-351')) return;

    let isPlaying = false;
    let beatInterval = null;
    let audioCtx = null;

    const beatBtn = document.createElement('button');
    beatBtn.id = 'btn-mod-351';
    beatBtn.type = 'button';
    beatBtn.textContent = '🥁 Lancer un Rythme FasoBeat (Studio Audio)';
    beatBtn.className = 'secondary-btn';
    beatBtn.style.width = '100%';
    beatBtn.style.marginBottom = '10px';
    beatBtn.style.borderColor = '#ff9ff3';

    logoutBtn.before(beatBtn);

    const playDrumHit = (freq, duration) => {
      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, audioCtx.currentTime + duration);
      gain.gain.setValueAtTime(0.25, audioCtx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + duration);
      osc.connect(gain);
      gain.connect(audioCtx.destination);
      osc.start();
      osc.stop(audioCtx.currentTime + duration);
    };

    beatBtn.addEventListener('click', () => {
      if (isPlaying) {
        clearInterval(beatInterval);
        isPlaying = false;
        beatBtn.textContent = '🥁 Lancer un Rythme FasoBeat (Studio Audio)';
        return;
      }

      isPlaying = true;
      beatBtn.textContent = '⏹️ Arrêter le Rythme FasoBeat';
      let step = 0;
      beatInterval = setInterval(() => {
        const pattern = [110, 165, 220, 165];
        playDrumHit(pattern[step % pattern.length], 0.18);
        step++;
      }, 280);
    });
  });
});

