// --- 360. CRÉATEUR DE MINIATURE / COVER VIDÉO PNG (CANVAS STUDIO) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_360_VIDEO_COVER_GENERATOR', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-360')) return;

    const coverBtn = document.createElement('button');
    coverBtn.id = 'btn-mod-360';
    coverBtn.type = 'button';
    coverBtn.textContent = '🎨 Créer une Miniature / Cover Vidéo (PNG)';
    coverBtn.className = 'secondary-btn';
    coverBtn.style.width = '100%';
    coverBtn.style.marginBottom = '10px';
    coverBtn.style.borderColor = '#ff9ff3';

    logoutBtn.before(coverBtn);

    coverBtn.addEventListener('click', () => {
      const coverTitle = prompt('🎨 Écris le grand titre à afficher sur ta miniature vidéo :', 'NOUVELLE VIDÉO FASOTOK 🔥');
      if (!coverTitle || coverTitle.trim().length < 2) return;

      const canvas = document.createElement('canvas');
      canvas.width = 720;
      canvas.height = 1280;
      const ctx = canvas.getContext('2d');

      // Fond dégradé officiel FasoTok
      const grad = ctx.createLinearGradient(0, 0, 720, 1280);
      grad.addColorStop(0, '#121212');
      grad.addColorStop(0.5, '#fe2c55');
      grad.addColorStop(1, '#25f4ee');
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, 720, 1280);

      // Cadre central sombre pour la lisibilité
      ctx.fillStyle = 'rgba(0, 0, 0, 0.72)';
      ctx.fillRect(50, 420, 620, 440);

      // Texte principal
      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 46px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(coverTitle.trim().slice(0, 26), 360, 620);

      // Signature FasoTok
      ctx.fillStyle = '#feca57';
      ctx.font = 'bold 28px sans-serif';
      ctx.fillText('🇧🇫 FASOTOK STUDIO MONDIAL 🌍', 360, 740);

      const link = document.createElement('a');
      link.download = `fasotok_cover_${Date.now()}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    });
  });
});

// --- 361. BARRE DE TEMPS DE TOURNAGE (15S / 30S / 60S) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_361_RECORDING_PROGRESS_BAR', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-361')) return;

    const barBtn = document.createElement('button');
    barBtn.id = 'btn-mod-361';
    barBtn.type = 'button';
    barBtn.textContent = '⏳ Barre de Temps Tournage (15s / 30s / 60s)';
    barBtn.className = 'secondary-btn';
    barBtn.style.width = '100%';
    barBtn.style.marginBottom = '10px';
    barBtn.style.borderColor = '#feca57';

    logoutBtn.before(barBtn);

    barBtn.addEventListener('click', () => {
      const existingBar = document.getElementById('rec-bar-container-mod-361');
      if (existingBar) {
        existingBar.remove();
        return;
      }

      const secChoice = parseInt(prompt('Choisis la durée cible en secondes (15, 30 ou 60) :', '15'), 10);
      const duration = [15, 30, 60].includes(secChoice) ? secChoice : 15;

      const container = document.createElement('div');
      container.id = 'rec-bar-container-mod-361';
      container.style.cssText = 'position: fixed; top: 0; left: 0; width: 100%; height: 8px; background: #222; z-index: 10005;';

      const fill = document.createElement('div');
      fill.style.cssText = 'width: 0%; height: 100%; background: linear-gradient(90deg, #25f4ee, #fe2c55); transition: width 0.2s linear;';
      container.appendChild(fill);
      document.body.appendChild(container);

      let elapsed = 0;
      const timer = setInterval(() => {
        elapsed += 0.2;
        const pct = Math.min((elapsed / duration) * 100, 100);
        fill.style.width = `${pct}%`;

        if (elapsed >= duration) {
          clearInterval(timer);
          setTimeout(() => container.remove(), 800);
          alert(`⏱️ Temps écoulé ! Ta prise de ${duration} secondes est terminée.`);
        }
      }, 200);
    });
  });
});

