// --- 366. MÉTRONOME VISUEL & SONORE POUR DANSE ET MUSIQUE (BPM) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_366_CREATOR_METRONOME', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-366')) return;

    let metroTimer = null;
    let audioCtx = null;

    const metroBtn = document.createElement('button');
    metroBtn.id = 'btn-mod-366';
    metroBtn.type = 'button';
    metroBtn.textContent = '🎼 Métronome Danse & Tempo (BPM)';
    metroBtn.className = 'secondary-btn';
    metroBtn.style.width = '100%';
    metroBtn.style.marginBottom = '10px';
    metroBtn.style.borderColor = '#ff9ff3';

    logoutBtn.before(metroBtn);

    metroBtn.addEventListener('click', () => {
      if (metroTimer) {
        clearInterval(metroTimer);
        metroTimer = null;
        metroBtn.textContent = '🎼 Métronome Danse & Tempo (BPM)';
        return;
      }

      const bpmInput = parseInt(prompt('🎼 Choisis le tempo en BPM (ex: 100 pour Afrobeat, 125 pour Coupé-Décalé) :', '110'), 10);
      const bpm = !isNaN(bpmInput) && bpmInput >= 60 && bpmInput <= 180 ? bpmInput : 110;
      const intervalMs = Math.round(60000 / bpm);

      metroBtn.textContent = `⏹️ Arrêter le Métronome (${bpm} BPM)`;

      metroTimer = setInterval(() => {
        if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.frequency.setValueAtTime(880, audioCtx.currentTime);
        gain.gain.setValueAtTime(0.15, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.06);
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.start();
        osc.stop(audioCtx.currentTime + 0.06);

        metroBtn.style.borderColor = metroBtn.style.borderColor === 'rgb(254, 44, 85)' ? '#25f4ee' : '#fe2c55';
      }, intervalMs);
    });
  });
});

