// --- 375. SOUNDBOARD CRÉATEUR (EFFETS SONORES EN DIRECT) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_375_CREATOR_SOUNDBOARD', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-375')) return;

    let audioCtx = null;

    const soundBtn = document.createElement('button');
    soundBtn.id = 'btn-mod-375';
    soundBtn.type = 'button';
    soundBtn.textContent = '🔊 Boîte à Bruitages Studio (Effets Sonores)';
    soundBtn.className = 'secondary-btn';
    soundBtn.style.width = '100%';
    soundBtn.style.marginBottom = '10px';
    soundBtn.style.borderColor = '#ff6b81';

    logoutBtn.before(soundBtn);

    const playTone = (notes, type = 'sine', stepTime = 0.12) => {
      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      notes.forEach((freq, idx) => {
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = type;
        osc.frequency.setValueAtTime(freq, audioCtx.currentTime + idx * stepTime);
        gain.gain.setValueAtTime(0.2, audioCtx.currentTime + idx * stepTime);
        gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + (idx + 1) * stepTime);
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.start(audioCtx.currentTime + idx * stepTime);
        osc.stop(audioCtx.currentTime + (idx + 1) * stepTime);
      });
    };

    soundBtn.addEventListener('click', () => {
      const choice = prompt(
        '🔊 Choisis un effet sonore à jouer en direct :\n\n' +
        '1. 🏆 Fanfare Victoire / But des Étalons\n' +
        '2. 😱 Suspense / Choc\n' +
        '3. 😂 Boing Comédie / Gag',
        '1'
      );

      if (choice === '1') {
        playTone([523, 659, 784, 1046], 'triangle', 0.11);
      } else if (choice === '2') {
        playTone([300, 260, 220, 180], 'sawtooth', 0.16);
      } else if (choice === '3') {
        playTone([250, 450, 300, 600], 'sine', 0.09);
      }
    });
  });
});

