// --- 377. TESTEUR DE VITESSE & STABILITÉ RÉSEAU MOBILE ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_377_NETWORK_SPEED_CHECKER', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-377')) return;

    const netBtn = document.createElement('button');
    netBtn.id = 'btn-mod-377';
    netBtn.type = 'button';
    netBtn.textContent = '📡 Tester la Qualité de ma Connexion Mobile';
    netBtn.className = 'secondary-btn';
    netBtn.style.width = '100%';
    netBtn.style.marginBottom = '10px';
    netBtn.style.borderColor = '#2ed573';

    logoutBtn.before(netBtn);

    netBtn.addEventListener('click', async () => {
      if (!navigator.onLine) {
        alert('🔴 Tu es actuellement hors ligne. Active tes données mobiles ou le Wi-Fi.');
        return;
      }

      const start = performance.now();
      try {
        await fetch(window.location.href, { method: 'HEAD', cache: 'no-store' });
        const latency = Math.round(performance.now() - start);
        const quality = latency < 250 ? 'Excellente 🟢 (Idéal pour publier)' : latency < 600 ? 'Bonne 🟡' : 'Lente 🟠 (Active le mode Économie de Data)';

        alert(
          `📡 DIAGNOSTIC CONNEXION FASOTOK\n\n` +
          `⏱️ Temps de réponse (Ping) : ${latency} ms\n` +
          `📶 Qualité estimée : ${quality}`
        );
      } catch (e) {
        alert('🟠 Réseau instable détecté. Vérifie ton signal mobile.');
      }
    });
  });
});
