// --- 382. CALCULATEUR DE DURÉE DE SCRIPT (TEMPS DE PAROLE) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_382_SCRIPT_DURATION_CALC', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-382')) return;

    const calcScriptBtn = document.createElement('button');
    calcScriptBtn.id = 'btn-mod-382';
    calcScriptBtn.type = 'button';
    calcScriptBtn.textContent = '🗣️ Calculer la Durée d’un Texte Parlé';
    calcScriptBtn.className = 'secondary-btn';
    calcScriptBtn.style.width = '100%';
    calcScriptBtn.style.marginBottom = '10px';
    calcScriptBtn.style.borderColor = '#25f4ee';

    logoutBtn.before(calcScriptBtn);

    calcScriptBtn.addEventListener('click', () => {
      const saved = localStorage.getItem('fasotok_creator_notes') || '';
      const text = prompt('🗣️ Colle ton texte pour connaître sa durée exacte en vidéo :', saved);
      if (!text || text.trim().length === 0) return;

      const words = text.trim().split(/\s+/).length;
      // Rythme moyen naturel : environ 2,3 mots par seconde
      const seconds = Math.max(1, Math.round(words / 2.3));

      alert(
        `⏱️ ANALYSE DE TON SCRIPT FASOTOK\n\n` +
        `📝 Nombre de mots : ${words} mots\n` +
        `🎬 Durée estimée à l'oral : ~${seconds} seconde${seconds > 1 ? 's' : ''}\n` +
        `💡 Format recommandé : ${seconds <= 15 ? 'Court 15s (Idéal viralité)' : seconds <= 30 ? 'Standard 30s' : 'Storytelling 60s'}`
      );
    });
  });
});

