// --- 385. SPRINT DE CRÉATION RAPIDE (MINUTEUR 15 MINUTES) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_385_CREATIVE_SPRINT_TIMER', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-385')) return;

    let sprintInterval = null;

    const sprintBtn = document.createElement('button');
    sprintBtn.id = 'btn-mod-385';
    sprintBtn.type = 'button';
    sprintBtn.textContent = '⚡ Lancer un Sprint Création (15 min)';
    sprintBtn.className = 'secondary-btn';
    sprintBtn.style.width = '100%';
    sprintBtn.style.marginBottom = '10px';
    sprintBtn.style.borderColor = '#fe2c55';

    logoutBtn.before(sprintBtn);

    sprintBtn.addEventListener('click', () => {
      if (sprintInterval) {
        clearInterval(sprintInterval);
        sprintInterval = null;
        sprintBtn.textContent = '⚡ Lancer un Sprint Création (15 min)';
        return;
      }

      let remainingSeconds = 15 * 60;
      sprintInterval = setInterval(() => {
        remainingSeconds--;
        const mins = Math.floor(remainingSeconds / 60);
        const secs = String(remainingSeconds % 60).padStart(2, '0');
        sprintBtn.textContent = `⏳ Sprint en cours : ${mins}:${secs} (Clic pour arrêter)`;

        if (remainingSeconds <= 0) {
          clearInterval(sprintInterval);
          sprintInterval = null;
          sprintBtn.textContent = '⚡ Lancer un Sprint Création (15 min)';
          alert('🎉 Sprint de 15 minutes terminé ! Ta création est prête.');
        }
      }, 1000);
    });
  });
});

