// --- 397. SURVEILLANCE BATTERIE MOBILE AVANT TOURNAGE ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_397_MOBILE_BATTERY_MONITOR', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-397')) return;

    const batBtn = document.createElement('button');
    batBtn.id = 'btn-mod-397';
    batBtn.type = 'button';
    batBtn.textContent = '🔋 Niveau de Batterie & Autonomie Studio';
    batBtn.className = 'secondary-btn';
    batBtn.style.width = '100%';
    batBtn.style.marginBottom = '10px';
    batBtn.style.borderColor = '#2ed573';

    logoutBtn.before(batBtn);

    batBtn.addEventListener('click', async () => {
      if ('getBattery' in navigator) {
        try {
          const battery = await navigator.getBattery();
          const level = Math.round(battery.level * 100);
          const charging = battery.charging ? 'En charge ⚡' : 'Sur batterie 📱';
          const advice = level < 20 && !battery.charging
            ? '⚠️ Batterie faible ! Pense à sauvegarder ton code sur GitHub avant de filmer.'
            : '🟢 Autonomie suffisante pour tourner et coder sereinement.';

          alert(`🔋 ÉTAT DE TON TÉLÉPHONE\n\nNiveau : ${level} % (${charging})\n${advice}`);
          return;
        } catch (e) {}
      }

      alert('🔋 Mode Mobile Actif : Pense à garder au moins 20 % de batterie avant un long tournage vidéo !');
    });
  });
});

