// --- 406. CALIBRAGE AUDIO & TEST HAUT-PARLEUR MOBILE ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_406_AUDIO_SPEAKER_CALIBRATOR', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-406')) return;

    const audioTestBtn = document.createElement('button');
    audioTestBtn.id = 'btn-mod-406';
    audioTestBtn.type = 'button';
    audioTestBtn.textContent = '🎧 Tester le Volume Audio du Téléphone';
    audioTestBtn.className = 'secondary-btn';
    audioTestBtn.style.width = '100%';
    audioTestBtn.style.marginBottom = '10px';
    audioTestBtn.style.borderColor = '#ff9ff3';

    logoutBtn.before(audioTestBtn);

    audioTestBtn.addEventListener('click', () => {
      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      if (!AudioContextClass) {
        alert('❌ Test audio non supporté sur ce navigateur.');
        return;
      }

      const ctx = new AudioContextClass();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(440, ctx.currentTime); // Note La 440Hz standard
      gain.gain.setValueAtTime(0.18, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5);

      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.5);

      alert('🎧 Signal de calibrage (440 Hz) émis ! Si tu as entendu le bip clair, ton volume audio est bien réglé.');
    });
  });
});
