// --- 415. AMBIANCE SONORE DE CONCENTRATION (BRUIT DOUX STUDIO) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_415_FOCUS_AMBIENT_SOUND', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-415')) return;

    let focusCtx = null;
    let focusSource = null;

    const focusSoundBtn = document.createElement('button');
    focusSoundBtn.id = 'btn-mod-415';
    focusSoundBtn.type = 'button';
    focusSoundBtn.textContent = '🌊 Son Apaisant Concentration (Écriture)';
    focusSoundBtn.className = 'secondary-btn';
    focusSoundBtn.style.width = '100%';
    focusSoundBtn.style.marginBottom = '10px';
    focusSoundBtn.style.borderColor = '#48dbfb';

    logoutBtn.before(focusSoundBtn);

    focusSoundBtn.addEventListener('click', () => {
      if (focusSource) {
        focusSource.stop();
        focusSource = null;
        focusSoundBtn.textContent = '🌊 Son Apaisant Concentration (Écriture)';
        return;
      }

      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      if (!AudioContextClass) return;

      focusCtx = new AudioContextClass();
      const bufferSize = focusCtx.sampleRate * 2;
      const buffer = focusCtx.createBuffer(1, bufferSize, focusCtx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        data[i] = (Math.random() * 2 - 1) * 0.04;
      }

      const filter = focusCtx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 350;

      focusSource = focusCtx.createBufferSource();
      focusSource.buffer = buffer;
      focusSource.loop = true;
      focusSource.connect(filter);
      filter.connect(focusCtx.destination);
      focusSource.start();

      focusSoundBtn.textContent = '⏹️ Couper le Son Apaisant';
    });
  });
});
