// --- 422. DOUBLE-TAP CŒUR GÉANT ANIMÉ (GESTE ICONIQUE TIKTOK) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_422_TIKTOK_DOUBLE_TAP_HEART', () => {
    let lastTap = 0;

    document.addEventListener('click', (e) => {
      const targetVideo = e.target.closest('video');
      if (!targetVideo) return;

      const now = Date.now();
      if (now - lastTap < 300) {
        const heart = document.createElement('div');
        heart.textContent = '❤️';
        heart.style.cssText = `
          position: fixed; left: ${e.clientX - 40}px; top: ${e.clientY - 40}px;
          font-size: 80px; pointer-events: none; z-index: 10010;
          transform: scale(0.5); opacity: 1;
          transition: transform 0.5s ease-out, opacity 0.6s ease-out;
        `;
        document.body.appendChild(heart);

        requestAnimationFrame(() => {
          heart.style.transform = 'scale(1.4) translateY(-30px)';
          heart.style.opacity = '0';
        });

        setTimeout(() => heart.remove(), 650);
      }
      lastTap = now;
    });
  });
});

