// --- 425. BARRE D'ACTIONS LATÉRALE DROITE STYLE TIKTOK ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_425_TIKTOK_RIGHT_ACTION_BAR', () => {
    if (document.getElementById('right-bar-mod-425')) return;

    const bar = document.createElement('div');
    bar.id = 'right-bar-mod-425';
    bar.style.cssText = `
      position: fixed; right: 12px; bottom: 135px; z-index: 9991;
      display: flex; flex-direction: column; gap: 18px; align-items: center;
      color: #fff; font-size: 12px; font-weight: bold;
      text-shadow: 0 2px 5px rgba(0,0,0,0.8);
    `;

    let likesCount = 128;
    let liked = false;
    let bookmarked = false;

    const createActionItem = (icon, labelText, onClick) => {
      const wrap = document.createElement('div');
      wrap.style.cssText = 'display: flex; flex-direction: column; align-items: center; cursor: pointer;';
      const ic = document.createElement('div');
      ic.style.fontSize = '28px';
      ic.textContent = icon;
      const lbl = document.createElement('span');
      lbl.textContent = labelText;
      wrap.appendChild(ic);
      wrap.appendChild(lbl);
      wrap.addEventListener('click', () => onClick(ic, lbl));
      return wrap;
    };

    const likeItem = createActionItem('🤍', String(likesCount), (ic, lbl) => {
      liked = !liked;
      likesCount += liked ? 1 : -1;
      ic.textContent = liked ? '❤️' : '🤍';
      lbl.textContent = String(likesCount);
    });

    const commentItem = createActionItem('💬', '24', () => {
      if (window.postFasoTokComment) {
        window.postFasoTokComment('featured');
      } else {
        prompt('💬 Écris un commentaire sur cette vidéo :');
      }
    });

    const favItem = createActionItem('🔖', 'Favori', (ic) => {
      bookmarked = !bookmarked;
      ic.textContent = bookmarked ? '⭐' : '🔖';
    });

    const shareItem = createActionItem('↪️', 'Partager', async () => {
      if (navigator.share) {
        try {
          await navigator.share({ title: 'FasoTok', url: window.location.href });
        } catch (e) {}
      } else if (navigator.clipboard) {
        await navigator.clipboard.writeText(window.location.href);
        alert('📋 Lien de la vidéo copié !');
      }
    });

    bar.appendChild(likeItem);
    bar.appendChild(commentItem);
    bar.appendChild(favItem);
    bar.appendChild(shareItem);
    document.body.appendChild(bar);
  });
});

