// --- 432. VITESSE X2 PAR APPUI LONG & CONTRÔLE DU SON (GESTES TIKTOK) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_432_TIKTOK_LONG_PRESS_2X_SPEED', () => {
    let speedBadge = null;

    const showSpeedIndicator = (active) => {
      if (active && !speedBadge) {
        speedBadge = document.createElement('div');
        speedBadge.id = 'speed-2x-badge-mod-432';
        speedBadge.style.cssText = `
          position: fixed; top: 55px; left: 50%; transform: translateX(-50%);
          background: rgba(0, 0, 0, 0.75); color: #ffffff; padding: 5px 14px;
          border-radius: 16px; font-size: 12px; font-weight: bold; z-index: 10009;
        `;
        speedBadge.textContent = '⏩ Vitesse x2';
        document.body.appendChild(speedBadge);
      } else if (!active && speedBadge) {
        speedBadge.remove();
        speedBadge = null;
      }
    };

    document.addEventListener('touchstart', (e) => {
      const vid = e.target.closest('video');
      if (vid) {
        vid.playbackRate = 2.0;
        showSpeedIndicator(true);
      }
    }, { passive: true });

    document.addEventListener('touchend', () => {
      document.querySelectorAll('video').forEach((v) => {
        v.playbackRate = 1.0;
      });
      showSpeedIndicator(false);
    });
  });
});
