// --- 434. LECTURE AUTOMATIQUE INTELLIGENTE (AUTO-PLAY VIDÉO VISIBLE) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_434_TIKTOK_SMART_AUTOPLAY', () => {
    if (!('IntersectionObserver' in window)) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          const vid = entry.target;
          if (entry.isIntersecting && entry.intersectionRatio >= 0.65) {
            vid.play().catch(() => {});
          } else {
            vid.pause();
          }
        });
      },
      { threshold: [0.65] }
    );

    const observeAllVideos = () => {
      document.querySelectorAll('video').forEach((v) => {
        if (!v.dataset.observed434) {
          v.dataset.observed434 = 'true';
          v.loop = true;
          v.playsInline = true;
          observer.observe(v);
        }
      });
    };

    observeAllVideos();
    setInterval(observeAllVideos, 2500);
  });
});

