window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_439_TIKTOK_COMMENT_DRAWER', () => {
    window.openFasoTokCommentSheet = () => {
      if (document.getElementById('comment-sheet-mod-439')) return;

      const sheet = document.createElement('div');
      sheet.id = 'comment-sheet-mod-439';
      sheet.style.cssText = `
        position: fixed; bottom: 0; left: 0; width: 100%; height: 62%;
        background: #161823; color: #ffffff; z-index: 10015;
        border-top-left-radius: 18px; border-top-right-radius: 18px;
        box-shadow: 0 -6px 25px rgba(0,0,0,0.85); display: flex; flex-direction: column;
        font-family: sans-serif;
      `;

      const header = document.createElement('div');
      header.style.cssText = 'padding: 12px 16px; border-bottom: 1px solid #2a2c38; display: flex; justify-content: space-between; align-items: center; font-weight: bold; font-size: 14px;';
      header.innerHTML = '<span>💬 Commentaires FasoTok</span>';

      const closeBtn = document.createElement('span');
      closeBtn.textContent = '✖';
      closeBtn.style.cssText = 'cursor: pointer; font-size: 16px; padding: 4px 8px;';
      closeBtn.onclick = () => sheet.remove();
      header.appendChild(closeBtn);

      const listArea = document.createElement('div');
      listArea.style.cssText = 'flex: 1; overflow-y: auto; padding: 14px; font-size: 13px; display: flex; flex-direction: column; gap: 12px;';

      const savedComments = JSON.parse(localStorage.getItem('fasotok_sheet_comments') || '[{"user":"@OuagaVibes 🇧🇫","text":"Incroyable cette application FasoTok ! 🔥"},{"user":"@BoboFlow","text":"Force au créateur, c’est du lourd 👏"}]');

      const renderComments = () => {
        listArea.innerHTML = savedComments
          .map((c) => `<div><strong style="color:#25f4ee;">${c.user}</strong><br><span style="color:#eee;">${c.text}</span></div>`)
          .join('');
      };
      renderComments();

      const inputBar = document.createElement('div');
      inputBar.style.cssText = 'padding: 10px 12px; border-top: 1px solid #2a2c38; display: flex; gap: 8px; background: #12131a;';

      const input = document.createElement('input');
      input.type = 'text';
      input.placeholder = 'Ajouter un commentaire...';
      input.style.cssText = 'flex: 1; padding: 9px 14px; border-radius: 20px; border: none; background: #262836; color: #fff; font-size: 13px;';

      const sendBtn = document.createElement('button');
      sendBtn.type = 'button';
      sendBtn.textContent = '➤';
      sendBtn.style.cssText = 'padding: 0 16px; border-radius: 20px; border: none; background: #fe2c55; color: #fff; font-weight: bold; cursor: pointer;';

      sendBtn.onclick = () => {
        if (!input.value.trim()) return;
        savedComments.unshift({ user: '@Moi (Créateur) 🇧🇫', text: input.value.trim() });
        localStorage.setItem('fasotok_sheet_comments', JSON.stringify(savedComments));
        input.value = '';
        renderComments();
      };

      inputBar.appendChild(input);
      inputBar.appendChild(sendBtn);
      sheet.appendChild(header);
      sheet.appendChild(listArea);
      sheet.appendChild(inputBar);
      document.body.appendChild(sheet);
    };

    // Relie automatiquement le bouton commentaire de la barre droite à ce tiroir moderne
    const rightBar = document.getElementById('right-bar-mod-425');
    if (rightBar && rightBar.children[2]) {
      rightBar.children[2].onclick = window.openFasoTokCommentSheet;
    }
  });
});

