// --- 457. NAVIGATION TACTILE PAR GLISSEMENT VERTICAL (SWIPE UP / DOWN TIKTOK) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_457_TIKTOK_TOUCH_SWIPE_NAV', () => {
    let touchStartY = 0;

    document.addEventListener('touchstart', (e) => {
      if (e.touches && e.touches.length === 1) {
        touchStartY = e.touches.clientY;
      }
    }, { passive: true });

    document.addEventListener('touchend', (e) => {
      if (!e.changedTouches || e.changedTouches.length === 0) return;
      const deltaY = touchStartY - e.changedTouches.clientY;

      // Glissement franc vers le haut (> 85px) : descend vers la vidéo suivante
      if (deltaY > 85) {
        window.scrollBy({ top: window.innerHeight * 0.85, behavior: 'smooth' });
      }
      // Glissement franc vers le bas (< -85px) : remonte vers la vidéo précédente
      else if (deltaY < -85 && window.scrollY > 50) {
        window.scrollBy({ top: -window.innerHeight * 0.85, behavior: 'smooth' });
      }
    }, { passive: true });
  });
});

// --- 458. RETOUR HAPTIQUE / MICRO-VIBRATION MOBILE (SENSATION APP NATIVE) ---
