// --- 461. MODE MINI-LECTEUR FLOTTANT (PICTURE-IN-PICTURE STYLE TIKTOK) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_461_TIKTOK_PICTURE_IN_PICTURE', () => {
    if (document.getElementById('pip-btn-mod-461')) return;

    const pipBtn = document.createElement('button');
    pipBtn.id = 'pip-btn-mod-461';
    pipBtn.type = 'button';
    pipBtn.textContent = '📺';
    pipBtn.title = 'Mini-lecteur flottant (Picture-in-Picture)';
    pipBtn.style.cssText = `
      position: fixed; top: 56px; right: 14px; z-index: 9995;
      width: 36px; height: 36px; border-radius: 50%; border: none;
      background: rgba(0, 0, 0, 0.55); color: #ffffff; font-size: 15px;
      display: flex; align-items: center; justify-content: center; cursor: pointer;
    `;

    pipBtn.addEventListener('click', async () => {
      const activeVid = document.querySelector('video');
      if (!activeVid) {
        alert('🎬 Lance d’abord une vidéo pour activer le mini-lecteur flottant.');
        return;
      }

      if (document.pictureInPictureElement) {
        await document.exitPictureInPicture();
      } else if (document.pictureInPictureEnabled) {
        try {
          await activeVid.requestPictureInPicture();
        } catch (err) {
          alert('📺 Le mini-lecteur flottant nécessite une vidéo active à l’écran.');
        }
      } else {
        alert('📱 Ton navigateur mobile ne prend pas en charge le mode Picture-in-Picture.');
      }
    });

    document.body.appendChild(pipBtn);
  });
});
// --- 462. COMPTEUR TEMPOREL VIDÉO EN DIRECT (00:00 / 00:15) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_462_TIKTOK_TIME_READOUT', () => {
    if (document.getElementById('time-readout-mod-462')) return;

    const timePill = document.createElement('div');
    timePill.id = 'time-readout-mod-462';
    timePill.style.cssText = `
      position: fixed; bottom: 66px; right: 66px; z-index: 9991;
      background: rgba(0, 0, 0, 0.5); color: #ffffff;
      padding: 2px 8px; border-radius: 10px; font-size: 10px;
      font-family: monospace; pointer-events: none;
    `;
    timePill.textContent = '00:00 / 00:00';
    document.body.appendChild(timePill);

    const formatSec = (sec) => {
      if (!sec || isNaN(sec)) return '00:00';
      const m = String(Math.floor(sec / 60)).padStart(2, '0');
      const s = String(Math.floor(sec % 60)).padStart(2, '0');
      return `${m}:${s}`;
    };

    setInterval(() => {
      const vid = document.querySelector('video');
      if (vid && vid.duration) {
        timePill.textContent = `${formatSec(vid.currentTime)} / ${formatSec(vid.duration)}`;
      }
    }, 500);
  });
});

