// --- 466. CONTRÔLE RAPIDE LECTURE / PAUSE PAR LA TOUCHE ESPACE ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_466.KEYBOARD_SPACE_PLAY_PAUSE', () => {
    document.addEventListener('keydown', (e) => {
      if (e.code === 'Space' && e.target.tagName !== 'INPUT' && e.target.tagName !== 'TEXTAREA') {
        e.preventDefault();
        const activeVid = document.querySelector('video');
        if (activeVid) {
          if (activeVid.paused) {
            activeVid.play();
          } else {
            activeVid.pause();
          }
        }
      }
    });
  });
});

