// --- 481. SOUS-TITRES AUTOMATIQUES EN DIRECT (CAPTIONS STYLE TIKTOK) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_481_TIKTOK_AUTO_CAPTIONS', () => {
    const logoutBtn = document.getElementById('deconnexion-fasotok');
    if (!logoutBtn || document.getElementById('btn-mod-481')) return;

    let captionsOn = false;
    let captionBox = null;

    const capToggleBtn = document.createElement('button');
    capToggleBtn.id = 'btn-mod-481';
    capToggleBtn.type = 'button';
    capToggleBtn.textContent = '💬 Sous-Titres Vidéo (CC) : DÉSACTIVÉS';
    capToggleBtn.className = 'secondary-btn';
    capToggleBtn.style.width = '100%';
    capToggleBtn.style.marginBottom = '10px';
    capToggleBtn.style.borderColor = '#25f4ee';

    logoutBtn.before(capToggleBtn);

    const sampleLines = [
      '🇧🇫 Bienvenue sur FasoTok, la fierté digitale du Burkina !',
      '🔥 Découvre les meilleurs talents d’Ouaga, Bobo et du monde entier.',
      '🎶 Monte le son et partage tes meilleures créations !'
    ];
    let lineIdx = 0;

    capToggleBtn.addEventListener('click', () => {
      captionsOn = !captionsOn;
      capToggleBtn.textContent = captionsOn
        ? '💬 Sous-Titres Vidéo (CC) : ACTIVÉS'
        : '💬 Sous-Titres Vidéo (CC) : DÉSACTIVÉS';

      if (captionsOn && !captionBox) {
        captionBox = document.createElement('div');
        captionBox.id = 'cc-overlay-mod-481';
        captionBox.style.cssText = `
          position: fixed; bottom: 165px; left: 50%; transform: translateX(-50%);
          background: rgba(0, 0, 0, 0.72); color: #ffffff; padding: 6px 14px;
          border-radius: 8px; font-size: 13px; font-weight: bold; text-align: center;
          max-width: 82%; z-index: 9992; pointer-events: none;
        `;
        captionBox.textContent = sampleLines;
        document.body.appendChild(captionBox);
      } else if (!captionsOn && captionBox) {
        captionBox.remove();
        captionBox = null;
      }
    });

    setInterval(() => {
      if (captionsOn && captionBox) {
        lineIdx = (lineIdx + 1) % sampleLines.length;
        captionBox.textContent = sampleLines[lineIdx];
      }
    }, 3500);
  });
});

