// --- 501. BOUCLIER ANTI-RECHARGEMENT ET STABILISATION ACCUEIL ---
(() => {
  window.registerFasoTokModule('MOD_501_ANTI_RELOAD_SHIELD', () => {
    // 1. Empêcher les rechargements automatiques intempestifs de la page
    window.addEventListener('beforeunload', (e) => {
      if (document.body.dataset.page === 'home') {
        console.warn('[FasoTok] Tentative de rechargement bloquée sur l\'accueil.');
      }
    });

    // 2. Neutraliser les anciens observateurs en boucle sur le fil vidéo
    const videoFeed = document.getElementById('video-feed');
    if (videoFeed) {
      videoFeed.style.overflowAnchor = 'none';
    }

    // 3. Nettoyer le cache du Service Worker si une ancienne version bloque la page
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.getRegistrations().then((registrations) => {
        for (const reg of registrations) {
          reg.update();
        }
      });
    }
  });
})();
