// --- 503. ARRÊT DES RECHARGEMENTS INFINIS & NETTOYAGE ÉCRAN ACCUEIL ---
(() => {
  // 1. Désactiver le Service Worker en mode test local (localhost) pour stopper la boucle de rechargement
  if (location.hostname === 'localhost' || location.hostname === '127.0.0.1') {
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.getRegistrations().then((regs) => {
        regs.forEach((reg) => reg.unregister());
      });
    }
    if ('caches' in window) {
      caches.keys().then((names) => {
        names.forEach((name) => caches.delete(name));
      });
    }
  }

  // 2. Nettoyer les boutons et animations bloqués qui se superposent sur l'accueil
  const nettoyerSuperpositions = () => {
    const idsAEnlever = [
      'loader-mod-446',           // Les 2 points bleu/rose bloqués au milieu
      'top-tabs-mod-424',         // Le double texte "Suivis | Pour toi" en haut
      'search-icon-mod-436',      // La deuxième loupe en haut à droite
      'speed-pill-mod-449',       // Le bouton "1x" sur la Story
      'mute-btn-mod-435',         // Le bouton son en double en haut à gauche
      'pip-btn-mod-461',          // Le bouton TV en haut à droite
      'clear-ui-btn-mod-464',     // Le bouton étoiles en haut à droite
      'effects-btn-mod-471',      // Le bouton effets en haut à gauche
      'net-status-mod-479',       // Le badge 4G en haut à gauche
      'live-views-mod-465',       // Le compteur de vues flottant
      'right-bar-mod-425',        // La barre latérale flottante vide
      'bottom-left-info-mod-427', // La fausse légende flottante
      'vinyl-disc-mod-423',       // Le disque flottant vide
      'bottom-navbar-mod-428'     // La deuxième barre de navigation en bas
    ];

    idsAEnlever.forEach((id) => {
      const el = document.getElementById(id);
      if (el) el.remove();
    });
  };

  window.addEventListener('DOMContentLoaded', nettoyerSuperpositions);
  window.addEventListener('load', nettoyerSuperpositions);
  setTimeout(nettoyerSuperpositions, 1200);
})();
