// --- 506. BOUTON SUIVRE (+ SUIVRE / ABONNÉ) DIRECTEMENT SUR LES VIDÉOS ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_506_VIDEO_FOLLOW_BUTTON', () => {
    const videoFeed = document.getElementById('video-feed');
    if (!videoFeed) return;

    const ajouterBoutonSuivre = (carte) => {
      if (carte.dataset.followReady) return;
      carte.dataset.followReady = 'true';

      const titreAuteur = carte.querySelector('.post-caption strong, h3');
      if (!titreAuteur) return;

      const pseudo = titreAuteur.textContent.trim();
      const abonnements = JSON.parse(localStorage.getItem('fasotok_abonnements') || '[]');
      let estAbonne = abonnements.includes(pseudo);

      const btn = document.createElement('button');
      btn.type = 'button';
      btn.textContent = estAbonne ? 'Abonné ✓' : '+ Suivre';
      btn.style.cssText = `
        margin-left: 8px; padding: 3px 9px; border-radius: 6px; border: none;
        font-size: 11px; font-weight: bold; cursor: pointer;
        background: ${estAbonne ? 'rgba(255,255,255,0.2)' : '#fe2c55'}; color: #fff;
      `;

      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        let liste = JSON.parse(localStorage.getItem('fasotok_abonnements') || '[]');
        if (liste.includes(pseudo)) {
          liste = liste.filter((p) => p !== pseudo);
          estAbonne = false;
        } else {
          liste.push(pseudo);
          estAbonne = true;
        }
        localStorage.setItem('fasotok_abonnements', JSON.stringify(liste));
        btn.textContent = estAbonne ? 'Abonné ✓' : '+ Suivre';
        btn.style.background = estAbonne ? 'rgba(255,255,255,0.2)' : '#fe2c55';
      });

      titreAuteur.appendChild(btn);
    };

    videoFeed.querySelectorAll('.video-item').forEach(ajouterBoutonSuivre);
    new MutationObserver(() => {
      videoFeed.querySelectorAll('.video-item').forEach(ajouterBoutonSuivre);
    }).observe(videoFeed, { childList: true });
  });
});
// --- 507. DÉBLOCAGE TOTAL DES TOUCHES ET DE LA NAVIGATION ---
(() => {
  const debloquerTouches = () => {
    // 1. Supprimer ou rendre traversables tous les calques invisibles qui bloquent les clics
    const calquesBloquants = [
      'fasotok-night-filter',
      'ring-light-overlay-mod-354',
      'grid-overlay-mod-358',
      'neon-frame-mod-364',
      'warm-overlay-mod-383',
      'safe-zone-overlay-mod-388',
      'split-line-mod-483',
      'fasotok-studio-modal',
      'tiktok-search-panel',
      'profile-media-viewer'
    ];

    calquesBloquants.forEach((id) => {
      const el = document.getElementById(id);
      if (el) {
        el.style.pointerEvents = 'none';
        if (el.style.display === 'flex' || el.style.display === 'block') {
          el.style.display = 'none';
        }
      }
    });

    // 2. S'assurer que la barre du bas et les boutons principaux passent au premier plan
    const styleDeblocage = document.createElement('style');
    styleDeblocage.id = 'style-deblocage-507';
    styleDeblocage.textContent = `
      .bottom-nav, .top-nav, #empty-create-btn, button {
        pointer-events: auto !important;
      }
      .bottom-nav {
        z-index: 20000 !important;
      }
      .top-nav {
        z-index: 19000 !important;
      }
    `;
    if (!document.getElementById('style-deblocage-507')) {
      document.head.appendChild(styleDeblocage);
    }

    // 3. Rebrancher les boutons de la barre de navigation du bas (Accueil, Découvrir, +, Boîte, Profil)
    document.querySelectorAll('.bottom-nav .nav-item[data-page]').forEach((btn) => {
      btn.onclick = () => {
        const page = btn.getAttribute('data-page');
        document.querySelectorAll('.page-section').forEach((sec) => {
          sec.hidden = sec.id !== page + '-page';
        });
        document.querySelectorAll('.bottom-nav .nav-item').forEach((b) => {
          b.classList.toggle('active-nav', b === btn);
        });
      };
    });

    // 4. Rebrancher le bouton "+" central et le bouton "Créer ma première publication"
    const ouvrirCreation = () => {
      const menu = document.getElementById('create-menu');
      if (menu) menu.hidden = false;
    };
    const plusBtn = document.getElementById('publish-btn');
    const emptyBtn = document.getElementById('empty-create-btn');
    if (plusBtn) plusBtn.onclick = ouvrirCreation;
    if (emptyBtn) emptyBtn.onclick = ouvrirCreation;
  };

  window.addEventListener('DOMContentLoaded', debloquerTouches);
  window.addEventListener('load', debloquerTouches);
  setTimeout(debloquerTouches, 1000);
})();
// --- FASOTOK PROPRE & STABLE (GESTION DES INTERACTIONS TIKTOK) ---
document.addEventListener('DOMContentLoaded', () => {
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];

  // 1. Navigation fluide entre les 5 pages (Accueil, Découvrir, Boîte, Profil)
  $$('.bottom-nav .nav-item[data-page]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const page = btn.dataset.page;
      $$('.page-section').forEach((sec) => {
        sec.hidden = sec.id !== page + '-page';
      });
      $$('.bottom-nav .nav-item').forEach((b) => {
        b.classList.toggle('active-nav', b === btn);
      });
      const menu = $('#create-menu');
      if (menu) menu.hidden = true;
    });
  });

  // 2. Ouverture et fermeture du menu Créer (+)
  const ouvrirMenuCreation = () => {
    const menu = $('#create-menu');
    if (menu) menu.hidden = false;
  };
  $('#publish-btn')?.addEventListener('click', ouvrirMenuCreation);
  $('#empty-create-btn')?.addEventListener('click', ouvrirMenuCreation);
  $('#close-create-menu')?.addEventListener('click', () => {
    const menu = $('#create-menu');
    if (menu) menu.hidden = true;
  });

  // 3. Onglets du haut (Suivis / Pour toi / LIVE)
  $$('[data-feed-tab]').forEach((tab) => {
    tab.addEventListener('click', () => {
      $$('[data-feed-tab]').forEach((t) => t.classList.toggle('active', t === tab));
      const isLive = tab.dataset.feedTab === 'live';
      const livePanel = $('#live-placeholder');
      const feed = $('#video-feed');
      if (livePanel) livePanel.hidden = !isLive;
      if (feed) feed.hidden = isLive;
    });
  });
});
// --- 508. DÉBLOCAGE IMMÉDIAT DU PROCESSEUR ET DE TOUS LES BOUTONS ---
(() => {
  // 1. Empêcher les futurs MutationObserver de geler l'écran
  const OriginalObserver = window.MutationObserver;
  let observerCount = 0;
  window.MutationObserver = function(callback) {
    observerCount++;
    if (observerCount > 3) {
      return { observe() {}, disconnect() {}, takeRecords() { return []; } };
    }
    return new OriginalObserver(callback);
  };

  // 2. Délégation globale des clics : chaque bouton répond instantanément
  document.addEventListener('click', (e) => {
    const target = e.target;

    // A. Boutons de la barre de navigation du bas (Accueil, Découvrir, Boîte, Profil)
    const navBtn = target.closest('.bottom-nav .nav-item[data-page]');
    if (navBtn) {
      e.preventDefault();
      e.stopPropagation();
      const page = navBtn.getAttribute('data-page');
      document.querySelectorAll('.page-section').forEach((sec) => {
        sec.hidden = (sec.id !== page + '-page');
      });
      document.querySelectorAll('.bottom-nav .nav-item').forEach((b) => {
        b.classList.toggle('active-nav', b === navBtn);
      });
      const menu = document.getElementById('create-menu');
      if (menu) menu.hidden = true;
      return;
    }

    // B. Bouton "+" central et bouton "Créer ma première publication"
    if (target.closest('#publish-btn') || target.closest('#empty-create-btn')) {
      e.preventDefault();
      e.stopPropagation();
      const menu = document.getElementById('create-menu');
      if (menu) menu.hidden = false;
      return;
    }

    // C. Fermer le menu Créer (✕)
    if (target.closest('#close-create-menu')) {
      e.preventDefault();
      e.stopPropagation();
      const menu = document.getElementById('create-menu');
      if (menu) menu.hidden = true;
      return;
    }

    // D. Boutons Vidéo / Photo dans le menu Créer
    if (target.closest('#create-video-btn')) {
      const sel = document.getElementById('fasotok-selecteur');
      if (sel) { sel.accept = 'video/*'; sel.click(); }
      return;
    }
    if (target.closest('#create-photo-btn')) {
      const sel = document.getElementById('fasotok-selecteur');
      if (sel) { sel.accept = 'image/*'; sel.click(); }
      return;
    }

    // E. Onglets du haut (Suivis / Pour toi / LIVE)
    const tabBtn = target.closest('[data-feed-tab]');
    if (tabBtn) {
      document.querySelectorAll('[data-feed-tab]').forEach((t) => {
        t.classList.toggle('active', t === tabBtn);
      });
      const isLive = tabBtn.getAttribute('data-feed-tab') === 'live';
      const livePanel = document.getElementById('live-placeholder');
      const feed = document.getElementById('video-feed');
      if (livePanel) livePanel.hidden = !isLive;
      if (feed) feed.hidden = isLive;
      return;
    }

    // F. Boutons de raccourcis dans le Profil (Studio, Amis, Assistant)
    const openPageBtn = target.closest('[data-open-page]');
    if (openPageBtn) {
      const page = openPageBtn.getAttribute('data-open-page');
      document.querySelectorAll('.page-section').forEach((sec) => {
        sec.hidden = (sec.id !== page + '-page');
      });
    }
  }, true);
})();
