// --- 513. GESTE DOUBLE-TAP ❤️ SUR TOUTES LES VIDÉOS & PHOTOS ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_513_DOUBLE_TAP_HEART_FEED', () => {
    const videoFeed = document.getElementById('video-feed');
    if (!videoFeed) return;

    let dernierTap = 0;

    videoFeed.addEventListener('click', (e) => {
      const carte = e.target.closest('.video-item');
      if (!carte || e.target.closest('button')) return;

      const maintenant = Date.now();
      if (maintenant - dernierTap < 300) {
        // 1. Faire apparaître le grand cœur TikTok à l'endroit du doigt
        const coeur = document.createElement('div');
        coeur.textContent = '❤️';
        coeur.style.cssText = `
          position: fixed; left: ${e.clientX - 40}px; top: ${e.clientY - 40}px;
          font-size: 80px; pointer-events: none; z-index: 30000;
          transform: scale(0.4); opacity: 1;
          transition: transform 0.55s ease-out, opacity 0.6s ease-out;
        `;
        document.body.appendChild(coeur);

        requestAnimationFrame(() => {
          coeur.style.transform = 'scale(1.5) translateY(-45px)';
          coeur.style.opacity = '0';
        });
        setTimeout(() => coeur.remove(), 650);

        // 2. Activer le bouton J'aime s'il n'est pas encore aimé
        const likeBtn = carte.querySelector('.like-btn');
        if (likeBtn && likeBtn.textContent.includes('🤍')) {
          likeBtn.click();
        }
      }
      dernierTap = maintenant;
    });
  });
});

// --- 514. HASHTAGS TENDANCES CLIQUABLES DANS L'ONGLET DÉCOUVRIR ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_514_DISCOVER_HASHTAG_CHIPS', () => {
    const discoverInput = document.getElementById('discover-search');
    const resultsBox = document.getElementById('discover-results');
    if (!discoverInput || !resultsBox) return;

    document.querySelectorAll('#discover-page .topic-chip[data-search-tag]').forEach((chip) => {
      chip.addEventListener('click', () => {
        const tag = chip.getAttribute('data-search-tag');
        discoverInput.value = tag;

        // Rechercher dans les publications locales
        const cartes = Array.from(document.querySelectorAll('#video-feed .video-item'));
        const correspondances = cartes.filter((c) => c.textContent.toLowerCase().includes(tag.toLowerCase()));

        resultsBox.innerHTML = `
          <div style="background:#1c1c29; padding:12px; border-radius:12px; border:1px solid #25f4ee; margin-bottom:8px;">
            <strong style="color:#25f4ee; font-size:15px;">🔥 Tendance ${tag}</strong>
            <p style="font-size:12px; color:#ccc; margin-top:4px;">${correspondances.length} publication(s) trouvée(s) sur ton appareil.</p>
          </div>
        `;

        correspondances.forEach((carte) => {
          const item = document.createElement('button');
          item.type = 'button';
          item.className = 'result-card';
          item.textContent = '▶️ ' + (carte.querySelector('.post-caption')?.textContent || 'Publication FasoTok');
          item.onclick = () => {
            document.querySelectorAll('.page-section').forEach((s) => s.hidden = s.id !== 'home-page');
            document.querySelectorAll('.bottom-nav .nav-item').forEach((b) => b.classList.toggle('active-nav', b.dataset.page === 'home'));
            carte.scrollIntoView({ behavior: 'smooth' });
          };
          resultsBox.appendChild(item);
        });
      });
    });
  });
});
// --- 515. CONTRÔLE SON (🔊/🔇) ET ICÔNE PAUSE/LECTURE SUR LES VIDÉOS ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_515_VIDEO_AUDIO_AND_PLAY_UI', () => {
    const videoFeed = document.getElementById('video-feed');
    if (!videoFeed) return;

    const equiperLecteur = (carte) => {
      if (carte.dataset.audioUiReady) return;
      carte.dataset.audioUiReady = 'true';

      const vid = carte.querySelector('video');
      if (!vid) return;

      // 1. Bouton Son discret en bas à droite au-dessus de la barre d'actions
      const actionsBar = carte.querySelector('.post-actions');
      if (actionsBar) {
        const soundBtn = document.createElement('button');
        soundBtn.type = 'button';
        soundBtn.className = 'post-action';
        soundBtn.textContent = vid.muted ? '🔇 Son' : '🔊 Son';

        soundBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          vid.muted = !vid.muted;
          soundBtn.textContent = vid.muted ? '🔇 Son' : '🔊 Son';
        });
        actionsBar.prepend(soundBtn);
      }

      // 2. Icône centrale "▶️" quand la vidéo est mise en pause
      const pauseIcon = document.createElement('div');
      pauseIcon.textContent = '▶️';
      pauseIcon.style.cssText = `
        position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
        font-size: 56px; opacity: 0; pointer-events: none; transition: opacity 0.2s ease;
        text-shadow: 0 4px 15px rgba(0,0,0,0.8); z-index: 15;
      `;
      carte.appendChild(pauseIcon);

      vid.addEventListener('pause', () => { pauseIcon.style.opacity = '0.85'; });
      vid.addEventListener('play', () => { pauseIcon.style.opacity = '0'; });
    };

    videoFeed.querySelectorAll('.video-item').forEach(equiperLecteur);
    setInterval(() => {
      videoFeed.querySelectorAll('.video-item').forEach(equiperLecteur);
    }, 1500);
  });
});

// --- 516. ONGLETS BOÎTE DE RÉCEPTION & RÉPONSES RAPIDES ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_516_INBOX_TABS_AND_QUICK_REPLIES', () => {
    const inboxTabs = document.querySelectorAll('#inbox-page [data-inbox-tab]');
    const activityPanel = document.getElementById('inbox-activity-panel');
    const messagesPanel = document.getElementById('inbox-messages-panel');
    if (!inboxTabs.length || !activityPanel || !messagesPanel) return;

    // 1. Basculer entre Activité et Messages
    inboxTabs.forEach((tab) => {
      tab.addEventListener('click', () => {
        inboxTabs.forEach((t) => t.classList.toggle('active', t === tab));
        const mode = tab.getAttribute('data-inbox-tab');
        activityPanel.hidden = mode !== 'activity';
        messagesPanel.hidden = mode !== 'messages';
      });
    });

    // 2. Ajouter des réponses rapides dans le panneau Messages
    if (!document.getElementById('quick-replies-516')) {
      const box = document.createElement('div');
      box.id = 'quick-replies-516';
      box.style.cssText = 'margin-top: 12px; display: flex; flex-wrap: wrap; gap: 6px;';
      box.innerHTML = `<p style="width:100%; font-size:11px; color:#25f4ee;">⚡ Réponses rapides :</p>`;

      ['👋 Salut !', '🔥 Super vidéo !', '🤝 On fait un Duo ?', '🇧🇫 Force à toi !'].forEach((msg) => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.textContent = msg;
        chip.style.cssText = 'background:#1c1c29; border:1px solid #333; color:#fff; padding:6px 10px; border-radius:14px; font-size:11px;';
        chip.onclick = () => {
          if (window.fasotokNotify) window.fasotokNotify(`Message envoyé : "${msg}"`);
        };
        box.appendChild(chip);
      });
      messagesPanel.querySelector('div')?.appendChild(box);
    }
  });
});
