// --- 521. COMPTEUR DE COMMENTAIRES EN DIRECT SUR CHAQUE VIDÉO ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_521_LIVE_COMMENT_COUNTER', () => {
    const majCompteursCommentaires = () => {
      document.querySelectorAll('#video-feed .video-item').forEach((carte, idx) => {
        const btn = carte.querySelector('.comment-btn');
        if (!btn) return;

        const postId = carte.dataset.postId || '';
        const auteur = carte.querySelector('.post-caption strong, h3')?.textContent || 'vid_' + idx;
        const altId = auteur.replace(/[^a-zA-Z0-9]/g, '') + '_' + idx;

        const c1 = JSON.parse(localStorage.getItem('fasotok_comments_' + postId) || '[]');
        const c2 = JSON.parse(localStorage.getItem('fasotok_coms_' + (postId || altId)) || '[]');
        const total = Math.max(c1.length, c2.length);

        btn.textContent = `💬 ${total}`;
      });
    };

    majCompteursCommentaires();
    document.addEventListener('submit', (e) => {
      if (e.target && e.target.id === 'drawer-comment-form') {
        setTimeout(majCompteursCommentaires, 150);
      }
    });
    setInterval(majCompteursCommentaires, 2500);
  });
});

// --- 522. HASHTAGS CLIQUABLES DIRECTEMENT DANS LA LÉGENDE DES VIDÉOS ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_522_CLICKABLE_CAPTION_HASHTAGS', () => {
    const videoFeed = document.getElementById('video-feed');
    if (!videoFeed) return;

    const activerHashtags = () => {
      videoFeed.querySelectorAll('.post-caption p').forEach((p) => {
        if (p.dataset.hashtagsLinked === 'true') return;
        p.dataset.hashtagsLinked = 'true';

        p.innerHTML = p.textContent.replace(/(#[a-zA-Z0-9_\u00C0-\u017F]+)/g, (tag) => {
          return `<span class="ft-inline-tag" data-tag="${tag}" style="color:#25f4ee; font-weight:bold; cursor:pointer;">${tag}</span>`;
        });
      });
    };

    activerHashtags();
    setInterval(activerHashtags, 2000);

    videoFeed.addEventListener('click', (e) => {
      const tagEl = e.target.closest('.ft-inline-tag');
      if (!tagEl) return;
      e.stopPropagation();

      const tag = tagEl.getAttribute('data-tag');
      // Basculer vers l'onglet Découvrir et lancer la recherche sur ce hashtag
      document.querySelectorAll('.page-section').forEach((sec) => {
        sec.hidden = sec.id !== 'discover-page';
      });
      document.querySelectorAll('.bottom-nav .nav-item').forEach((b) => {
        b.classList.toggle('active-nav', b.dataset.page === 'discover');
      });

      const discoverInput = document.getElementById('discover-search');
      if (discoverInput) {
        discoverInput.value = tag;
        discoverInput.dispatchEvent(new Event('input'));
      }
    });
  });
});
// --- 523. TRI PAR POPULARITÉ (PLUS RÉCENTES / PLUS AIMÉES) DANS DÉCOUVRIR ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_523_DISCOVER_SORT_FILTER', () => {
    const discoverSub = document.querySelector('#discover-page .subheading');
    const resultsBox = document.getElementById('discover-results');
    if (!discoverSub || !resultsBox || document.getElementById('discover-sort-select')) return;

    const sortSelect = document.createElement('select');
    sortSelect.id = 'discover-sort-select';
    sortSelect.style.cssText = `
      width: 100%; padding: 10px 12px; margin-bottom: 12px; border-radius: 12px;
      background: #1c1c29; color: #fff; border: 1px solid rgba(255,255,255,0.12); font-size: 13px;
    `;
    sortSelect.innerHTML = `
      <option value="recent">🕒 Trier : Plus récentes</option>
      <option value="likes">❤️ Trier : Plus aimées</option>
    `;
    discoverSub.after(sortSelect);

    sortSelect.addEventListener('change', () => {
      const cartes = Array.from(document.querySelectorAll('#video-feed .video-item'));
      if (!cartes.length) return;

      const triees = [...cartes].sort((a, b) => {
        if (sortSelect.value === 'likes') {
          const likeA = parseInt((a.querySelector('.like-btn')?.textContent || '0').replace(/\D/g, ''), 10) || 0;
          const likeB = parseInt((b.querySelector('.like-btn')?.textContent || '0').replace(/\D/g, ''), 10) || 0;
          return likeB - likeA;
        }
        return 0;
      });

      resultsBox.innerHTML = '';
      triees.forEach((carte) => {
        const likes = carte.querySelector('.like-btn')?.textContent || '🤍 0';
        const desc = carte.querySelector('.post-caption p')?.textContent || 'Publication FasoTok';
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'result-card';
        btn.textContent = `${likes} • ${desc}`;
        btn.onclick = () => {
          document.querySelectorAll('.page-section').forEach((s) => s.hidden = s.id !== 'home-page');
          document.querySelectorAll('.bottom-nav .nav-item').forEach((b) => b.classList.toggle('active-nav', b.dataset.page === 'home'));
          carte.scrollIntoView({ behavior: 'smooth' });
        };
        resultsBox.appendChild(btn);
      });
    });
  });
});

// --- 524. SYNCHRONISATION DES FAVORIS (🔖) AVEC LA GRILLE DU PROFIL ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_524_SYNC_BOOKMARKS_TO_PROFILE', () => {
    const majGrilleFavoris = () => {
      const favGrid = document.getElementById('profile-favs-grid');
      if (!favGrid) return;

      const savedIds = JSON.parse(localStorage.getItem('fasotok_saved_posts') || '[]');
      const cartes = Array.from(document.querySelectorAll('#video-feed .video-item'));
      const favorites = cartes.filter((c) => savedIds.includes(c.dataset.postId));

      if (!favorites.length) return;
      favGrid.innerHTML = '';

      favorites.forEach((carte) => {
        const media = carte.querySelector('.post-media');
        if (!media) return;

        const cell = document.createElement('div');
        cell.style.cssText = 'aspect-ratio: 9/16; background: #111; border-radius: 6px; overflow: hidden; position: relative;';
        cell.innerHTML = media.tagName === 'VIDEO'
          ? `<video src="${media.src}" muted style="width:100%; height:100%; object-fit:cover;"></video>`
          : `<img src="${media.src}" style="width:100%; height:100%; object-fit:cover;">`;
        favGrid.appendChild(cell);
      });
    };

    document.addEventListener('click', (e) => {
      if (e.target && (e.target.closest('.save-btn') || e.target.id === 'tab-my-favs')) {
        setTimeout(majGrilleFavoris, 150);
      }
    });
  });
});
// --- 525. GESTION & SUPPRESSION DE TES VIDÉOS DEPUIS LE PROFIL ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_525_PROFILE_DELETE_POST', () => {
    const myGrid = document.getElementById('my-videos-grid');
    if (!myGrid) return;

    myGrid.addEventListener('contextmenu', (e) => {
      const vignette = e.target.closest('div');
      if (!vignette || !myGrid.contains(vignette)) return;
      e.preventDefault();

      if (confirm('🗑️ Supprimer définitivement cette publication de ton appareil ?')) {
        const media = vignette.querySelector('video, img');
        const src = media ? media.src : '';
        vignette.remove();

        // Retirer aussi la carte correspondante dans le fil d'accueil
        document.querySelectorAll('#video-feed .video-item').forEach((carte) => {
          const m = carte.querySelector('.post-media');
          if (m && m.src === src) {
            carte.remove();
          }
        });

        if (window.fasotokNotify) window.fasotokNotify('Publication supprimée.');
      }
    });
  });
});

