// --- 527. MENTIONS @PSEUDO CLIQUABLES DANS LES DESCRIPTIONS ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_527_CLICKABLE_MENTIONS', () => {
    const videoFeed = document.getElementById('video-feed');
    if (!videoFeed) return;

    const lierMentions = () => {
      videoFeed.querySelectorAll('.post-caption p').forEach((p) => {
        if (p.dataset.mentionsLinked === 'true') return;
        p.dataset.mentionsLinked = 'true';

        p.innerHTML = p.innerHTML.replace(/(^|\s)(@[a-zA-Z0-9_.-]+)/g, (match, espace, mention) => {
          return `${espace}<span class="ft-inline-mention" data-user="${mention}" style="color:#feca57; font-weight:bold; cursor:pointer;">${mention}</span>`;
        });
      });
    };

    lierMentions();
    setInterval(lierMentions, 2000);

    videoFeed.addEventListener('click', (e) => {
      const mentionEl = e.target.closest('.ft-inline-mention');
      if (!mentionEl) return;
      e.stopPropagation();

      const pseudo = mentionEl.getAttribute('data-user');
      document.querySelectorAll('.page-section').forEach((sec) => {
        sec.hidden = sec.id !== 'discover-page';
      });
      document.querySelectorAll('.bottom-nav .nav-item').forEach((b) => {
        b.classList.toggle('active-nav', b.dataset.page === 'discover');
      });

      const discoverInput = document.getElementById('discover-search');
      if (discoverInput) {
        discoverInput.value = pseudo;
        discoverInput.dispatchEvent(new Event('input'));
      }
    });
  });
});

