// --- 540. ONGLETS DE FILTRE (TOUT / CRÉATEURS / VIDÉOS) DANS DÉCOUVRIR ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_540_DISCOVER_FILTER_TABS', () => {
    const searchField = document.querySelector('#discover-page .search-field');
    const searchInput = document.getElementById('discover-search');
    const resultsBox = document.getElementById('discover-results');
    if (!searchField || !searchInput || !resultsBox || document.getElementById('discover-tabs-540')) return;

    let filtreActif = 'all';

    const tabsBar = document.createElement('div');
    tabsBar.id = 'discover-tabs-540';
    tabsBar.style.cssText = 'display: flex; gap: 12px; margin-top: 12px; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 6px;';

    const onglets = [
      { id: 'all', label: 'Tout' },
      { id: 'creators', label: 'Créateurs @' },
      { id: 'videos', label: 'Vidéos' }
    ];

    onglets.forEach((o) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.textContent = o.label;
      btn.style.cssText = `
        background: none; border: none; font-size: 13px; font-weight: bold; padding-bottom: 4px;
        color: ${o.id === 'all' ? '#fff' : '#888'};
        border-bottom: ${o.id === 'all' ? '2px solid #25f4ee' : 'none'};
      `;

      btn.addEventListener('click', () => {
        filtreActif = o.id;
        tabsBar.querySelectorAll('button').forEach((b) => {
          b.style.color = b === btn ? '#fff' : '#888';
          b.style.borderBottom = b === btn ? '2px solid #25f4ee' : 'none';
        });
        filtrerResultats();
      });
      tabsBar.appendChild(btn);
    });

    searchField.after(tabsBar);

    const filtrerResultats = () => {
      const q = searchInput.value.trim().toLowerCase();
      const cartes = Array.from(document.querySelectorAll('#video-feed .video-item'));
      resultsBox.innerHTML = '';

      if (filtreActif === 'creators') {
        const pseudos = [...new Set(cartes.map((c) => c.querySelector('.post-caption strong, h3')?.textContent?.trim()).filter(Boolean))];
        const matches = pseudos.filter((p) => !q || p.toLowerCase().includes(q));
        if (!matches.length) {
          resultsBox.textContent = 'Aucun créateur trouvé.';
          return;
        }
        matches.forEach((pseudo) => {
          const card = document.createElement('div');
          card.className = 'result-card';
          card.textContent = `👤 ${pseudo}`;
          resultsBox.appendChild(card);
        });
      } else {
        const matches = cartes.filter((c) => !q || c.textContent.toLowerCase().includes(q));
        if (!matches.length) {
          resultsBox.textContent = 'Aucune vidéo trouvée.';
          return;
        }
        matches.forEach((carte) => {
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'result-card';
          btn.textContent = '🎬 ' + (carte.querySelector('.post-caption')?.textContent || 'Publication');
          btn.onclick = () => {
            document.querySelectorAll('.page-section').forEach((s) => s.hidden = s.id !== 'home-page');
            document.querySelectorAll('.bottom-nav .nav-item').forEach((b) => b.classList.toggle('active-nav', b.dataset.page === 'home'));
            carte.scrollIntoView({ behavior: 'smooth' });
          };
          resultsBox.appendChild(btn);
        });
      }
    };

    searchInput.addEventListener('input', filtrerResultats);
  });
});
