// --- 543. COMPTEUR DE PARTAGES EN DIRECT SUR LE BOUTON PARTAGER (↗) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_543_LIVE_SHARE_COUNTER', () => {
    const videoFeed = document.getElementById('video-feed');
    if (!videoFeed) return;

    const majCompteursPartages = () => {
      const shareCounts = JSON.parse(localStorage.getItem('fasotok_share_counts') || '{}');
      videoFeed.querySelectorAll('.video-item').forEach((carte, idx) => {
        const shareBtn = carte.querySelector('.share-btn');
        if (!shareBtn) return;

        const postId = carte.dataset.postId || 'vid_' + idx;
        const total = shareCounts[postId] || 0;
        shareBtn.textContent = `↗ ${total}`;
      });
    };

    majCompteursPartages();

    videoFeed.addEventListener('click', (e) => {
      const shareBtn = e.target.closest('.share-btn');
      if (!shareBtn) return;

      const carte = shareBtn.closest('.video-item');
      const postId = carte?.dataset.postId || 'vid_0';
      const shareCounts = JSON.parse(localStorage.getItem('fasotok_share_counts') || '{}');
      shareCounts[postId] = (shareCounts[postId] || 0) + 1;
      localStorage.setItem('fasotok_share_counts', JSON.stringify(shareCounts));

      shareBtn.textContent = `↗ ${shareCounts[postId]}`;
    }, true);
  });
});

// --- 544. HISTORIQUE DES RECHERCHES RÉCENTES DANS DÉCOUVRIR (STYLE TIKTOK) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_544_DISCOVER_SEARCH_HISTORY', () => {
    const searchField = document.querySelector('#discover-page .search-field');
    const searchInput = document.getElementById('discover-search');
    if (!searchField || !searchInput || document.getElementById('discover-history-544')) return;

    const historyBox = document.createElement('div');
    historyBox.id = 'discover-history-544';
    historyBox.style.cssText = 'display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px;';
    searchField.after(historyBox);

    const afficherHistorique = () => {
      const hist = JSON.parse(localStorage.getItem('fasotok_search_history') || '[]');
      historyBox.innerHTML = '';

      hist.forEach((terme) => {
        const pill = document.createElement('div');
        pill.style.cssText = `
          display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px;
          background: #1c1c29; border: 1px solid rgba(255,255,255,0.1);
          border-radius: 16px; font-size: 12px; color: #ddd; cursor: pointer;
        `;

        const label = document.createElement('span');
        label.textContent = `🕒 ${terme}`;
        label.onclick = () => {
          searchInput.value = terme;
          searchInput.dispatchEvent(new Event('input'));
        };

        const del = document.createElement('span');
        del.textContent = '✕';
        del.style.cssText = 'color: #888; font-size: 11px; padding-left: 2px;';
        del.onclick = (e) => {
          e.stopPropagation();
          const maj = hist.filter((t) => t !== terme);
          localStorage.setItem('fasotok_search_history', JSON.stringify(maj));
          afficherHistorique();
        };

        pill.append(label, del);
        historyBox.appendChild(pill);
      });
    };

    searchInput.addEventListener('change', () => {
      const val = searchInput.value.trim();
      if (val.length < 2) return;
      let hist = JSON.parse(localStorage.getItem('fasotok_search_history') || '[]');
      hist = [val, ...hist.filter((t) => t.toLowerCase() !== val.toLowerCase())].slice(0, 6);
      localStorage.setItem('fasotok_search_history', JSON.stringify(hist));
      afficherHistorique();
    });

    afficherHistorique();
  });
});
