// --- 563. TRI DES VIDÉOS SUR LE PROFIL (PLUS RÉCENTES / PLUS POPULAIRES) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_563_PROFILE_GRID_SORT', () => {
    const myGrid = document.getElementById('my-videos-grid');
    if (!myGrid || document.getElementById('profile-sort-563')) return;

    const sortBar = document.createElement('div');
    sortBar.id = 'profile-sort-563';
    sortBar.style.cssText = 'display: flex; justify-content: flex-end; margin-bottom: 8px;';

    const select = document.createElement('select');
    select.style.cssText = `
      background: #1c1c29; color: #ddd; border: 1px solid rgba(255,255,255,0.12);
      border-radius: 8px; padding: 5px 10px; font-size: 11px;
    `;
    select.innerHTML = `
      <option value="recent">🕒 Plus récentes</option>
      <option value="popular">🔥 Plus populaires</option>
    `;

    sortBar.appendChild(select);
    myGrid.before(sortBar);

    select.addEventListener('change', () => {
      const vignettes = Array.from(myGrid.children).filter((el) => el.tagName === 'DIV');
      if (vignettes.length < 2) return;

      const triees = [...vignettes].sort((a, b) => {
        if (select.value === 'popular') {
          const vA = parseInt((a.querySelector('.ft-grid-views-536')?.textContent || '0').replace(/\D/g, ''), 10) || 0;
          const vB = parseInt((b.querySelector('.ft-grid-views-536')?.textContent || '0').replace(/\D/g, ''), 10) || 0;
          return vB - vA;
        }
        return 0;
      });

      triees.forEach((v) => myGrid.appendChild(v));
    });
  });
});
