window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_577_INBOX_DIRECT_MESSAGES_CHAT', () => {
    const messagesPanel = document.getElementById('inbox-messages-panel');
    if (!messagesPanel || document.getElementById('ft-dm-box-577')) return;

    messagesPanel.style.flexDirection = 'column';
    messagesPanel.innerHTML = `
      <div id="ft-dm-box-577" style="width:100%; display:flex; flex-direction:column; gap:10px;">
        <div style="display:flex; align-items:center; gap:10px; padding-bottom:8px; border-bottom:1px solid rgba(255,255,255,0.1);">
          <span style="font-size:24px;">🇧🇫</span>
          <div>
            <strong style="font-size:14px;">Communauté FasoTok</strong>
            <p style="font-size:11px; color:#25f4ee;">En ligne • Messagerie locale</p>
          </div>
        </div>
        <div id="ft-dm-history-577" style="min-height:160px; max-height:240px; overflow-y:auto; display:flex; flex-direction:column; gap:8px; padding:6px 0;"></div>
        <form id="ft-dm-form-577" style="display:flex; gap:8px; margin-top:4px;">
          <input type="text" id="ft-dm-input-577" placeholder="Envoyer un message..." required style="flex:1; padding:10px 14px; border-radius:20px; border:1px solid #333; background:#1c1c29; color:#fff; font-size:13px;">
          <button type="submit" style="background:#fe2c55; color:#fff; border:none; border-radius:20px; padding:0 16px; font-weight:bold;">➤</button>
        </form>
      </div>
    `;

    const historyBox = document.getElementById('ft-dm-history-577');
    const dmForm = document.getElementById('ft-dm-form-577');
    const dmInput = document.getElementById('ft-dm-input-577');

    const renderMessages = () => {
      const msgs = JSON.parse(localStorage.getItem('fasotok_dm_messages') || '[{"from":"bot","text":"Bienvenue dans ta messagerie FasoTok ! Écris ton premier message ci-dessous 👋"}]');
      historyBox.innerHTML = msgs.map((m) => `
        <div style="
          align-self: ${m.from === 'me' ? 'flex-end' : 'flex-start'};
          background: ${m.from === 'me' ? '#fe2c55' : '#1c1c29'};
          color: #fff; padding: 9px 13px; border-radius: 16px;
          max-width: 80%; font-size: 13px; line-height: 1.4;
        ">${m.text}</div>
      `).join('');
      historyBox.scrollTop = historyBox.scrollHeight;
    };

    renderMessages();

    dmForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const txt = dmInput.value.trim();
      if (!txt) return;

      const msgs = JSON.parse(localStorage.getItem('fasotok_dm_messages') || '[]');
      msgs.push({ from: 'me', text: txt });
      localStorage.setItem('fasotok_dm_messages', JSON.stringify(msgs));
      dmInput.value = '';
      renderMessages();
    });
  });
});
