// --- 583. VERROUILLER / DÉVERROUILLER LES COMMENTAIRES D'UNE VIDÉO ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_583_TOGGLE_VIDEO_COMMENTS_LOCK', () => {
    // 1. Bloquer l'ouverture du tiroir si les commentaires sont désactivés sur cette vidéo
    document.addEventListener('click', (e) => {
      const comBtn = e.target.closest('.comment-btn');
      if (!comBtn) return;

      const carte = comBtn.closest('.video-item');
      const postId = carte?.dataset.postId || '';
      const lockedList = JSON.parse(localStorage.getItem('fasotok_locked_comments') || '[]');

      if (lockedList.includes(postId)) {
        e.preventDefault();
        e.stopPropagation();
        if (window.fasotokNotify) window.fasotokNotify('🔒 Les commentaires sont désactivés pour cette vidéo.');
      }
    }, true);

    // 2. Ajouter le bouton d'activation/désactivation dans la feuille Partager (↪️)
    document.addEventListener('click', (e) => {
      const shareBtn = e.target.closest('.share-btn');
      if (!shareBtn) return;

      const carte = shareBtn.closest('.video-item');
      const postId = carte?.dataset.postId || '';
      if (!postId) return;

      setTimeout(() => {
        const sheet = document.getElementById('ft-share-sheet-532');
        const list = sheet?.querySelector('div[style*="flex-direction:column"]');
        if (!list || document.getElementById('lock-com-583')) return;

        let lockedList = JSON.parse(localStorage.getItem('fasotok_locked_comments') || '[]');
        const estVerrouille = lockedList.includes(postId);

        const lockBtn = document.createElement('button');
        lockBtn.id = 'lock-com-583';
        lockBtn.type = 'button';
        lockBtn.textContent = estVerrouille ? '🔓 Activer les commentaires' : '🔒 Désactiver les commentaires';
        lockBtn.style.cssText = 'text-align:left; padding:12px; background:#222533; border:none; border-radius:10px; color:#feca57; font-weight:bold;';

        lockBtn.onclick = () => {
          sheet.remove();
          let liste = JSON.parse(localStorage.getItem('fasotok_locked_comments') || '[]');
          if (liste.includes(postId)) {
            liste = liste.filter((id) => id !== postId);
            if (window.fasotokNotify) window.fasotokNotify('🔓 Commentaires activés.');
          } else {
            liste.push(postId);
            if (window.fasotokNotify) window.fasotokNotify('🔒 Commentaires désactivés.');
          }
          localStorage.setItem('fasotok_locked_comments', JSON.stringify(liste));
        };

        list.appendChild(lockBtn);
      }, 35);
    }, true);
  });
});
// --- 584. CHANGER SA PHOTO DE PROFIL DEPUIS LA GALERIE DU TÉLÉPHONE ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_584_CUSTOM_PROFILE_AVATAR_PICKER', () => {
    const avatarBox = document.querySelector('#profile-page .profile-avatar');
    if (!avatarBox) return;

    // 1. Charger la photo enregistrée au démarrage
    const appliquerPhoto = (dataUrl) => {
      if (!dataUrl) return;
      avatarBox.innerHTML = `<img src="${dataUrl}" alt="Avatar" style="width:100%; height:100%; border-radius:50%; object-fit:cover;">`;
    };
    appliquerPhoto(localStorage.getItem('fasotok_avatar_img'));

    // 2. Créer le sélecteur d'image caché
    const fileInput = document.createElement('input');
    fileInput.type = 'file';
    fileInput.accept = 'image/*';
    fileInput.hidden = true;
    document.body.appendChild(fileInput);

    avatarBox.style.cursor = 'pointer';
    avatarBox.title = 'Changer ma photo de profil';
    avatarBox.addEventListener('click', () => fileInput.click());

    fileInput.addEventListener('change', (e) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = () => {
        localStorage.setItem('fasotok_avatar_img', reader.result);
        appliquerPhoto(reader.result);
        if (window.fasotokNotify) window.fasotokNotify('Photo de profil mise à jour !');
      };
      reader.readAsDataURL(file);
    });
  });
});

// --- 585. FILTRES D'ACTIVITÉ DANS "BOÎTE -> ACTIVITÉ" (TOUT / J'AIME / FAVORIS) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_585_INBOX_ACTIVITY_FILTER_CHIPS', () => {
    const activityPanel = document.getElementById('inbox-activity-panel');
    if (!activityPanel) return;

    const installerFiltresActivite = () => {
      const titre = activityPanel.querySelector('h3');
      if (!titre || document.getElementById('act-filters-585')) return;

      const bar = document.createElement('div');
      bar.id = 'act-filters-585';
      bar.style.cssText = 'display: flex; gap: 6px; margin: 10px 0;';

      const filtres = [
        { id: 'all', label: 'Tout' },
        { id: 'like', label: "❤️ J'aime" },
        { id: 'fav', label: '⭐ Favoris' }
      ];

      filtres.forEach((f, idx) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.textContent = f.label;
        btn.style.cssText = `
          padding: 4px 10px; border-radius: 12px; font-size: 11px; font-weight: bold;
          background: #1c1c29; border: 1px solid ${idx === 0 ? '#25f4ee' : '#333'};
          color: ${idx === 0 ? '#25f4ee' : '#aaa'}; cursor: pointer;
        `;

        btn.onclick = () => {
          bar.querySelectorAll('button').forEach((b) => {
            b.style.borderColor = b === btn ? '#25f4ee' : '#333';
            b.style.color = b === btn ? '#25f4ee' : '#aaa';
          });

          activityPanel.querySelectorAll('div[style*="border-top"]').forEach((ligne) => {
            const txt = ligne.textContent;
            if (f.id === 'all') ligne.style.display = 'flex';
            else if (f.id === 'like') ligne.style.display = txt.includes('aimé') ? 'flex' : 'none';
            else if (f.id === 'fav') ligne.style.display = txt.includes('favori') ? 'flex' : 'none';
          });
        };

        bar.appendChild(btn);
      });

      titre.after(bar);
    };

    installerFiltresActivite();
    setInterval(installerFiltresActivite, 1500);
  });
});
