// --- 588. SUGGESTIONS DE CRÉATEURS LOCAUX À SUIVRE DANS L'ONGLET "AMIS" ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_588_FRIENDS_TAB_SUGGESTIONS', () => {
    const friendsPage = document.getElementById('friends-page');
    if (!friendsPage || document.getElementById('ft-suggested-creators-588')) return;

    const suggestions = [
      { pseudo: '@OuagaVibes226', desc: 'Humour & scènes de vie à Ouaga 😂🇧🇫' },
      { pseudo: '@BoboDance_Off', desc: 'Chorégraphies Afrobeat & Coupé-Décalé 💃' },
      { pseudo: '@YatengaStar', desc: 'Talents & découvertes du Nord 🌍🔥' },
      { pseudo: '@EtalonsFoot', desc: 'Actus & exploits des Étalons ⚽🇧🇫' }
    ];

    const box = document.createElement('div');
    box.id = 'ft-suggested-creators-588';
    box.style.cssText = 'margin-top: 18px; display: flex; flex-direction: column; gap: 10px;';
    box.innerHTML = `<h3 style="font-size: 15px; margin-bottom: 4px;">✨ Comptes suggérés pour toi</h3>`;

    const abonnements = JSON.parse(localStorage.getItem('fasotok_abonnements') || '[]');

    suggestions.forEach((c) => {
      const estSuivi = abonnements.includes(c.pseudo);
      const row = document.createElement('div');
      row.style.cssText = `
        display: flex; justify-content: space-between; align-items: center;
        padding: 12px; background: #14141e; border: 1px solid rgba(255,255,255,0.08);
        border-radius: 14px;
      `;
      row.innerHTML = `
        <div>
          <strong style="font-size: 14px;">${c.pseudo}</strong>
          <p style="font-size: 12px; color: #aaa; margin-top: 3px;">${c.desc}</p>
        </div>
        <button type="button" style="
          padding: 7px 14px; border-radius: 8px; border: none; font-weight: bold; font-size: 12px;
          background: ${estSuivi ? '#222533' : '#fe2c55'}; color: #fff; cursor: pointer;
        ">${estSuivi ? 'Abonné ✓' : 'Suivre'}</button>
      `;

      const btn = row.querySelector('button');
      btn.addEventListener('click', () => {
        let liste = JSON.parse(localStorage.getItem('fasotok_abonnements') || '[]');
        if (liste.includes(c.pseudo)) {
          liste = liste.filter((p) => p !== c.pseudo);
          btn.textContent = 'Suivre';
          btn.style.background = '#fe2c55';
        } else {
          liste.push(c.pseudo);
          btn.textContent = 'Abonné ✓';
          btn.style.background = '#222533';
        }
        localStorage.setItem('fasotok_abonnements', JSON.stringify(liste));
        const countEl = document.getElementById('profile-following-count');
        if (countEl) countEl.textContent = liste.length;
      });

      box.appendChild(row);
    });

    const friendsList = document.getElementById('friends-list');
    if (friendsList) friendsList.after(box);
  });
});

