// --- 591. CHOIX D'INSTANT DE COUVERTURE DANS L'ÉCRAN PUBLIER (+) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_591_PUBLISH_CUSTOM_COVER_FRAME', () => {
    const previewBox = document.getElementById('tk-thumb-preview-568');
    if (!previewBox) return;

    previewBox.style.cursor = 'pointer';
    previewBox.title = 'Appuie pour changer l’instant de couverture';

    previewBox.addEventListener('click', () => {
      const vid = previewBox.querySelector('video');
      if (!vid) {
        if (window.fasotokNotify) window.fasotokNotify('Choisis d’abord une vidéo pour ajuster sa couverture.');
        return;
      }

      const duree = Math.floor(vid.duration || 10);
      const sec = prompt(`🎞️ Choisis la seconde de couverture (entre 0 et ${duree}s) :`, '2');
      const val = parseFloat(sec);

      if (!isNaN(val) && val >= 0) {
        vid.currentTime = Math.min(val, duree);
        if (window.fasotokNotify) window.fasotokNotify(`Couverture calée à ${val}s !`);
      }
    });
  });
});
