// --- 593. MODIFIER SON CODE SECRET DANS "PARAMÈTRES & CONFIDENTIALITÉ" ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_593_SETTINGS_CHANGE_PASSWORD', () => {
    const settingsRows = document.querySelectorAll('#profile-page .setting-row');
    let securityRow = null;
    settingsRows.forEach((row) => {
      if (row.textContent.includes('Compte & sécurité')) securityRow = row;
    });

    if (!securityRow || document.getElementById('change-pass-btn-593')) return;

    const passBtn = document.createElement('button');
    passBtn.id = 'change-pass-btn-593';
    passBtn.type = 'button';
    passBtn.textContent = '🔑 Changer mon code secret';
    passBtn.className = 'secondary-action';
    passBtn.style.cssText = 'width: 100%; margin-top: 10px; font-size: 12px;';

    passBtn.addEventListener('click', async () => {
      const nouveauCode = prompt('🔑 Entre ton nouveau code secret (8 caractères minimum) :');
      if (!nouveauCode) return;
      if (nouveauCode.length < 8) {
        if (window.fasotokNotify) window.fasotokNotify('Le code secret doit contenir au moins 8 caractères.');
        return;
      }

      if (window.crypto?.subtle) {
        const bytes = new TextEncoder().encode(nouveauCode);
        const digest = await crypto.subtle.digest('SHA-256', bytes);
        const hash = [...new Uint8Array(digest)].map((v) => v.toString(16).padStart(2, '0')).join('');
        const account = JSON.parse(localStorage.getItem('fasotok_account_v1') || '{}');
        account.passwordHash = hash;
        localStorage.setItem('fasotok_account_v1', JSON.stringify(account));
        if (window.fasotokNotify) window.fasotokNotify('✅ Code secret mis à jour avec succès !');
      }
    });

    securityRow.appendChild(passBtn);
  });
});
