// --- 597. BOUTON D'EXPORTATION DE SAUVEGARDE JSON DANS LES PARAMÈTRES ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_597_EXPORT_LOCAL_BACKUP_SETTINGS', () => {
    const storageRow = document.getElementById('ft-storage-row-589');
    if (!storageRow || document.getElementById('export-backup-597')) return;

    const exportBtn = document.createElement('button');
    exportBtn.id = 'export-backup-597';
    exportBtn.type = 'button';
    exportBtn.textContent = '📥 Exporter une sauvegarde (.json)';
    exportBtn.className = 'secondary-action';
    exportBtn.style.cssText = 'width: 100%; margin-top: 8px; font-size: 12px; border-color: #25f4ee; color: #25f4ee;';

    exportBtn.addEventListener('click', () => {
      const backupData = {
        app: 'FasoTok Local',
        date: new Date().toISOString(),
        user: localStorage.getItem('fasotok_user') || 'MonProfil',
        bio: localStorage.getItem('fasotok_bio') || '',
        abonnements: JSON.parse(localStorage.getItem('fasotok_abonnements') || '[]'),
        langue: localStorage.getItem('fasotok-langue') || 'fr'
      };

      const blob = new Blob([JSON.stringify(backupData, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `FasoTok_Backup_${backupData.user}.json`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
      if (window.fasotokNotify) window.fasotokNotify('Sauvegarde téléchargée !');
    });

    storageRow.appendChild(exportBtn);
  });
});

