// --- 605. FILTRE ANTI-MOTS INDÉSIRABLES DANS LES PARAMÈTRES (STYLE TIKTOK) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_605_PRIVACY_COMMENT_KEYWORD_FILTER', () => {
    const settingsRows = document.querySelectorAll('#profile-page .setting-row');
    let securityRow = null;
    settingsRows.forEach((row) => {
      if (row.textContent.includes('Compte & sécurité')) securityRow = row;
    });

    if (securityRow && !document.getElementById('keyword-filter-btn-605')) {
      const filterBtn = document.createElement('button');
      filterBtn.id = 'keyword-filter-btn-605';
      filterBtn.type = 'button';
      filterBtn.textContent = '🛡️ Filtrer des mots-clés (Commentaires)';
      filterBtn.className = 'secondary-action';
      filterBtn.style.cssText = 'width: 100%; margin-top: 8px; font-size: 12px;';

      filterBtn.addEventListener('click', () => {
        const actuels = localStorage.getItem('fasotok_filtered_words') || '';
        const saisie = prompt(
          '🛡️ Entre les mots-clés à bloquer dans les commentaires (séparés par des virgules) :',
          actuels
        );
        if (saisie !== null) {
          localStorage.setItem('fasotok_filtered_words', saisie.trim());
          if (window.fasotokNotify) window.fasotokNotify('Filtre de commentaires enregistré !');
        }
      });

      securityRow.appendChild(filterBtn);
    }

    // Bloquer l'envoi d'un commentaire contenant un mot interdit
    document.addEventListener('submit', (e) => {
      if (e.target?.id !== 'drawer-comment-form') return;
      const input = document.getElementById('drawer-comment-input');
      const texte = (input?.value || '').toLowerCase();
      const motsBannis = (localStorage.getItem('fasotok_filtered_words') || '')
        .split(',')
        .map((m) => m.trim().toLowerCase())
        .filter(Boolean);

      if (motsBannis.some((mot) => texte.includes(mot))) {
        e.preventDefault();
        e.stopImmediatePropagation();
        if (window.fasotokNotify) window.fasotokNotify('⚠️ Ce commentaire contient un mot-clé filtré.');
      }
    }, true);
  });
});

