// --- 608. TRI DES ABONNEMENTS (RÉCENTS / ALPHABÉTIQUE A-Z) DANS L'ONGLET AMIS ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_608_FRIENDS_LIST_SORT_SELECTOR', () => {
    const friendsList = document.getElementById('friends-list');
    if (!friendsList || document.getElementById('friends-sort-608')) return;

    const sortBar = document.createElement('div');
    sortBar.id = 'friends-sort-608';
    sortBar.style.cssText = 'display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px;';
    sortBar.innerHTML = `
      <strong style="font-size: 13px; color: #ddd;">Mes abonnements</strong>
      <select id="friends-sort-select-608" style="background:#1c1c29; color:#ddd; border:1px solid rgba(255,255,255,0.12); border-radius:8px; padding:4px 8px; font-size:11px;">
        <option value="recent">🕒 Récents</option>
        <option value="az">🔤 Nom (A → Z)</option>
      </select>
    `;

    friendsList.before(sortBar);

    const select = document.getElementById('friends-sort-select-608');
    select.addEventListener('change', () => {
      const rows = Array.from(friendsList.querySelectorAll('div'));
      if (rows.length < 2) return;

      const sorted = [...rows].sort((a, b) => {
        if (select.value === 'az') {
          const nameA = (a.querySelector('strong')?.textContent || '').toLowerCase();
          const nameB = (b.querySelector('strong')?.textContent || '').toLowerCase();
          return nameA.localeCompare(nameB);
        }
        return 0;
      });

      sorted.forEach((r) => friendsList.appendChild(r));
    });
  });
});
// --- 609. AFFICHAGE & REPRISE DES BROUILLONS TEXTES DANS LE STUDIO ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_609_STUDIO_TEXT_DRAFTS_MANAGER', () => {
    const draftsWrap = document.getElementById('drafts-list');
    if (!draftsWrap) return;

    const afficherBrouillonsTextes = () => {
      const notes = JSON.parse(localStorage.getItem('fasotok_text_drafts') || '[]');
      let box = document.getElementById('ft-text-drafts-609');
      if (!notes.length) {
        if (box) box.remove();
        return;
      }

      if (!box) {
        box = document.createElement('div');
        box.id = 'ft-text-drafts-609';
        box.style.cssText = 'display: flex; flex-direction: column; gap: 8px; margin-bottom: 10px;';
        draftsWrap.prepend(box);
      }

      box.innerHTML = notes.map((n, idx) => `
        <div class="draft-row" style="border-color: rgba(37,244,238,0.25);">
          <div>
            <strong>✍️ Brouillon texte (${n.date})</strong>
            <p>${n.texte}</p>
          </div>
          <div class="draft-actions">
            <button type="button" data-use-note="${idx}">Reprendre</button>
            <button type="button" data-del-note="${idx}">Suppr.</button>
          </div>
        </div>
      `).join('');

      box.querySelectorAll('[data-use-note]').forEach((btn) => {
        btn.onclick = () => {
          const i = parseInt(btn.getAttribute('data-use-note'), 10);
          const item = notes[i];
          if (!item) return;
          const captionInput = document.getElementById('create-caption');
          const createMenu = document.getElementById('create-menu');
          if (captionInput) captionInput.value = item.texte;
          if (createMenu) createMenu.hidden = false;
        };
      });

      box.querySelectorAll('[data-del-note]').forEach((btn) => {
        btn.onclick = () => {
          const i = parseInt(btn.getAttribute('data-del-note'), 10);
          notes.splice(i, 1);
          localStorage.setItem('fasotok_text_drafts', JSON.stringify(notes));
          afficherBrouillonsTextes();
        };
      });
    };

    afficherBrouillonsTextes();
    setInterval(afficherBrouillonsTextes, 2000);
  });
});

// --- 610. CARTE CODE QR DE PROFIL STYLE TIKTOK DANS LE MENU "☰" ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_610_TIKTOK_PROFILE_QR_MODAL', () => {
    const qrMenuItem = document.querySelector('#tiktok-profile-menu-509 [data-go="qr"]');
    if (!qrMenuItem) return;

    qrMenuItem.onclick = () => {
      document.getElementById('tiktok-profile-menu-509').style.display = 'none';
      if (document.getElementById('ft-qr-modal-610')) return;

      const pseudo = (localStorage.getItem('fasotok_user') || 'MonProfil').replace(/^@+/, '');
      const lien = `${window.location.origin}/?u=${encodeURIComponent(pseudo)}`;

      const modal = document.createElement('div');
      modal.id = 'ft-qr-modal-610';
      modal.style.cssText = `
        position: fixed; inset: 0; z-index: 29000; background: rgba(0,0,0,0.85);
        display: flex; align-items: center; justify-content: center; padding: 20px;
        backdrop-filter: blur(5px);
      `;

      // Générer une matrice visuelle QR locale unique basée sur le pseudo
      let cellules = '';
      for (let i = 0; i < 64; i++) {
        const code = pseudo.charCodeAt(i % pseudo.length) + i * 7;
        const actif = code % 2 === 0 || i < 8 || i > 55;
        cellules += `<span style="background:${actif ? '#090910' : 'transparent'}; border-radius:2px;"></span>`;
      }

      modal.innerHTML = `
        <div style="width:100%; max-width:310px; background:linear-gradient(145deg, #fe2c55, #161823 50%, #25f4ee); padding:3px; border-radius:22px;">
          <div style="background:#14141e; border-radius:20px; padding:22px; text-align:center; color:#fff;">
            <strong style="font-size:17px;">@${pseudo}</strong>
            <p style="font-size:11px; color:#aaa; margin:4px 0 16px;">Code QR FasoTok 🇧🇫</p>
            <div style="width:156px; height:156px; margin:0 auto 16px; background:#fff; padding:12px; border-radius:14px; display:grid; grid-template-columns:repeat(8,1fr); gap:2px;">
              ${cellules}
            </div>
            <button type="button" id="copy-qr-link-610" style="width:100%; padding:11px; border:none; border-radius:10px; background:#fe2c55; color:#fff; font-weight:bold; margin-bottom:8px;">
              📋 Copier le lien du profil
            </button>
            <button type="button" id="close-qr-610" style="width:100%; padding:10px; border:1px solid #333; border-radius:10px; background:#1c1c29; color:#ccc;">
              Fermer
            </button>
          </div>
        </div>
      `;

      document.body.appendChild(modal);
      document.getElementById('close-qr-610').onclick = () => modal.remove();
      modal.onclick = (e) => { if (e.target === modal) modal.remove(); };
      document.getElementById('copy-qr-link-610').onclick = async () => {
        if (navigator.clipboard) await navigator.clipboard.writeText(lien);
        if (window.fasotokNotify) window.fasotokNotify('Lien de ton profil copié !');
      };
    };
  });
});
