// --- 618. SÉLECTEUR DE TRI DANS LE TIROIR DE COMMENTAIRES (💬) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_618_COMMENT_DRAWER_SORT_ORDER', () => {
    const drawerTitle = document.getElementById('drawer-title');
    const commentsList = document.getElementById('drawer-comments-list');
    if (!drawerTitle || !commentsList || document.getElementById('comment-sort-618')) return;

    const sortSelect = document.createElement('select');
    sortSelect.id = 'comment-sort-618';
    sortSelect.style.cssText = `
      margin-left: 10px; background: #222533; color: #ddd;
      border: 1px solid #333; border-radius: 8px; padding: 3px 6px; font-size: 11px;
    `;
    sortSelect.innerHTML = `
      <option value="recent">Récents</option>
      <option value="creator">❤️ Créateur</option>
    `;

    drawerTitle.after(sortSelect);

    sortSelect.addEventListener('change', () => {
      const items = Array.from(commentsList.querySelectorAll('div'));
      if (items.length < 2) return;

      const sorted = [...items].sort((a, b) => {
        if (sortSelect.value === 'creator') {
          const aLiked = a.textContent.includes('Aimé par le créateur') ? 1 : 0;
          const bLiked = b.textContent.includes('Aimé par le créateur') ? 1 : 0;
          return bLiked - aLiked;
        }
        return 0;
      });

      sorted.forEach((el) => commentsList.appendChild(el));
    });
  });
});
