// --- 620. CENTRE D'HISTORIQUE DE VISIONNAGE DANS LE MENU "☰" ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_620_WATCH_HISTORY_CENTER_IN_BURGER', () => {
    const videoFeed = document.getElementById('video-feed');
    const burgerList = document.querySelector('#tiktok-profile-menu-509 div[style*="flex-direction:column"]');
    if (!videoFeed || !burgerList || document.getElementById('history-item-620')) return;

    // 1. Enregistrer chaque vidéo regardée
    videoFeed.addEventListener('play', (e) => {
      const vid = e.target;
      const carte = vid.closest('.video-item');
      if (!carte) return;

      const auteur = carte.querySelector('.post-caption strong')?.textContent?.trim() || '@FasoTok';
      const desc = carte.querySelector('.post-caption p')?.textContent?.trim() || 'Vidéo FasoTok';
      const heure = new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });

      let hist = JSON.parse(localStorage.getItem('fasotok_watch_history_620') || '[]');
      if (!hist.length || hist[0].desc !== desc) {
        hist.unshift({ auteur, desc, heure });
        localStorage.setItem('fasotok_watch_history_620', JSON.stringify(hist.slice(0, 20)));
      }
    }, true);

    // 2. Ajouter le bouton dans le Menu "☰" du Profil
    const histBtn = document.createElement('button');
    histBtn.id = 'history-item-620';
    histBtn.type = 'button';
    histBtn.textContent = '🕒 Historique des vidéos regardées';
    histBtn.style.cssText = 'text-align:left; padding:12px; background:#222533; border:none; border-radius:10px; color:#fff; font-weight:bold;';

    histBtn.onclick = () => {
      document.getElementById('tiktok-profile-menu-509').style.display = 'none';
      const hist = JSON.parse(localStorage.getItem('fasotok_watch_history_620') || '[]');
      if (!hist.length) {
        alert('🕒 Ton historique de visionnage est vide pour le moment.');
        return;
      }

      const texte = hist.map((h, i) => `${i + 1}. ${h.auteur} — "${h.desc.slice(0, 40)}" (${h.heure})`).join('\n');
      if (confirm(`🕒 VIDÉOS REGARDÉES (${hist.length}) :\n\n${texte}\n\nAppuie sur OK pour vider l'historique, ou Annuler pour fermer.`)) {
        localStorage.removeItem('fasotok_watch_history_620');
        if (window.fasotokNotify) window.fasotokNotify('Historique de visionnage effacé.');
      }
    };

    burgerList.appendChild(histBtn);
  });
});
