// --- 622. TEMPS D'ÉCRAN & BIEN-ÊTRE NUMÉRIQUE DANS LE MENU "☰" ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_622_DIGITAL_WELLBEING_IN_BURGER', () => {
    const burgerList = document.querySelector('#tiktok-profile-menu-509 div[style*="flex-direction:column"]');
    if (!burgerList || document.getElementById('wellbeing-item-622')) return;

    const todayKey = 'fasotok_daily_mins_' + new Date().toISOString().slice(0, 10);

    // Compter 1 minute chaque 60 secondes tant que l'onglet est actif
    setInterval(() => {
      if (!document.hidden) {
        const mins = parseInt(localStorage.getItem(todayKey) || '0', 10) + 1;
        localStorage.setItem(todayKey, mins);

        const limite = parseInt(localStorage.getItem('fasotok_screen_limit_622') || '0', 10);
        if (limite > 0 && mins === limite && window.fasotokNotify) {
          window.fasotokNotify(`⏳ Rappel bien-être : tu as atteint ta limite de ${limite} min aujourd’hui.`);
        }
      }
    }, 60000);

    const wbBtn = document.createElement('button');
    wbBtn.id = 'wellbeing-item-622';
    wbBtn.type = 'button';
    wbBtn.textContent = '⏳ Temps d’écran (Bien-être)';
    wbBtn.style.cssText = 'text-align:left; padding:12px; background:#222533; border:none; border-radius:10px; color:#fff; font-weight:bold;';

    wbBtn.onclick = () => {
      document.getElementById('tiktok-profile-menu-509').style.display = 'none';
      const minsAujourdhui = parseInt(localStorage.getItem(todayKey) || '1', 10);
      const limiteActuelle = localStorage.getItem('fasotok_screen_limit_622') || 'Aucune';

      const nouvelleLimite = prompt(
        `⏳ TEMPS D'ÉCRAN FASOTOK 🇧🇫\n\n` +
        `• Temps passé aujourd'hui : ${minsAujourdhui} minute(s)\n` +
        `• Limite quotidienne actuelle : ${limiteActuelle} min\n\n` +
        `Entre une nouvelle limite en minutes (ex: 30) ou 0 pour désactiver :`,
        limiteActuelle === 'Aucune' ? '30' : limiteActuelle
      );

      if (nouvelleLimite !== null) {
        const val = parseInt(nouvelleLimite, 10);
        if (!isNaN(val) && val > 0) {
          localStorage.setItem('fasotok_screen_limit_622', val);
          if (window.fasotokNotify) window.fasotokNotify(`Limite fixée à ${val} min/jour.`);
        } else {
          localStorage.removeItem('fasotok_screen_limit_622');
          if (window.fasotokNotify) window.fasotokNotify('Limite de temps désactivée.');
        }
      }
    };

    burgerList.appendChild(wbBtn);
  });
});
