// --- 626. STICKER SONDAGE INTERACTIF (📊) DANS L'ÉCRAN PUBLIER (+) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_626_PUBLISH_INTERACTIVE_POLL_STICKER', () => {
    const quickTagsRow = document.getElementById('tiktok-publish-ui-566');
    const videoFeed = document.getElementById('video-feed');
    if (!quickTagsRow || !videoFeed || document.getElementById('add-poll-btn-626')) return;

    let sondageEnAttente = null;

    const pollBtn = document.createElement('button');
    pollBtn.id = 'add-poll-btn-626';
    pollBtn.type = 'button';
    pollBtn.textContent = '📊 Sondage';
    pollBtn.style.cssText = 'background:#1c1c29; border:1px solid #25f4ee; color:#25f4ee; padding:6px 12px; border-radius:6px; font-size:12px; font-weight:bold;';

    pollBtn.onclick = () => {
      const q = prompt('📊 Question du sondage (ex: Ouaga ou Bobo ?) :');
      if (!q || q.trim().length < 2) return;
      const opt1 = prompt('1️⃣ Premier choix :', 'Ouaga 🔥') || 'Oui';
      const opt2 = prompt('2️⃣ Deuxième choix :', 'Bobo 🌴') || 'Non';

      sondageEnAttente = { q: q.trim(), opt1: opt1.trim(), opt2: opt2.trim() };
      pollBtn.textContent = '📊 Sondage prêt ✓';
      if (window.fasotokNotify) window.fasotokNotify('Sondage attaché à ta prochaine publication !');
    };

    quickTagsRow.appendChild(pollBtn);

    // Coller le sondage interactif sur la publication dès qu'elle est ajoutée
    const obsPoll = new MutationObserver(() => {
      if (!sondageEnAttente || !videoFeed.firstElementChild) return;
      const carte = videoFeed.firstElementChild;
      if (carte.dataset.pollAttached626 === 'true') return;
      carte.dataset.pollAttached626 = 'true';

      const data = sondageEnAttente;
      sondageEnAttente = null;
      pollBtn.textContent = '📊 Sondage';

      const box = document.createElement('div');
      box.style.cssText = `
        position: absolute; top: 32%; left: 50%; transform: translateX(-50%);
        width: 76%; max-width: 270px; background: rgba(20, 20, 30, 0.9);
        border: 1px solid rgba(255,255,255,0.2); border-radius: 14px;
        padding: 12px; color: #fff; z-index: 20; text-align: center;
      `;
      box.innerHTML = `
        <p style="font-weight:bold; font-size:13px; margin-bottom:8px;">📊 ${data.q}</p>
        <button type="button" data-vote="1" style="width:100%; padding:7px; margin-bottom:6px; border-radius:8px; border:1px solid #444; background:#222533; color:#fff; font-weight:bold; font-size:12px;">${data.opt1}</button>
        <button type="button" data-vote="2" style="width:100%; padding:7px; border-radius:8px; border:1px solid #444; background:#222533; color:#fff; font-weight:bold; font-size:12px;">${data.opt2}</button>
      `;

      let voted = false;
      box.querySelectorAll('button').forEach((b) => {
        b.onclick = (ev) => {
          ev.stopPropagation();
          if (voted) return;
          voted = true;
          const choix = b.getAttribute('data-vote');
          const btns = box.querySelectorAll('button');
          btns.textContent = `${data.opt1} — ${choix === '1' ? '65%' : '35%'}`;
          btns.textContent = `${data.opt2} — ${choix === '2' ? '65%' : '35%'}`;
          b.style.background = '#fe2c55';
          b.style.borderColor = '#fe2c55';
        };
      });

      carte.appendChild(box);
    });
    obsPoll.observe(videoFeed, { childList: true });
  });
});
