// --- 631. GESTION DES COMPTES BLOQUÉS DANS PARAMÈTRES (STYLE TIKTOK) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_631_SETTINGS_BLOCKED_ACCOUNTS', () => {
    const dataSaverRow = document.getElementById('data-saver-row-630');
    const videoFeed = document.getElementById('video-feed');
    if (!dataSaverRow || document.getElementById('blocked-acc-btn-631')) return;

    const masquerComptesBloques = () => {
      if (!videoFeed) return;
      const bloques = JSON.parse(localStorage.getItem('fasotok_blocked_users_631') || '[]');
      videoFeed.querySelectorAll('.video-item').forEach((carte) => {
        const auteur = (carte.querySelector('.post-caption strong')?.textContent || '').toLowerCase();
        const estBloque = bloques.some((b) => auteur.includes(b.toLowerCase()));
        if (estBloque) carte.style.display = 'none';
      });
    };
    masquerComptesBloques();
    setInterval(masquerComptesBloques, 2000);

    const blockBtn = document.createElement('button');
    blockBtn.id = 'blocked-acc-btn-631';
    blockBtn.type = 'button';
    blockBtn.textContent = '🚫 Comptes bloqués';
    blockBtn.className = 'secondary-action';
    blockBtn.style.cssText = 'width: 100%; margin-top: 10px; font-size: 12px;';

    blockBtn.addEventListener('click', () => {
      let bloques = JSON.parse(localStorage.getItem('fasotok_blocked_users_631') || '[]');
      const listeTxt = bloques.length ? bloques.join(', ') : 'Aucun compte bloqué';
      const action = prompt(
        `🚫 COMPTES BLOQUÉS :\n${listeTxt}\n\n` +
        `Entre un @pseudo à bloquer (ou tape "DEBLOQUER" pour vider la liste) :`
      );
      if (!action || !action.trim()) return;

      if (action.trim().toUpperCase() === 'DEBLOQUER') {
        localStorage.removeItem('fasotok_blocked_users_631');
        if (window.fasotokNotify) window.fasotokNotify('Liste des comptes bloqués vidée.');
      } else {
        const propre = action.trim().replace(/^@+/, '');
        if (!bloques.includes(propre)) bloques.push(propre);
        localStorage.setItem('fasotok_blocked_users_631', JSON.stringify(bloques));
        masquerComptesBloques();
        if (window.fasotokNotify) window.fasotokNotify(`🚫 @${propre} a été bloqué.`);
      }
    });

    dataSaverRow.after(blockBtn);
  });
});

