// --- 633. ENREGISTRER UN SON EN FAVORI & LISTE DES SONS FAVORIS DANS MENU "☰" ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_633_FAVORITE_SOUNDS_MANAGER', () => {
    // 1. Ajouter le bouton "⭐ Ajouter aux favoris" dans la fiche audio (🎵)
    document.addEventListener('click', (e) => {
      if (!e.target?.textContent?.includes('🎵 Son original')) return;
      const titreSon = e.target.textContent.trim();

      setTimeout(() => {
        const sheet = document.getElementById('ft-sound-modal-528');
        const useBtn = document.getElementById('use-sound-528');
        if (!sheet || !useBtn || document.getElementById('fav-sound-btn-633')) return;

        let favSounds = JSON.parse(localStorage.getItem('fasotok_fav_sounds_633') || '[]');
        const estFav = favSounds.includes(titreSon);

        const favBtn = document.createElement('button');
        favBtn.id = 'fav-sound-btn-633';
        favBtn.type = 'button';
        favBtn.textContent = estFav ? '⭐ Son enregistré en favori' : '🔖 Ajouter aux sons favoris';
        favBtn.style.cssText = `
          width: 100%; padding: 11px; margin-bottom: 8px; border-radius: 12px;
          border: 1px solid #feca57; background: #1c1c29; color: #feca57; font-weight: bold;
        `;

        favBtn.onclick = () => {
          let liste = JSON.parse(localStorage.getItem('fasotok_fav_sounds_633') || '[]');
          if (liste.includes(titreSon)) {
            liste = liste.filter((s) => s !== titreSon);
            favBtn.textContent = '🔖 Ajouter aux sons favoris';
            if (window.fasotokNotify) window.fasotokNotify('Son retiré des favoris.');
          } else {
            liste.push(titreSon);
            favBtn.textContent = '⭐ Son enregistré en favori';
            if (window.fasotokNotify) window.fasotokNotify('⭐ Son ajouté à tes favoris !');
          }
          localStorage.setItem('fasotok_fav_sounds_633', JSON.stringify(liste));
        };

        useBtn.before(favBtn);
      }, 35);
    }, true);

    // 2. Ajouter le raccourci "🎵 Mes sons favoris" dans le Menu "☰" du Profil
    const burgerList = document.querySelector('#tiktok-profile-menu-509 div[style*="flex-direction:column"]');
    if (burgerList && !document.getElementById('fav-sounds-menu-633')) {
      const menuBtn = document.createElement('button');
      menuBtn.id = 'fav-sounds-menu-633';
      menuBtn.type = 'button';
      menuBtn.textContent = '🎵 Mes sons favoris';
      menuBtn.style.cssText = 'text-align:left; padding:12px; background:#222533; border:none; border-radius:10px; color:#fff; font-weight:bold;';

      menuBtn.onclick = () => {
        document.getElementById('tiktok-profile-menu-509').style.display = 'none';
        const liste = JSON.parse(localStorage.getItem('fasotok_fav_sounds_633') || '[]');
        if (!liste.length) {
          alert('🎵 Tu n’as enregistré aucun son favori pour le moment.\nAppuie sur la musique en bas d’une vidéo pour l’enregistrer !');
          return;
        }
        alert('🎵 TES SONS FAVORIS FASOTOK :\n\n' + liste.map((s, i) => `${i + 1}. ${s}`).join('\n'));
      };

      burgerList.appendChild(menuBtn);
    }
  });
});

