// --- 637. PROGRAMMER UN RAPPEL DE PUBLICATION DANS L'ÉCRAN PUBLIER (+) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_637_PUBLISH_SCHEDULE_REMINDER', () => {
    const filterRow = document.getElementById('filter-com-row-635');
    if (!filterRow || document.getElementById('schedule-row-637')) return;

    const schedRow = document.createElement('div');
    schedRow.id = 'schedule-row-637';
    schedRow.style.cssText = 'display:flex; justify-content:space-between; align-items:center; font-size:13px;';
    schedRow.innerHTML = `
      <span>⏰ Rappel de publication</span>
      <input type="time" id="schedule-time-637" style="background:#1c1c29; border:1px solid #333; color:#25f4ee; border-radius:6px; padding:3px 6px; font-size:12px;">
    `;

    filterRow.after(schedRow);

    const timeInput = document.getElementById('schedule-time-637');
    timeInput.addEventListener('change', () => {
      if (timeInput.value) {
        localStorage.setItem('fasotok_publish_reminder_637', timeInput.value);
        if (window.fasotokNotify) window.fasotokNotify(`⏰ Rappel programmé pour ${timeInput.value} !`);
      }
    });

    // Vérifier toutes les 30 secondes si l'heure du rappel est atteinte
    setInterval(() => {
      const cible = localStorage.getItem('fasotok_publish_reminder_637');
      if (!cible) return;
      const maintenant = new Date().toTimeString().slice(0, 5);
      if (maintenant === cible) {
        localStorage.removeItem('fasotok_publish_reminder_637');
        if (window.fasotokNotify) window.fasotokNotify(`🎬 C'est l'heure (${cible}) de publier ta vidéo sur FasoTok !`);
      }
    }, 30000);
  });
});

