// --- 643. COPIER UN COMMENTAIRE EN 1 CLIC DANS LE TIROIR (💬) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_643_COPY_COMMENT_IN_DRAWER', () => {
    const commentsList = document.getElementById('drawer-comments-list');
    if (!commentsList) return;

    const ajouterBoutonCopierCom = () => {
      commentsList.querySelectorAll('div').forEach((item) => {
        if (item.dataset.copyReady643 === 'true' || !item.querySelector('p')) return;
        item.dataset.copyReady643 = 'true';

        const copyBtn = document.createElement('button');
        copyBtn.type = 'button';
        copyBtn.textContent = '📋';
        copyBtn.title = 'Copier ce commentaire';
        copyBtn.style.cssText = 'background:none; border:none; font-size:13px; float:right; margin-right:6px; cursor:pointer; opacity:0.8;';

        copyBtn.addEventListener('click', async () => {
          const texte = item.querySelector('p')?.textContent?.trim() || '';
          if (texte && navigator.clipboard) {
            await navigator.clipboard.writeText(texte);
            if (window.fasotokNotify) window.fasotokNotify('Commentaire copié !');
          }
        });

        item.prepend(copyBtn);
      });
    };

    ajouterBoutonCopierCom();
    setInterval(ajouterBoutonCopierCom, 1200);
  });
});

