// --- 649. BANDEAU DE SOUS-TITRES / TEXTE À L'ÉCRAN DANS L'ÉCRAN PUBLIER (+) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_649_PUBLISH_ONSCREEN_CAPTIONS', () => {
    const quickTagsRow = document.getElementById('tiktok-publish-ui-566');
    const videoFeed = document.getElementById('video-feed');
    if (!quickTagsRow || !videoFeed || document.getElementById('add-subtitles-btn-649')) return;

    let sousTitreEnAttente = '';

    const subBtn = document.createElement('button');
    subBtn.id = 'add-subtitles-btn-649';
    subBtn.type = 'button';
    subBtn.textContent = '📝 Sous-titres';
    subBtn.style.cssText = 'background:#1c1c29; border:1px solid #fff; color:#fff; padding:6px 12px; border-radius:6px; font-size:12px; font-weight:bold;';

    subBtn.onclick = () => {
      const texte = prompt('📝 Écris le texte ou sous-titre à afficher sur ta vidéo :', sousTitreEnAttente);
      if (texte !== null) {
        sousTitreEnAttente = texte.trim();
        subBtn.textContent = sousTitreEnAttente ? '📝 Sous-titres ✓' : '📝 Sous-titres';
        if (sousTitreEnAttente && window.fasotokNotify) {
          window.fasotokNotify('Sous-titre prêt pour ta prochaine publication !');
        }
      }
    };

    quickTagsRow.appendChild(subBtn);

    // Afficher le bandeau de sous-titres propre sur la publication ajoutée
    const obsSub = new MutationObserver(() => {
      if (!sousTitreEnAttente || !videoFeed.firstElementChild) return;
      const carte = videoFeed.firstElementChild;
      if (carte.dataset.subApplied649 === 'true') return;
      carte.dataset.subApplied649 = 'true';

      const texteFinal = sousTitreEnAttente;
      sousTitreEnAttente = '';
      subBtn.textContent = '📝 Sous-titres';

      const banner = document.createElement('div');
      banner.style.cssText = `
        position: absolute; top: 18%; left: 50%; transform: translateX(-50%);
        background: rgba(0, 0, 0, 0.78); color: #ffffff; font-weight: 800;
        font-size: 14px; padding: 7px 14px; border-radius: 10px;
        text-align: center; max-width: 82%; z-index: 18; pointer-events: none;
      `;
      banner.textContent = texteFinal;
      carte.appendChild(banner);
    });
    obsSub.observe(videoFeed, { childList: true });
  });
});

