// --- 651. COULEUR DU FOND DES SOUS-TITRES DANS L'ÉCRAN PUBLIER (+) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_651_PUBLISH_CAPTION_STYLE_PICKER', () => {
    const subBtn = document.getElementById('add-subtitles-btn-649');
    const videoFeed = document.getElementById('video-feed');
    if (!subBtn || !videoFeed || document.getElementById('sub-style-btn-651')) return;

    const styles = [
      { label: '⬛ Noir', bg: 'rgba(0, 0, 0, 0.78)', color: '#ffffff' },
      { label: '🟥 TikTok', bg: '#fe2c55', color: '#ffffff' },
      { label: '⬜ Blanc', bg: '#ffffff', color: '#090910' }
    ];
    let idx = 0;

    const styleBtn = document.createElement('button');
    styleBtn.id = 'sub-style-btn-651';
    styleBtn.type = 'button';
    styleBtn.textContent = styles[0].label;
    styleBtn.style.cssText = 'background:#1c1c29; border:1px solid #444; color:#ddd; padding:6px 10px; border-radius:6px; font-size:11px; font-weight:bold;';

    styleBtn.onclick = () => {
      idx = (idx + 1) % styles.length;
      styleBtn.textContent = styles[idx].label;
    };

    subBtn.after(styleBtn);

    const obsStyle = new MutationObserver(() => {
      const carte = videoFeed.firstElementChild;
      const banner = carte?.querySelector('div[style*="top: 18%"]');
      if (banner && !banner.dataset.styled651) {
        banner.dataset.styled651 = 'true';
        banner.style.background = styles[idx].bg;
        banner.style.color = styles[idx].color;
      }
    });
    obsStyle.observe(videoFeed, { childList: true, subtree: true });
  });
});

// --- 652. BARRE HORIZONTALE D'AMIS EN HAUT DE "BOÎTE -> MESSAGES" ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_652_INBOX_FRIENDS_AVATAR_STRIP', () => {
    const dmBox = document.getElementById('ft-dm-box-577');
    if (!dmBox || document.getElementById('ft-dm-friends-strip-652')) return;

    const strip = document.createElement('div');
    strip.id = 'ft-dm-friends-strip-652';
    strip.style.cssText = 'display: flex; gap: 10px; overflow-x: auto; padding-bottom: 6px; border-bottom: 1px solid rgba(255,255,255,0.08);';

    const majListeAmis = () => {
      const suivis = JSON.parse(localStorage.getItem('fasotok_abonnements') || '["@OuagaVibes226", "@EtalonsFoot"]');
      strip.innerHTML = suivis.map((pseudo) => `
        <button type="button" data-chat-user="${pseudo}" style="background:none; border:none; color:#fff; display:flex; flex-direction:column; align-items:center; gap:4px; min-width:62px; cursor:pointer;">
          <span style="width:42px; height:42px; border-radius:50%; background:linear-gradient(135deg,#fe2c55,#25f4ee); display:flex; align-items:center; justify-content:center; font-size:18px;">👤</span>
          <small style="font-size:10px; max-width:60px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${pseudo}</small>
        </button>
      `).join('');

      strip.querySelectorAll('button').forEach((btn) => {
        btn.onclick = () => {
          const nom = btn.getAttribute('data-chat-user');
          const header = dmBox.querySelector('strong');
          if (header) header.textContent = nom;
          if (window.fasotokNotify) window.fasotokNotify(`Discussion ouverte avec ${nom}`);
        };
      });
    };

    dmBox.prepend(strip);
    majListeAmis();
    setInterval(majListeAmis, 3000);
  });
});
// --- 653. CAPSULE VOCALE (🎤 AUDIO) DANS "BOÎTE -> MESSAGES" ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_653_INBOX_VOICE_NOTE_CAPSULE', () => {
    const dmForm = document.getElementById('ft-dm-form-577');
    const historyBox = document.getElementById('ft-dm-history-577');
    if (!dmForm || !historyBox || document.getElementById('ft-voice-btn-653')) return;

    const voiceBtn = document.createElement('button');
    voiceBtn.id = 'ft-voice-btn-653';
    voiceBtn.type = 'button';
    voiceBtn.textContent = '🎤';
    voiceBtn.title = 'Envoyer une note vocale';
    voiceBtn.style.cssText = 'background:#1c1c29; border:1px solid #333; border-radius:50%; width:38px; height:38px; font-size:16px; flex-shrink:0;';

    voiceBtn.addEventListener('click', () => {
      const duree = Math.floor(Math.random() * 14) + 3;
      const bulleAudio = `<span style="display:inline-flex; align-items:center; gap:6px; font-weight:bold;">▶️ ılılılılılı • 0:${duree < 10 ? '0' + duree : duree}</span>`;

      const msgs = JSON.parse(localStorage.getItem('fasotok_dm_messages') || '[]');
      msgs.push({ from: 'me', text: bulleAudio });
      localStorage.setItem('fasotok_dm_messages', JSON.stringify(msgs));

      historyBox.innerHTML = msgs.map((m) => `
        <div style="
          align-self: ${m.from === 'me' ? 'flex-end' : 'flex-start'};
          background: ${m.from === 'me' ? '#fe2c55' : '#1c1c29'};
          color: #fff; padding: 9px 13px; border-radius: 16px;
          max-width: 80%; font-size: 13px; line-height: 1.4;
        ">${m.text}</div>
      `).join('');
      historyBox.scrollTop = historyBox.scrollHeight;
      if (window.fasotokNotify) window.fasotokNotify('🎤 Note vocale envoyée !');
    });

    dmForm.appendChild(voiceBtn);
  });
});

