// --- 655. OPTION "PASSER EN PRIVÉ (🔒)" DANS LA FEUILLE PARTAGER (↪️) ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_655_MOVE_VIDEO_TO_PRIVATE_TAB', () => {
    const chargerGrillePrivee = () => {
      const privateGrid = document.getElementById('profile-private-grid-654');
      if (!privateGrid) return;

      const privateIds = JSON.parse(localStorage.getItem('fasotok_private_posts_655') || '[]');
      const cartes = Array.from(document.querySelectorAll('#video-feed .video-item'));

      cartes.forEach((c) => {
        if (privateIds.includes(c.dataset.postId)) c.style.display = 'none';
      });

      const privees = cartes.filter((c) => privateIds.includes(c.dataset.postId));
      if (!privees.length) return;

      privateGrid.innerHTML = '';
      privees.forEach((carte) => {
        const media = carte.querySelector('.post-media');
        if (!media) return;
        const cell = document.createElement('div');
        cell.style.cssText = 'aspect-ratio: 9/16; background: #111; border-radius: 6px; overflow: hidden;';
        cell.innerHTML = media.tagName === 'VIDEO'
          ? `<video src="${media.src}" muted style="width:100%; height:100%; object-fit:cover;"></video>`
          : `<img src="${media.src}" style="width:100%; height:100%; object-fit:cover;">`;
        privateGrid.appendChild(cell);
      });
    };
    setTimeout(chargerGrillePrivee, 1500);

    document.addEventListener('click', (e) => {
      const shareBtn = e.target.closest('.share-btn');
      if (!shareBtn) return;

      const carte = shareBtn.closest('.video-item');
      const postId = carte?.dataset.postId || '';
      if (!postId) return;

      setTimeout(() => {
        const sheet = document.getElementById('ft-share-sheet-532');
        const list = sheet?.querySelector('div[style*="flex-direction:column"]');
        if (!list || document.getElementById('make-private-655')) return;

        const privBtn = document.createElement('button');
        privBtn.id = 'make-private-655';
        privBtn.type = 'button';
        privBtn.textContent = '🔒 Passer cette vidéo en privé';
        privBtn.style.cssText = 'text-align:left; padding:12px; background:#222533; border:none; border-radius:10px; color:#ccc; font-weight:bold;';

        privBtn.onclick = () => {
          sheet.remove();
          let liste = JSON.parse(localStorage.getItem('fasotok_private_posts_655') || '[]');
          if (!liste.includes(postId)) liste.push(postId);
          localStorage.setItem('fasotok_private_posts_655', JSON.stringify(liste));
          carte.style.display = 'none';
          chargerGrillePrivee();
          if (window.fasotokNotify) window.fasotokNotify('🔒 Vidéo déplacée dans ton onglet Privé.');
        };

        list.appendChild(privBtn);
      }, 35);
    }, true);
  });
});

