// --- 657. REMETTRE UNE VIDÉO PRIVÉE EN PUBLIC DEPUIS L'ONGLET 🔒 DU PROFIL ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_657_RESTORE_PRIVATE_VIDEO_TO_PUBLIC', () => {
    const privateGrid = document.getElementById('profile-private-grid-654');
    if (!privateGrid) return;

    privateGrid.addEventListener('click', (e) => {
      const cell = e.target.closest('div');
      const media = cell?.querySelector('video, img');
      if (!media || !media.src) return;

      if (confirm('🌍 Veux-tu remettre cette vidéo privée en mode Public sur ton fil ?')) {
        const cartes = Array.from(document.querySelectorAll('#video-feed .video-item'));
        const cible = cartes.find((c) => c.querySelector('.post-media')?.src === media.src);

        if (cible) {
          cible.style.display = 'block';
          const postId = cible.dataset.postId || '';
          let liste = JSON.parse(localStorage.getItem('fasotok_private_posts_655') || '[]');
          liste = liste.filter((id) => id !== postId);
          localStorage.setItem('fasotok_private_posts_655', JSON.stringify(liste));
        }

        cell.remove();
        if (!privateGrid.children.length) {
          privateGrid.innerHTML = '<p style="grid-column:1/-1; color:#888; font-size:13px; padding:12px 0;">🔒 Aucune vidéo privée.</p>';
        }
        if (window.fasotokNotify) window.fasotokNotify('🌍 Vidéo remise en public !');
      }
    });
  });
});

