// --- 688. COPIER LE LIEN D'UNE PLAYLIST AU CLIC SUR LE PROFIL ---
window.addEventListener('load', () => {
  window.registerFasoTokModule('MOD_688_PROFILE_PLAYLIST_SHARE_LINK', () => {
    const playlistsBar = document.getElementById('ft-playlists-bar-614');
    if (!playlistsBar) return;

    playlistsBar.addEventListener('click', async (e) => {
      const chip = e.target.closest('button');
      if (!chip || chip.id === 'add-pl-614') return;

      const nomPlaylist = chip.textContent.replace('📂 ', '').trim();
      const pseudo = localStorage.getItem('fasotok_user') || 'MonProfil';
      const lien = `${window.location.origin}/?u=${encodeURIComponent(pseudo)}&playlist=${encodeURIComponent(nomPlaylist)}`;

      if (navigator.clipboard) {
        await navigator.clipboard.writeText(lien);
      }
      if (window.fasotokNotify) {
        window.fasotokNotify(`🔗 Lien de la playlist "${nomPlaylist}" copié !`);
      }
    });
  });
});
