// --- 671. BLOC-NOTES D'IDÉES DE VIDÉOS DANS LE STUDIO CRÉATEUR ---
window.addEventListener('load', function () {
  window.registerFasoTokModule('MOD_671_STUDIO_CREATOR_IDEA_PAD', function () {
    var studioPage = document.getElementById('studio-page');
    var draftsWrap = document.getElementById('drafts-list');
    if (!studioPage || !draftsWrap || document.getElementById('studio-ideas-card-671')) return;

    var card = document.createElement('section');
    card.id = 'studio-ideas-card-671';
    card.className = 'panel-card';
    card.style.marginTop = '16px';
    card.innerHTML = '<h2>💡 Mes idées de vidéos</h2><div style="display:flex; gap:8px; margin:10px 0;"><input type="text" id="idea-input-671" placeholder="Ex: Scène humour au marché de Ouahigouya..." style="flex:1; padding:10px; border-radius:10px; border:1px solid #333; background:#14141e; color:#fff; font-size:12px;"><button type="button" id="add-idea-btn-671" style="background:#fe2c55; color:#fff; border:none; border-radius:10px; padding:0 14px; font-weight:bold;">+</button></div><div id="ideas-list-671" style="display:flex; flex-direction:column; gap:8px;"></div>';

    var parentCard = draftsWrap.closest('.panel-card');
    if (parentCard) parentCard.after(card);

    var listEl = document.getElementById('ideas-list-671');
    var inputEl = document.getElementById('idea-input-671');

    function renderIdeas() {
      var ideas = JSON.parse(localStorage.getItem('fasotok_creator_ideas_671') || '[]');
      listEl.innerHTML = ideas.length
        ? ideas.map(function (txt, i) {
            return '<div style="display:flex; justify-content:space-between; align-items:center; padding:8px 10px; background:#1c1c29; border-radius:10px; font-size:12px;"><span>💡 ' + txt + '</span><div style="display:flex; gap:6px;"><button type="button" data-use-idea="' + i + '" style="background:#25f4ee; color:#000; border:none; border-radius:6px; padding:3px 8px; font-weight:bold; font-size:11px;">Créer</button><button type="button" data-del-idea="' + i + '" style="background:#2a2c38; color:#fff; border:none; border-radius:6px; padding:3px 7px; font-size:11px;">✕</button></div></div>';
          }).join('')
        : '<p class="muted" style="font-size:12px;">Aucune idée enregistrée.</p>';

      listEl.querySelectorAll('[data-use-idea]').forEach(function (b) {
        b.onclick = function () {
          var idx = parseInt(b.getAttribute('data-use-idea'), 10);
          var cap = document.getElementById('create-caption');
          var menu = document.getElementById('create-menu');
          if (cap) cap.value = ideas[idx] + ' #FasoTok';
          if (menu) menu.hidden = false;
        };
      });

      listEl.querySelectorAll('[data-del-idea]').forEach(function (b) {
        b.onclick = function () {
          var idx = parseInt(b.getAttribute('data-del-idea'), 10);
          ideas.splice(idx, 1);
          localStorage.setItem('fasotok_creator_ideas_671', JSON.stringify(ideas));
          renderIdeas();
        };
      });
    }

    document.getElementById('add-idea-btn-671').onclick = function () {
      var val = inputEl.value.trim();
      if (!val) return;
      var ideas = JSON.parse(localStorage.getItem('fasotok_creator_ideas_671') || '[]');
      ideas.unshift(val);
      localStorage.setItem('fasotok_creator_ideas_671', JSON.stringify(ideas));
      inputEl.value = '';
      renderIdeas();
    };

    renderIdeas();
  });
});

