// --- 673. CLOCHE DE CRÉATEUR FAVORI (🔔) DANS L'ONGLET "AMIS" ---
window.addEventListener('load', function () {
  window.registerFasoTokModule('MOD_673_FRIENDS_CREATOR_BELL_ALERT', function () {
    var friendsList = document.getElementById('friends-list');
    if (!friendsList) return;

    function ajouterClochesAmis() {
      var favCreators = JSON.parse(localStorage.getItem('fasotok_bell_creators_673') || '[]');
      friendsList.querySelectorAll('div').forEach(function (row) {
        if (row.dataset.bellReady673 === 'true') return;
        var strongEl = row.querySelector('strong');
        var pseudo = strongEl ? strongEl.textContent.trim() : '';
        if (!pseudo) return;
        row.dataset.bellReady673 = 'true';

        var actif = favCreators.indexOf(pseudo) !== -1;
        var bellBtn = document.createElement('button');
        bellBtn.type = 'button';
        bellBtn.textContent = actif ? '🔔' : '🔕';
        bellBtn.title = 'Alertes de publication';
        bellBtn.style.cssText = 'background:none; border:none; font-size:15px; margin-left:6px; cursor:pointer;';

        bellBtn.addEventListener('click', function () {
          var liste = JSON.parse(localStorage.getItem('fasotok_bell_creators_673') || '[]');
          if (liste.indexOf(pseudo) !== -1) {
            liste = liste.filter(function (p) { return p !== pseudo; });
            actif = false;
          } else {
            liste.push(pseudo);
            actif = true;
          }
          localStorage.setItem('fasotok_bell_creators_673', JSON.stringify(liste));
          bellBtn.textContent = actif ? '🔔' : '🔕';
          if (window.fasotokNotify) {
            window.fasotokNotify(actif ? '🔔 Alertes activées pour ' + pseudo : '🔕 Alertes coupées pour ' + pseudo);
          }
        });

        row.appendChild(bellBtn);
      });
    }

    ajouterClochesAmis();
    setInterval(ajouterClochesAmis, 1500);
  });
});

