window.addEventListener('load', function () {
  window.registerFasoTokModule('MOD_676_PROFILE_FAVORITES_COLLECTIONS', function () {
    var favGrid = document.getElementById('profile-favs-grid');
    if (!favGrid || document.getElementById('fav-collections-bar-676')) return;

    var colBar = document.createElement('div');
    colBar.id = 'fav-collections-bar-676';
    colBar.style.cssText = 'grid-column:1 / -1; display:flex; gap:6px; overflow-x:auto; margin-bottom:8px; padding-bottom:4px;';

    function renderCollections() {
      var cols = JSON.parse(localStorage.getItem('fasotok_fav_collections_676') || '["⭐ Tous les favoris"]');
      colBar.innerHTML = '<button type="button" id="new-col-btn-676" style="background:#1c1c29; border:1px dashed #feca57; color:#feca57; padding:4px 10px; border-radius:12px; font-size:11px; font-weight:bold; white-space:nowrap;">+ Collection</button>';

      cols.forEach(function (nom) {
        var chip = document.createElement('span');
        chip.textContent = '📁 ' + nom;
        chip.style.cssText = 'background:#1c1c29; border:1px solid #333; color:#ddd; padding:4px 10px; border-radius:12px; font-size:11px; white-space:nowrap;';
        colBar.appendChild(chip);
      });

      document.getElementById('new-col-btn-676').onclick = function () {
        var nom = prompt('📁 Nom de la nouvelle collection de favoris (ex: Humour 226) :');
        if (!nom || nom.trim().length < 2) return;
        var actuelles = JSON.parse(localStorage.getItem('fasotok_fav_collections_676') || '["⭐ Tous les favoris"]');
        actuelles.push(nom.trim());
        localStorage.setItem('fasotok_fav_collections_676', JSON.stringify(actuelles));
        renderCollections();
      };
    }

    var observerFav = new MutationObserver(function () {
      if (favGrid.style.display === 'grid' && !favGrid.contains(colBar)) {
        favGrid.prepend(colBar);
        renderCollections();
      }
    });
    observerFav.observe(favGrid, { attributes: true, attributeFilter: ['style'] });
  });
});

