window.addEventListener('load', function () {
  window.registerFasoTokModule('MOD_679_STUDIO_WEEKLY_CREATOR_GOAL', function () {
    var ideasCard = document.getElementById('studio-ideas-card-671');
    if (!ideasCard || document.getElementById('studio-goal-card-679')) return;

    var goalCard = document.createElement('section');
    goalCard.id = 'studio-goal-card-679';
    goalCard.className = 'panel-card';
    goalCard.style.marginTop = '16px';

    function majObjectif() {
      var cible = parseInt(localStorage.getItem('fasotok_weekly_goal_679') || '3', 10);
      var publiees = document.querySelectorAll('#my-videos-grid > div').length;
      var pct = Math.min(100, Math.round((publiees / cible) * 100));

      goalCard.innerHTML = '<div style="display:flex; justify-content:space-between; align-items:center;"><h2>🎯 Objectif créateur</h2><button type="button" id="edit-goal-btn-679" style="background:#1c1c29; border:1px solid #333; color:#25f4ee; padding:4px 10px; border-radius:8px; font-size:11px; font-weight:bold;">Modifier</button></div><p style="font-size:12px; color:#aaa; margin:8px 0;">Progression : <strong>' + publiees + ' / ' + cible + '</strong> vidéo(s) publiée(s) (' + pct + '%)</p><div style="width:100%; height:8px; background:#1c1c29; border-radius:8px; overflow:hidden;"><div style="width:' + pct + '%; height:100%; background:linear-gradient(90deg, #fe2c55, #25f4ee);"></div></div>';

      document.getElementById('edit-goal-btn-679').onclick = function () {
        var val = prompt('🎯 Combien de vidéos souhaites-tu publier cette semaine ?', cible);
        var num = parseInt(val, 10);
        if (!isNaN(num) && num > 0) {
          localStorage.setItem('fasotok_weekly_goal_679', num);
          majObjectif();
          if (window.fasotokNotify) window.fasotokNotify('Objectif fixé à ' + num + ' vidéo(s) !');
        }
      };
    }

    ideasCard.after(goalCard);
    majObjectif();
    setInterval(majObjectif, 3000);
  });
});

