// --- 688. COPIER LE LIEN D'UNE PLAYLIST AU CLIC SUR LE PROFIL ---
window.addEventListener('load', function () {
  window.registerFasoTokModule('MOD_688_PROFILE_PLAYLIST_SHARE_LINK', function () {
    var playlistsBar = document.getElementById('ft-playlists-bar-614');
    if (!playlistsBar) return;

    playlistsBar.addEventListener('click', function (e) {
      var chip = e.target.closest('button');
      if (!chip || chip.id === 'add-pl-614') return;

      var nomPlaylist = chip.textContent.replace('📂 ', '').trim();
      var pseudo = localStorage.getItem('fasotok_user') || 'MonProfil';
      var lien = window.location.origin + '/?u=' + encodeURIComponent(pseudo) + '&playlist=' + encodeURIComponent(nomPlaylist);

      if (navigator.clipboard) {
        navigator.clipboard.writeText(lien);
      }
      if (window.fasotokNotify) {
        window.fasotokNotify('🔗 Lien de la playlist "' + nomPlaylist + '" copié !');
      }
    });
  });
});

