// --- 701. VRAI STUDIO & SALON LIVE TIKTOK AVEC CAMÉRA DU TÉLÉPHONE ---
window.addEventListener('load', function () {
  window.registerFasoTokModule('MOD_701_REAL_CAMERA_TIKTOK_LIVE_STUDIO', function () {
    var fluxCamera = null;
    var facingMode = 'user';
    var timerSpectateurs = null;
    var debutLive = 0;
    var totalCoeursLive = 0;
    var totalSpectateursMax = 18;

    function arreterCamera() {
      if (fluxCamera) {
        fluxCamera.getTracks().forEach(function (track) { track.stop(); });
        fluxCamera = null;
      }
      clearInterval(timerSpectateurs);
    }

    function demarrerFluxVideo(videoEl) {
      arreterCamera();
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        return;
      }
      navigator.mediaDevices.getUserMedia({
        video: { facingMode: facingMode },
        audio: false
      }).then(function (stream) {
        fluxCamera = stream;
        videoEl.srcObject = stream;
        videoEl.play().catch(function () {});
      }).catch(function () {
        if (window.fasotokNotify) {
          window.fasotokNotify('📷 Caméra non autorisée : mode aperçu studio activé.');
        }
      });
    }

    window.ouvrirStudioLiveFasoTok = function () {
      if (document.getElementById('ft-live-studio-701')) return;

      // Fermer le menu "+" s'il était ouvert
      var createMenu = document.getElementById('create-menu');
      if (createMenu) createMenu.hidden = true;

      var pseudo = localStorage.getItem('fasotok_user') || 'FasoCreateur';
      var enDirect = false;
      totalCoeursLive = 0;
      totalSpectateursMax = 18;

      var modal = document.createElement('div');
      modal.id = 'ft-live-studio-701';
      modal.style.cssText = 'position:fixed; inset:0; z-index:30000; background:#090910; color:#fff; display:flex; flex-direction:column; justify-content:space-between; overflow:hidden;';

      modal.innerHTML =
        '<video id="ft-live-cam-701" autoplay playsinline muted style="position:absolute; inset:0; width:100%; height:100%; object-fit:cover; background:radial-gradient(circle, #2b1025, #090910);"></video>' +
        '<div style="position:relative; z-index:10; padding:16px; display:flex; justify-content:space-between; align-items:center; background:linear-gradient(to bottom, rgba(0,0,0,0.75), transparent);">' +
          '<button type="button" id="close-live-701" style="background:rgba(0,0,0,0.55); border:none; color:#fff; width:36px; height:36px; border-radius:50%; font-size:18px;">✕</button>' +
          '<div id="live-status-pill-701" style="background:rgba(0,0,0,0.65); padding:5px 12px; border-radius:20px; font-size:12px; font-weight:bold;">🎥 Préparation LIVE</div>' +
          '<button type="button" id="flip-cam-701" style="background:rgba(0,0,0,0.55); border:none; color:#fff; width:36px; height:36px; border-radius:50%; font-size:16px;" title="Retourner la caméra">🔄</button>' +
        '</div>' +
        '<div id="live-setup-box-701" style="position:relative; z-index:10; margin:auto 18px; background:rgba(20,20,30,0.88); border:1px solid rgba(255,255,255,0.15); border-radius:18px; padding:18px; text-align:center;">' +
          '<strong style="font-size:16px;">🔴 Passer en LIVE sur FasoTok</strong>' +
          '<input type="text" id="live-title-input-701" value="En direct depuis Ouahigouya 🇧🇫🔥" maxlength="50" style="width:100%; margin:12px 0; padding:10px 12px; border-radius:10px; border:1px solid #333; background:#14141e; color:#fff; font-size:13px;">' +
          '<button type="button" id="start-live-btn-701" style="width:100%; padding:13px; border:none; border-radius:25px; background:#fe2c55; color:#fff; font-weight:900; font-size:15px; cursor:pointer;">Passer en LIVE</button>' +
        '</div>' +
        '<div id="live-onair-ui-701" style="display:none; position:relative; z-index:10; padding:14px; background:linear-gradient(to top, rgba(0,0,0,0.85), transparent); flex-direction:column; gap:10px;">' +
          '<div id="live-comments-701" style="height:150px; overflow-y:auto; display:flex; flex-direction:column; gap:6px; font-size:12px;">' +
            '<div style="background:rgba(0,0,0,0.55); padding:6px 10px; border-radius:12px; align-self:flex-start;"><strong style="color:#25f4ee;">@OuagaVibes226 :</strong> Salut @' + pseudo + ' ! Force à toi 🇧🇫🔥</div>' +
          '</div>' +
          '<form id="live-chat-form-701" style="display:flex; gap:8px; align-items:center;">' +
            '<input type="text" id="live-chat-input-701" placeholder="Écrire un commentaire en direct..." style="flex:1; padding:10px 14px; border-radius:20px; border:none; background:rgba(255,255,255,0.18); color:#fff; font-size:13px;">' +
            '<button type="submit" style="background:#fe2c55; color:#fff; border:none; border-radius:20px; padding:10px 14px; font-weight:bold;">➤</button>' +
            '<button type="button" id="live-heart-btn-701" style="background:rgba(255,255,255,0.2); border:none; border-radius:50%; width:40px; height:40px; font-size:20px;">❤️</button>' +
          '</form>' +
        '</div>';

      document.body.appendChild(modal);

      var videoEl = document.getElementById('ft-live-cam-701');
      demarrerFluxVideo(videoEl);

      // Retourner caméra avant / arrière
      document.getElementById('flip-cam-701').onclick = function () {
        facingMode = facingMode === 'user' ? 'environment' : 'user';
        demarrerFluxVideo(videoEl);
      };

      // Lancer le direct
      document.getElementById('start-live-btn-701').onclick = function () {
        enDirect = true;
        debutLive = Date.now();
        var titreLive = document.getElementById('live-title-input-701').value.trim() || 'LIVE FasoTok 🇧🇫';
        document.getElementById('live-setup-box-701').style.display = 'none';
        document.getElementById('live-onair-ui-701').style.display = 'flex';

        var pill = document.getElementById('live-status-pill-701');
        pill.innerHTML = '<span style="background:#fe2c55; padding:2px 6px; border-radius:4px; margin-right:6px;">LIVE</span> 👁️ 18 • ' + titreLive.slice(0, 18);

        var messagesAuto = [
          { u: '@YatengaStar', t: 'L’image est super nette depuis le Yatenga ! 👏' },
          { u: '@BoboDance_Off', t: 'On est connecté avec toi 🔥💃' },
          { u: '@EtalonsFoot', t: '🎁 @EtalonsFoot t’a envoyé une Rose (+5 🪙) !' },
          { u: '@FasoFan226', t: 'Continue comme ça, c’est du lourd 🇧🇫❤️' }
        ];
        var idxMsg = 0;

        timerSpectateurs = setInterval(function () {
          var nb = Math.floor(Math.random() * 35) + 18;
          if (nb > totalSpectateursMax) totalSpectateursMax = nb;
          pill.innerHTML = '<span style="background:#fe2c55; padding:2px 6px; border-radius:4px; margin-right:6px;">LIVE</span> 👁️ ' + nb;

          var feed = document.getElementById('live-comments-701');
          if (feed && idxMsg < messagesAuto.length) {
            var item = messagesAuto[idxMsg];
            idxMsg++;
            var line = document.createElement('div');
            line.style.cssText = 'background:rgba(0,0,0,0.55); padding:6px 10px; border-radius:12px; align-self:flex-start;';
            line.innerHTML = '<strong style="color:#feca57;">' + item.u + ' :</strong> ' + item.t;
            feed.appendChild(line);
            feed.scrollTop = feed.scrollHeight;
          }
        }, 3500);
      };

      // Envoyer un message dans le chat LIVE
      document.getElementById('live-chat-form-701').onsubmit = function (e) {
        e.preventDefault();
        var inp = document.getElementById('live-chat-input-701');
        var txt = inp.value.trim();
        if (!txt) return;
        var feed = document.getElementById('live-comments-701');
        var line = document.createElement('div');
        line.style.cssText = 'background:rgba(254,44,85,0.45); padding:6px 10px; border-radius:12px; align-self:flex-start;';
        line.innerHTML = '<strong>@' + pseudo + ' :</strong> ' + txt;
        feed.appendChild(line);
        feed.scrollTop = feed.scrollHeight;
        inp.value = '';
      };

      // Envoyer des cœurs volants
      function envoyerCoeurLive() {
        totalCoeursLive++;
        var c = document.createElement('div');
        c.textContent = ['❤️', '🔥', '🇧🇫', '👏'][Math.floor(Math.random() * 4)];
        c.style.cssText = 'position:absolute; bottom:75px; right:' + (20 + Math.random() * 40) + 'px; font-size:26px; pointer-events:none; transition:all 1.2s ease-out; opacity:1; z-index:20;';
        modal.appendChild(c);
        setTimeout(function () {
          c.style.bottom = '360px';
          c.style.opacity = '0';
        }, 40);
        setTimeout(function () { c.remove(); }, 1300);
      }

      document.getElementById('live-heart-btn-701').onclick = envoyerCoeurLive;
      videoEl.onclick = envoyerCoeurLive;

      // Fermer le studio LIVE
      document.getElementById('close-live-701').onclick = function () {
        arreterCamera();
        modal.remove();
        if (enDirect && typeof window.afficherBilanLive702 === 'function') {
          var dureeSec = Math.max(5, Math.round((Date.now() - debutLive) / 1000));
          window.afficherBilanLive702(dureeSec, totalSpectateursMax, totalCoeursLive);
        }
      };
    };

    // Relier tous les boutons LIVE existants (menu "+" et onglet "LIVE" en haut)
    document.addEventListener('click', function (e) {
      if (e.target.closest('#create-live-btn') || e.target.closest('[data-feed-tab="live"]')) {
        e.preventDefault();
        e.stopImmediatePropagation();
        window.ouvrirStudioLiveFasoTok();
      }
    }, true);
  });
});

