        pinBanner.innerHTML = '<span>📌 <strong>Épinglé :</strong> ' + bulle.textContent + '</span><button type="button" id="unpin-live-708" style="background:none; border:none; color:#fe2c55; font-weight:bold;">✕</button>';

        onAirUi.prepend(pinBanner);
